    "error1800": "\u0939\u093E\u0925\u094B\u0902 \u0915\u093E \u0938\u0902\u0917\u094D\u0930\u0939 \u0938\u0940\u092E\u093E \u0938\u0947 \u0905\u0927\u093F\u0915 \u0939\u0948",
    "error1900": "\u0910\u0938\u093E \u0915\u094B\u0908 \u0917\u0947\u092E \u092A\u094D\u0930\u0915\u093E\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "error2000": "\u091C\u0948\u0915\u092A\u0949\u091F \u0915\u0949\u0928\u094D\u092B\u093C\u093F\u0917\u0930\u0947\u0936\u0928 \u0921\u0947\u091F\u093E \u0917\u0941\u092E \u0939\u0948",
    "error2001": "\u0930\u0942\u092E 1 \u092E\u093F\u0928\u091F \u092E\u0947\u0902 \u092C\u0902\u0926",
    "error2002": "\u0905\u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u0905\u0928\u0941\u092E\u0924\u093F\u092F\u093E\u0901",
    "error2003": "\u0917\u0947\u092E \u0938\u0930\u094D\u0935\u0930 \u0938\u0947 \u0915\u0928\u0947\u0915\u094D\u091F \u0915\u0930\u0928\u0947 \u092E\u0947\u0902 \u0905\u0938\u092E\u0930\u094D\u0925",
    "error2004": "\u0916\u093E\u0924\u093E \u092B\u093C\u094D\u0930\u0940\u091C\u093C \u0915\u0930 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
