    "error2006": "\u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u093E \u0915\u094D\u0932\u092C \u092C\u0902\u0926 \u0915\u0930 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
    "error2007": "\u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u093E \u0915\u094D\u0932\u092C \u092F\u0942\u0928\u093F\u092F\u0928 \u0938\u0947 \u092C\u0902\u0927\u093E \u0928\u0939\u0940\u0902 \u0939\u0948",
    "error2008": "\u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u093E \u0915\u094D\u0932\u092C \u0938\u094D\u0925\u093E\u0928\u093E\u0902\u0924\u0930\u093F\u0924 \u0915\u093F\u092F\u093E \u091C\u093E \u0930\u0939\u093E \u0939\u0948 \u092F\u093E \u092C\u093E\u0939\u0930 \u0915\u0930 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
    "error2009": "\u0909\u092A\u092F\u094B\u0917\u0915\u0930\u094D\u0924\u093E \u0915\u094B \u092C\u093E\u0939\u0930 \u0928\u093F\u0915\u093E\u0932 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
    "error2100": "\u0936\u0947\u092F\u0930\u093F\u0902\u0917 \u0926\u094D\u0935\u093E\u0930\u093E UC \u0905\u0930\u094D\u091C\u093F\u0924 \u0915\u0930\u0928\u0947 \u0915\u093E \u0915\u093E\u0930\u094D\u092F \u091A\u093E\u0932\u0942 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "error2101": "\u090F\u091C\u0947\u0902\u091F \u092C\u0928\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947 \u0915\u0943\u092A\u092F\u093E \u092A\u0939\u0932\u0947 \u0915\u094D\u0932\u092C \u092E\u0947\u0902 \u0936\u093E\u092E\u093F\u0932 \u0939\u094B\u0902",
    "error2103": "\u0906\u092E\u0902\u0924\u094D\u0930\u0923 \u0915\u094B\u0921 \u0917\u0932\u0924 \u0939\u0948, \u0915\u0943\u092A\u092F\u093E \u092A\u0941\u0928\u0903 \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902",
    "error2104": "\u0916\u093E\u0924\u0947 \u092E\u0947\u0902 UC \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u0905\u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u0939\u0948!",
    "error2105": "\u0906\u092A\u0915\u0947 \u0926\u094D\u0935\u093E\u0930\u093E \u0926\u0930\u094D\u091C \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u0926\u094D\u0935\u093F\u0924\u0940\u092F\u0915 \u092A\u093E\u0938\u0935\u0930\u094D\u0921 \u0917\u0932\u0924 \u0939\u0948",
    "error2106": "\u0906\u092E\u0902\u0924\u094D\u0930\u0923 \u0915\u094B\u0921 \u0930\u091C\u093F\u0938\u094D\u091F\u0930 \u0905\u0938\u092B\u093C\u0932!",
    "error2107": "\u0906\u092E\u0902\u0924\u094D\u0930\u0923 \u0915\u094B\u0921 \u0930\u091C\u093F\u0938\u094D\u091F\u0930 \u092A\u093E\u0930\u093F\u0924 \u0915\u093F\u092F\u093E \u0917\u092F\u093E",
