    "error2108": "\u092D\u0941\u0917\u0924\u093E\u0928 \u0906\u0926\u0947\u0936 \u092E\u094C\u091C\u0942\u0926 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "error2109": "\u0926\u0947\u0916\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0906\u092A\u0915\u093E \u090F\u091C\u0947\u0902\u091F \u0939\u094B\u0928\u093E \u0906\u0935\u0936\u094D\u092F\u0915 \u0939\u0948",
    "error2110": "\u092C\u093E\u0907\u0902\u0921\u093F\u0902\u0917 \u090F\u091C\u0947\u0902\u091F \u0936\u094D\u0930\u0947\u0937\u094D\u0920-\u0905\u0927\u0940\u0928\u0938\u094D\u0925 \u0938\u0902\u092C\u0902\u0927 \u0924\u094D\u0930\u0941\u091F\u093F",
    "error2200": "\u0928\u093F\u0937\u094D\u0915\u094D\u0930\u093F\u092F \u0915\u0930 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
    "error2201": "\u0928\u093F\u0915\u093E\u0938\u0940 \u092F\u0942\u0938\u0940 \u0938\u0902\u0916\u094D\u092F\u093E 10,000~1,000,000 \u0915\u0940 \u0938\u0940\u092E\u093E \u0915\u0947 \u092D\u0940\u0924\u0930 \u0939\u0948 \u0914\u0930 100 \u0915\u093E \u092A\u0942\u0930\u094D\u0923\u093E\u0902\u0915 \u0917\u0941\u0923\u0915 \u0939\u0948",
    "error2202": "\u092F\u0939 \u0932\u0947\u0928\u0926\u0947\u0928 \u0935\u093F\u0927\u093F (Alipay) \u0938\u092E\u0930\u094D\u0925\u093F\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "error2203": "\u0928\u093F\u0915\u093E\u0938\u0940 \u0916\u093E\u0924\u0947 \u0915\u0940 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0938\u092E\u0940\u0915\u094D\u0937\u093E\u0927\u0940\u0928 \u0939\u0948 \u0914\u0930 \u0907\u0938\u0947 \u0938\u0902\u0936\u094B\u0927\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E",
    "error2204": "\u0928\u093F\u0915\u093E\u0938\u0940 \u0916\u093E\u0924\u0947 \u0915\u0940 \u0915\u094B\u0908 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "error2205": "\u092A\u0948\u0938\u0947 \u0928\u093F\u0915\u093E\u0932\u0928\u0947 \u092E\u0947\u0902 \u0905\u0938\u092E\u0930\u094D\u0925, \u0915\u0943\u092A\u092F\u093E \u0917\u094D\u0930\u093E\u0939\u0915 \u0938\u0947\u0935\u093E \u0938\u0947 \u0938\u0902\u092A\u0930\u094D\u0915 \u0915\u0930\u0947\u0902",
    "error2206": "\u091A\u0948\u0928\u0932 \u0935\u0941\u0915 \u0928\u093F\u0937\u094D\u0915\u094D\u0930\u093F\u092F \u0915\u0930 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
    "error2207": "\u0938\u094D\u0925\u093E\u0928\u093E\u0902\u0924\u0930\u0923 \u092A\u093E\u0930\u094D\u091F\u0940 \u0915\u094B \u0928\u093F\u0937\u094D\u0915\u094D\u0930\u093F\u092F \u0915\u0930 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
    "error2208": "\u0926\u0948\u0928\u093F\u0915 \u0939\u0938\u094D\u0924\u093E\u0902\u0924\u0930\u0923 \u0930\u093E\u0936\u093F \u092A\u093E\u0930 \u0939\u094B \u0917\u0908 \u0939\u0948",
    "error2209": "\u0906\u092A UC \u0915\u094B \u0905\u092A\u0928\u0947 \u092A\u093E\u0938 \u0938\u094D\u0925\u093E\u0928\u093E\u0902\u0924\u0930\u093F\u0924 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u0947",
    "error2210": "\u0938\u094D\u0925\u093E\u0928\u093E\u0902\u0924\u0930\u0923 \u0909\u092A\u092F\u094B\u0917\u0915\u0930\u094D\u0924\u093E \u092E\u094C\u091C\u0942\u0926 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "error2211": "\u092D\u0941\u0917\u0924\u093E\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F 5 \u0938\u0947 \u0905\u0927\u093F\u0915 \u0911\u0930\u094D\u0921\u0930 \u0939\u0948\u0902, \u0914\u0930 \u0906\u092A \u091C\u092E\u0930 \u091C\u093E\u0930\u0940 \u0928\u0939\u0940\u0902 \u0930\u0916 \u0938\u0915\u0924\u0947",
    "error2212": "\u091C\u092E\u0930 \u0930\u093E\u0936\u093F \u0938\u0940\u092E\u093E \u0938\u0947 \u092A\u0930\u0947",
    "error2213": "\u092D\u0941\u0917\u0924\u093E\u0928 \u0905\u0928\u0941\u0930\u094B\u0927 \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902, \u092C\u093E\u0926 \u092E\u0947\u0902 \u092A\u094D\u0930\u092F\u093E\u0938 \u0915\u0930\u0947\u0902",
    "error2214": "\u090F\u0915\u0932 \u0938\u094D\u0925\u093E\u0928\u093E\u0902\u0924\u0930\u0923 \u0915\u0940 \u0928\u094D\u092F\u0942\u0928\u0924\u092E \u0938\u0902\u0916\u094D\u092F\u093E 1,000 \u0939\u0948 \u0914\u0930 \u0905\u0927\u093F\u0915\u0924\u092E \u0938\u0902\u0916\u094D\u092F\u093E 5,000,000 \u0939\u0948",
