    "club_tribe_10": "\u0938\u092B\u0932 \u0932\u094B\u0917\u094B\u0902 \u0938\u0947 \u091C\u0941\u0921\u093C\u0947\u0902, \u0905\u0928\u0941\u092E\u094B\u0926\u0928 \u0915\u0940 \u092A\u094D\u0930\u0924\u0940\u0915\u094D\u0937\u093E \u092E\u0947\u0902",
    "club_0": "\u0906\u092A\u0915\u0947 \u0926\u094D\u0935\u093E\u0930\u093E \u092C\u0928\u093E\u092F\u093E \u0917\u092F\u093E \u0915\u094D\u0932\u092C \u0938\u092E\u0940\u0915\u094D\u0937\u093E\u0927\u0940\u0928 \u0939\u0948, \u0914\u0930 \u0905\u0928\u094D\u092F \u0915\u094D\u0932\u092C \u0928\u0939\u0940\u0902 \u092C\u0928\u093E\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E\u0964",
