    "adaptation20009": "\u090F\u0921\u092E\u093F\u0928\u0938\u0947\u091F\u093F\u0902\u0917\u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u0947 \u0932\u093F\u090F \u0928\u094D\u092F\u0942\u0928\u0924\u092E \u0916\u0947\u0932 \u0938\u092E\u092F \u0939\u0948<color=#ff0000>##\u0918\u0902\u091F\u0947</color>, \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0907\u0938 \u0905\u0935\u0927\u093F \u0915\u0947 \u0926\u094C\u0930\u093E\u0928 \u091F\u0947\u092C\u0932 \u0928\u0939\u0940\u0902 \u091B\u094B\u0921\u093C \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u0905\u0928\u094D\u092F\u0925\u093E \u092C\u094D\u0932\u093E\u0907\u0902\u0921 \u092A\u094D\u0932\u0947\u0907\u0902\u0917 \u0915\u093E \u0939\u094B\u0938\u094D\u091F\u093F\u0902\u0917 \u092E\u094B\u0921 \u0932\u093E\u0917\u0942 \u0915\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E\u0964",
    "adaptation20010": "\u0905\u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u092F\u0942\u0938\u0940 \u092C\u0948\u0932\u0947\u0902\u0938, \u0915\u0943\u092A\u092F\u093E \u092A\u0939\u0932\u0947 \u091C\u093E\u0902\u091A\u0947\u0902",
    "adaptation20011": "\u090F\u0921\u092E\u093F\u0928\u093F\u0938\u094D\u091F\u094D\u0930\u0947\u091F\u0930\u0932\u0942",
    "adaptation20012": "\u090F\u0921\u092E\u093F\u0928\u0939\u093E\u0938 \u092C\u0902\u0926Muck",
    "adaptation20013": "\u090F\u0921\u092E\u093F\u0928\u091A\u0930\u094D\u0930\u094D\u0930",
    "adaptation20014": "\u090F\u0921\u092E\u093F\u0928 \u0928\u0947 \u091C\u092C\u0930\u0926\u0938\u094D\u0924\u0940 \u0938\u094D\u091F\u094D\u0930\u0948\u0921\u0932 \u0915\u094B \u092C\u0902\u0926 \u0915\u0930 \u0926\u093F\u092F\u093E \u0939\u0948",
    "adaptation20015": "\u090F\u0921\u092E\u093F\u0928 \u0926\u0947\u0930\u0940##\u092E\u093F\u0928\u091F",
    "adaptation20016": "\u0906\u092A \u092F\u0939\u093E\u0902 \u092A\u0930 \u0939\u0948##\u0916\u0947\u0932 \u0915\u0947 \u0926\u094C\u0930\u093E\u0928 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u092C\u0948\u0920\u093E \u0930\u0939\u0924\u093E \u0939\u0948 \u0914\u0930 \u0916\u0947\u0932 \u092E\u0947\u0902 \u0936\u093E\u092E\u093F\u0932 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0924\u093E\u0964",
    "adaptation20017": "OUTS>16 \u092F\u093E OUTS=0, \u091B\u093E\u0924\u094D\u0930\u093E\u0935\u093E\u0938 \u0928\u0939\u0940\u0902 \u0916\u0930\u0940\u0926 \u0938\u0915\u0924\u0947",
    "adaptation20018": "\u0938\u093F\u0938\u094D\u091F\u092E \u0911\u091F\u094B \u0905\u0924\u093F\u0930\u093F\u0915\u094D\u0924 \u0907\u0928\u094D\u0938. \u092C\u0940\u092E\u093E, \u0916\u0930\u0940\u0926## UC",
    "adaptation20019": "\u0907\u0938 \u092C\u093E\u0930 \u0906\u092A\u0915\u0947 \u0926\u094D\u0935\u093E\u0930\u093E \u0928\u093F\u0935\u0947\u0936 \u0915\u0940 \u0917\u0908 \u092C\u0940\u092E\u093E \u0915\u0940 \u0905\u0927\u093F\u0915\u0924\u092E \u0930\u093E\u0936\u093F \u0906\u092A\u0915\u0947 \u0905\u092A\u0928\u0947 \u092A\u0949\u091F \u092A\u0949\u0907\u0902\u091F\u094D\u0938 \u0915\u0940 0.45 \u0939\u0948, \u0914\u0930 \u0905\u0927\u093F\u0915\u0924\u092E \u092E\u0942\u0932\u094D\u092F \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0916\u0930\u0940\u0926\u093E \u0917\u092F\u093E \u0939\u0948#",
    "adaptation20020": "\u0905\u0927\u093F\u0915\u0924\u092E \u0926\u094D\u0935\u093F\u0924\u0940\u092F\u0915 \u092C\u0940\u092E\u093E \u0930\u093E\u0936\u093F 1/2\u092A\u0949\u091F \u0939\u0948, \u0914\u0930 \u0905\u0927\u093F\u0915\u0924\u092E \u092E\u0942\u0932\u094D\u092F \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0916\u0930\u0940\u0926\u093E \u0917\u092F\u093E \u0939\u0948\u0964##",
    "adaptation20021": "\u092F\u0926\u093F \u0906\u092A \u0935\u0930\u094D\u0924\u092E\u093E\u0928 \u0917\u0947\u092E \u092E\u0947\u0902 \u092C\u0940\u092C\u0940 \u0938\u094D\u0925\u093F\u0924\u093F \u092E\u0947\u0902 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902, \u0924\u094B \u0906\u092A \u092C\u0940\u092C\u0940 \u0915\u0940 \u092F\u0942\u0938\u0940 \u0930\u093E\u0936\u093F \u0915\u093E\u091F\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0917\u0947\u092E \u092E\u0947\u0902 \u0936\u093E\u092E\u093F\u0932 \u0939\u094B\u0902\u0917\u0947\u0964",
    "adaptation20022": "\u0905\u0938\u094D\u0924\u093F\u0924\u094D\u0935##\u0915\u092E\u0930\u093E \u0939\u094B\u0938\u094D\u091F \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948",
    "adaptation20023": "\u090F\u0921\u092E\u093F\u0928\u0938\u0947\u091F\u093F\u0902\u0917\u092C\u093E\u092F-\u0907\u0928 \u0917\u0941\u0923\u0915 \u0939\u0948\u0902##-##\u091F\u093E\u0907\u092E\u094D\u0938",
    "adaptation20024": "\u0928\u093F\u0937\u094D\u092A\u0915\u094D\u0937\u0924\u093E \u0915\u0947 \u0932\u093F\u090F, \u0906\u092A \u0916\u0947\u0932 \u092E\u0947\u0902 \u0924\u092D\u0940 \u0936\u093E\u092E\u093F\u0932 \u0939\u094B \u0938\u0915\u0924\u0947 \u0939\u0948\u0902 \u091C\u092C \u092C\u0940\u092C\u0940 \u092A\u0926 \u092A\u0930 \u0906\u0928\u0947 \u0915\u0940 \u0906\u092A\u0915\u0940 \u092C\u093E\u0930\u0940 \u0939\u094B",
    "adaptation20025": "\u092B\u094D\u0932\u0949\u092A \u0938\u0930\u094D\u0915\u0932 \u092E\u0947\u0902 \u0915\u093E\u0930\u094D\u0921 \u091C\u093E\u0902\u091A\u0947\u0902",
    "adaptation20026": "\u091F\u0930\u094D\u0928 \u0938\u0930\u094D\u0915\u0932 \u092E\u0947\u0902 \u0915\u093E\u0930\u094D\u0921\u094B\u0902 \u0915\u0940 \u091C\u093E\u0902\u091A \u0915\u0930\u0947\u0902",
    "adaptation20027": "\u0930\u093F\u0935\u0930 \u0938\u0930\u094D\u0915\u0932 \u092E\u0947\u0902 \u0915\u093E\u0930\u094D\u0921 \u091C\u093E\u0902\u091A\u0947\u0902",
    "adaptation20028": "\u0906\u092A\u0915\u094B \u090F\u0921\u092E\u093F\u0928 \u0926\u094D\u0935\u093E\u0930\u093E \u091F\u0940\u092E \u0938\u0947 \u092C\u093E\u0939\u0930 \u0928\u093F\u0915\u093E\u0932 \u0926\u093F\u092F\u093E \u0917\u092F\u093E \u0914\u0930 \u0916\u0921\u093C\u0947 \u0939\u094B\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092E\u091C\u092C\u0942\u0930 \u0915\u093F\u092F\u093E \u0917\u092F\u093E",
    "adaptation20029": "\u0939\u094B\u0932\u094D\u0921'\u090F\u092E (\u091B\u094B\u0921\u093C\u0928\u093E \u091A\u093E\u0939\u093F\u090F)",
    "adaptation20030": "Hold'em(AOF)",
