    "adaptation20033": "Omaha(AOF)",
    "adaptation20034": "\u0905\u0924\u093F\u0930\u093F\u0915\u094D\u0924 \u0907\u0928\u094D\u0938 \u0915\u094B \u092C\u0932\u092A\u0942\u0930\u094D\u0935\u0915 \u0932\u093E\u0917\u0942 \u0915\u0930\u0947\u0902: \u0905\u091A\u092F\u0928\u093F\u0924 \u0906\u0909\u091F\u094D\u0938##\u091D\u093E\u0902\u0917, \u0938\u0902\u092D\u093E\u0935\u0928\u093E \u0939\u0948##, \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u092C\u0940\u092E\u093E \u0930\u093E\u0936\u093F##",
    "adaptation20035": "\u0906\u092A\u0915\u094B \u0907\u0938 \u0926\u094C\u0930 \u092E\u0947\u0902 \u0938\u092D\u0940 \u0906\u0909\u091F \u0916\u0930\u0940\u0926\u0928\u0947 \u0939\u094B\u0902\u0917\u0947",
    "adaptation20036": "\u0928\u094D\u092F\u0942\u0928\u0924\u092E \u0935\u0943\u0926\u094D\u0927\u093F \u0930\u093E\u0936\u093F:##",
    "adaptation20037": "OKFold\uFF1F",
    "adaptation20038": "\u0906\u092A \u092C\u093F\u0928\u093E \u0915\u093F\u0938\u0940 \u091A\u093F\u092A\u094D\u0938 \u0915\u0947 \u091C\u093E\u0902\u091A \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902",
    "adaptation20039": "\u0915\u094D\u092F\u093E \u0906\u092A \u0915\u092E\u0930\u093E \u0916\u093C\u0924\u094D\u092E \u0915\u0930\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902?",
    "adaptation20040": "\u0932\u093E\u0917\u0924:##",
    "adaptation20041": "\u0909\u092A\u0928\u093E\u092E:",
    "adaptation20042": "\u0915\u0947\u0935\u0932 \u092A\u093F\u091B\u0932\u0947 30 \u0926\u093F\u0928\u094B\u0902 \u0915\u093E \u0921\u0947\u091F\u093E \u092A\u094D\u0930\u0926\u0930\u094D\u0936\u093F\u0924 \u0915\u0930\u0947\u0902",
