    "adaptation20044": "\u0935\u0940\u0906\u0908\u092A\u0940 \u0938\u0915\u094D\u0930\u093F\u092F \u0915\u0930\u0947\u0902",
    "adaptation20045": "\u0935\u0940\u0906\u0908\u092A\u0940 \u0905\u092A\u0917\u094D\u0930\u0947\u0921 \u0915\u0930\u0947\u0902",
