    "adaptation20047": "\u092A\u094D\u0932\u0948\u091F\u093F\u0928\u092E \u0921\u093E\u0907\u092E\u0902\u0921VIP \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902",
    "adaptation20048": "\u0921\u0947\u0930\u0947\u092E\u0902\u0921\u0935\u0940\u0906\u0908\u092A\u0940 \u0926\u0947\u0916 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902",
    "adaptation20049": "\u0926\u0930\u094D\u0936\u0915 \u091C\u093E\u0926\u0941\u0908 \u0907\u092E\u094B\u091F\u093F\u0915\u0949\u0928\u094D\u0938 \u0928\u0939\u0940\u0902 \u092D\u0947\u091C \u0938\u0915\u0924\u0947",
    "adaptation20050": "\u0915\u094D\u092F\u093E \u0906\u092A \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u091C\u092C\u0930\u0926\u0938\u094D\u0924\u0940 \u092C\u093E\u0939\u0930 \u0928\u093F\u0915\u093E\u0932\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902? \u092C\u093E\u0939\u0930 \u0928\u093F\u0915\u093E\u0932\u0947 \u091C\u093E\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0906\u092A \u0907\u0938 \u0915\u092E\u0930\u0947 \u092E\u0947\u0902 \u092A\u094D\u0930\u0935\u0947\u0936 \u0928\u0939\u0940\u0902 \u0915\u0930 \u0938\u0915\u0924\u0947\u0964",
    "adaptation20051": "\u0915\u094D\u092F\u093E \u0906\u092A \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u0916\u0921\u093C\u0947 \u0939\u094B\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092E\u091C\u092C\u0942\u0930 \u0915\u0930\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902?",
    "adaptation20052": "\u0936\u094D\u0930\u094B\u0924\u093E\u0917\u0923",
    "adaptation20053": "\u091A\u0942\u0902\u0915\u093F \u0906\u092A\u0928\u0947 \u091F\u0930\u094D\u0928\u0907\u0902\u0936\u094D\u092F\u094B\u0930\u0947\u0902\u0938 \u0916\u0930\u0940\u0926\u093E \u0939\u0948, \u0907\u0938\u0932\u093F\u090F \u0905\u092A\u0928\u0947 \u0939\u093F\u0924\u094B\u0902 \u0915\u0940 \u0930\u0915\u094D\u0937\u093E \u0915\u0947 \u0932\u093F\u090F \u0930\u093F\u0935\u0930\u0907\u0902\u0936\u094D\u092F\u094B\u0930\u0947\u0902\u0938 \u0916\u0930\u0940\u0926\u0928\u093E \u0905\u0928\u093F\u0935\u093E\u0930\u094D\u092F \u0939\u0948\u0964 \u092F\u0939 \u0906\u092A\u0915\u0947 \u0932\u093F\u090F \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0938\u092E\u0930\u094D\u0925\u093F\u0924 \u0939\u094B \u0917\u092F\u093E \u0939\u0948##(\u0907\u0938 \u092C\u093E\u0930 \u0915\u093E\u0930\u094D\u0921 \u0915\u093E \u091A\u092F\u0928 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E)",
    "adaptation20054": "\u092C\u0927\u093E\u0908 \u0939\u094B##\u092E\u093E\u0930\u094B##\u0914\u0930 \u091C\u0940\u0924\u094B## UC",
    "adaptation20055": "\u0915\u094D\u092F\u093E \u0906\u092A \u090F\u091C\u0947\u0902\u091F \u092C\u0928\u0928\u093E \u0920\u0940\u0915 \u0939\u0948?",
    "adaptation20056": "\u092C\u0940\u092E\u093E",
