    "UIInsurance_yixuan": "\u091A\u092F\u0928\u093F\u0924:",
    "UIJackPotInfo_tips": '1. \u092F\u0926\u093F \u0935\u0930\u094D\u0924\u092E\u093E\u0928 \u092E\u0947\u0902 \u092D\u093E\u0917 \u0932\u0947\u0928\u0947 \u0935\u093E\u0932\u0947 \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E 4 \u0924\u0915 \u092A\u0939\u0941\u0902\u091A \u091C\u093E\u0924\u0940 \u0939\u0948, \u0924\u094B \u091C\u0948\u0915\u092A\u0949\u091F \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0926\u0930\u094D\u091C \u0939\u094B \u091C\u093E\u090F\u0917\u093E\u0964 \u092F\u0926\u093F 4 \u0938\u0947 \u0915\u092E \u0939\u0948\u0902, \u0924\u094B \u0907\u0928\u093E\u092E \u0938\u0915\u094D\u0930\u093F\u092F \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E \u0914\u0930 \u091C\u0947\u092A\u0940 \u0928\u0939\u0940\u0902 \u0928\u093F\u0915\u093E\u0932\u093E \u091C\u093E\u090F\u0917\u093E\u0964 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0926\u094D\u0935\u093E\u0930\u093E \u0935\u093F\u0936\u093F\u0937\u094D\u091F \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930 \u0915\u094B \u0939\u093F\u091F \u0915\u0930\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926, \u0909\u0938\u0947 \u091C\u0948\u0915\u092A\u0949\u091F \u0907\u0928\u093E\u092E \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0939\u094B\u0917\u093E;\\n2. \u0935\u093F\u0936\u093F\u0937\u094D\u091F \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930 \u0915\u094B \u0939\u093F\u091F \u0915\u0930\u0928\u0947 \u0915\u093E \u0924\u093E\u0924\u094D\u092A\u0930\u094D\u092F \u0939\u0948:\\n\u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0947 \u0926\u094B \u0939\u093E\u0925 \u0935\u093E\u0932\u0947 \u0915\u093E\u0930\u094D\u0921 \u0914\u0930 \u0938\u093E\u092E\u0941\u0926\u093E\u092F\u093F\u0915 \u0915\u093E\u0930\u094D\u0921 \u092E\u093F\u0932\u0915\u0930 \u090F\u0915 [\u0930\u0949\u092F\u0932 \u092B\u094D\u0932\u0936] [\u091A\u093E\u0930 \u092E\u0947\u0902 \u0938\u0947 \u091A\u093E\u0930] \u092C\u0928\u093E\u0924\u0947 \u0939\u0948\u0902 \u0914\u0930 \u091C\u0940\u0924\u0924\u0947 \u0939\u0948\u0902\u0964\\n\u0909\u0926\u093E\u0939\u0930\u0923 \u0915\u0947 \u0932\u093F\u090F: 4 \u0939\u093F\u091F \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F, \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0947 \u0926\u094B \u0915\u093E\u0930\u094D\u0921 \u091C\u094B\u0921\u093C\u0947 \u092E\u0947\u0902 \u0938\u0947 \u090F\u0915 \u0939\u094B\u0928\u0947 \u091A\u093E\u0939\u093F\u090F\\n3. \u092C\u0930\u094D\u0924\u0928 \u092E\u0947\u0902 \u0921\u093E\u0932\u0947\u0902:\\n\u091C\u092C \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u093E \u092A\u094D\u0930\u0924\u093F \u0939\u093E\u0925 \u0932\u093E\u092D 10 BB \u0924\u0915 \u092A\u0939\u0941\u0901\u091A \u091C\u093E\u0924\u093E \u0939\u0948, \u0924\u094B \u0938\u093F\u0938\u094D\u091F\u092E \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0926\u094B SB \u0928\u093F\u0915\u093E\u0932 \u0932\u0947\u0924\u093E \u0939\u0948, \u090F\u0915 SB \u092A\u0949\u091F \u092E\u0947\u0902 \u0921\u093E\u0932 \u0926\u093F\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948, \u0914\u0930 \u090F\u0915 SB "\u092A\u0941\u0930\u0938\u094D\u0915\u093E\u0930 \u092A\u0942\u0932" \u092E\u0947\u0902 \u0921\u093E\u0932 \u0926\u093F\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948\u0964\\n\u0928\u094B\u091F: "\u092A\u0941\u0930\u0938\u094D\u0915\u093E\u0930 \u092A\u0942\u0932" \u0939\u0930 \u0926\u093F\u0928 \u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u0930\u0942\u092A \u0938\u0947 \u0935\u093F\u0924\u0930\u093F\u0924 \u0915\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E, \u0914\u0930 \u092A\u0941\u0930\u0938\u094D\u0915\u093E\u0930 \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0924\u093E\u0932\u093F\u0915\u093E \u0938\u0947 \u090F\u0915 \u092D\u093E\u0917\u094D\u092F\u0936\u093E\u0932\u0940 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u093E \u091A\u092F\u0928 \u0915\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E\u0964 \u0935\u093F\u0935\u0930\u0923 \u0915\u0947 \u0932\u093F\u090F \u0915\u0943\u092A\u092F\u093E \u092A\u0941\u0930\u0938\u094D\u0915\u093E\u0930 \u092A\u0942\u0932 \u092A\u0943\u0937\u094D\u0920 \u0926\u0947\u0916\u0947\u0902\u0964\\n4. \u0935\u093F\u0924\u0930\u0923 \u0928\u093F\u0930\u094D\u0926\u0947\u0936\\n(1) \u091C\u093E\u0930\u0940 \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u0907\u0928\u093E\u092E \u092F\u0942\u0938\u0940 \u0939\u0948\\n(2) \u092E\u093E\u0930\u0928\u0947 \u0915\u093E \u0907\u0928\u093E\u092E \u0938\u0940\u0927\u0947 \u092A\u093E\u0920\u0915\u094B\u0902 \u0915\u094B \u0935\u093F\u0924\u0930\u093F\u0924 \u0915\u093F\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948',
