    "WalletTranschipsBindingCard_Sgiloq": "\u0916\u093E\u0924\u093E \u0936\u0939\u0930:",
    "WalletTranschipsBindingCard_8d9iCb": "\u0928\u094B\u091F: 1. \u0915\u0943\u092A\u092F\u093E \u0938\u0939\u0940 \u092C\u0948\u0902\u0915 \u0915\u093E\u0930\u094D\u0921 \u0916\u093E\u0924\u093E \u0938\u0902\u0916\u094D\u092F\u093E \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902. \u092C\u0948\u0902\u0915 \u0915\u093E\u0930\u094D\u0921 \u0938\u0947 \u092A\u0948\u0938\u0947 \u0928\u093F\u0915\u093E\u0932\u0924\u0947 \u0938\u092E\u092F, \u092F\u0939 \u0938\u0940\u0927\u0947 \u092C\u0948\u0902\u0915 \u0915\u093E\u0930\u094D\u0921 \u0916\u093E\u0924\u093E \u0938\u0902\u0916\u094D\u092F\u093E \u092E\u0947\u0902 \u0938\u094D\u0925\u093E\u0928\u093E\u0902\u0924\u0930\u093F\u0924 \u0915\u0930 \u0926\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E\u0964 \u0916\u093E\u0924\u093E \u0938\u0902\u0916\u094D\u092F\u093E \u0915\u094B \u0938\u0902\u0936\u094B\u0927\u093F\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0915\u0943\u092A\u092F\u093E \u0917\u094D\u0930\u093E\u0939\u0915 \u0938\u0947\u0935\u093E \u0938\u0947 \u092A\u0930\u093E\u092E\u0930\u094D\u0936 \u0932\u0947\u0902\u0964\\n2. \u090F\u0915 \u092C\u0948\u0902\u0915 \u0915\u093E\u0930\u094D\u0921 \u0915\u094B \u0915\u0947\u0935\u0932 2 \u0906\u0908\u0921\u0940 \u0928\u0902\u092C\u0930 \u0938\u0947 \u091C\u094B\u0921\u093C\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948\u0964",
    "WalletTranschipsBindingCard_tishi": "\u0938\u092B\u0932 \u0928\u093F\u0915\u093E\u0938\u0940 \u0938\u0941\u0928\u093F\u0936\u094D\u091A\u093F\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0939\u0940 \u092C\u0948\u0902\u0915 \u0915\u093E\u0930\u094D\u0921 \u091C\u093E\u0928\u0915\u093E\u0930\u0940 \u092D\u0930\u0947\u0902\u0964 \u092F\u0926\u093F \u0906\u092A\u0915\u0947 \u0915\u094B\u0908 \u092A\u094D\u0930\u0936\u094D\u0928 \u0939\u0948\u0902, \u0924\u094B \u0915\u0943\u092A\u092F\u093E \u0917\u094D\u0930\u093E\u0939\u0915 \u0938\u0947\u0935\u093E \u0938\u0947 \u0938\u0902\u092A\u0930\u094D\u0915 \u0915\u0930\u0947\u0902",
    "WalletTranschipsBindingCard_rightNowAdd": "\u0905\u092D\u0940 \u091C\u094B\u0921\u093C\u0947\u0902",
    "UIData_ShowProblem_zIwG": "\u092C\u0941\u0928\u093F\u092F\u093E\u0926\u0940 \u0921\u0947\u091F\u093E",
    "UIData_ShowProblem_eZys": "\u0935\u0940\u0906\u0908\u092A\u0940 \u0938\u0926\u0938\u094D\u092F \u0909\u0928\u094D\u0928\u0924 \u0921\u0947\u091F\u093E",
    "UIData_ShowProblem_SM0y": "\u0915\u0941\u0932 \u0939\u093E\u0925: \u0915\u094D\u0930\u0947\u091C\u093C\u0940 \u092A\u094B\u0915\u0930 \u092E\u0947\u0902 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0926\u094D\u0935\u093E\u0930\u093E \u0916\u0947\u0932\u0947 \u0917\u090F \u0939\u093E\u0925\u094B\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E\\n\\n\u0916\u0947\u0932\u094B\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E: \u0915\u094D\u0930\u0947\u091C\u093C\u0940 \u092A\u094B\u0915\u0930 \u092E\u0947\u0902 \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0926\u094D\u0935\u093E\u0930\u093E \u0916\u0947\u0932\u0947 \u0917\u090F \u0916\u0947\u0932\u094B\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E\\n\\n\u0935\u0940\u092A\u0940\u0906\u0908\u092A\u0940: \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u0947 \u0939\u093E\u0925\u094B\u0902 \u0915\u093E \u0905\u0928\u0941\u092A\u093E\u0924 \u091C\u093F\u0928\u094D\u0939\u0947\u0902 \u0916\u0947\u0932\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092A\u0942\u0932 \u092E\u0947\u0902 \u0921\u093E\u0932\u093E \u091C\u093E\u0924\u093E \u0939\u0948 (\u090F\u0902\u091F\u0947 \u0915\u094B \u092A\u0942\u0932 \u092E\u0947\u0902 \u0936\u093E\u092E\u093F\u0932 \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948, \u0914\u0930 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u0938\u0915\u094D\u0930\u093F\u092F \u0930\u0942\u092A \u0938\u0947 \u0915\u0949\u0932 \u0915\u0930\u0928\u0947 \u092F\u093E \u0909\u0920\u093E\u0928\u0947 \u0915\u0940 \u0906\u0935\u0936\u094D\u092F\u0915\u0924\u093E \u0939\u0948); \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0926\u094D\u0935\u093E\u0930\u093E \u092A\u0942\u0932 \u092E\u0947\u0902 \u092A\u094D\u0930\u0935\u0947\u0936 \u0915\u0930\u0928\u0947 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E/\u0939\u093E\u0925\u094B\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E\\n\\n\u0935\u0940\u092A\u0940\u0906\u0908\u092A\u0940 \u091C\u0940\u0924: \u092A\u0942\u0932 \u092E\u0947\u0902 \u0921\u093E\u0932\u0947 \u0917\u090F \u0939\u093E\u0925\u094B\u0902 \u0938\u0947 \u091C\u0940\u0924\u0928\u0947 \u0935\u093E\u0932\u0947 \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u093E \u0905\u0928\u0941\u092A\u093E\u0924\u0964\\n\\n\u092A\u094D\u0930\u0924\u093F \u0917\u0947\u092E \u0914\u0938\u0924 \u0930\u093F\u0915\u0949\u0930\u094D\u0921: \u092A\u094D\u0930\u0924\u093F \u0917\u0947\u092E \u092A\u094D\u0930\u093E\u092A\u094D\u0924/\u0916\u094B\u090F \u0917\u090F \u0914\u0938\u0924 \u0905\u0902\u0915\u0964 \u0917\u0923\u0928\u093E \u092A\u0926\u094D\u0927\u0924\u093F \u0915\u0941\u0932 \u0930\u093F\u0915\u0949\u0930\u094D\u0921 \u0915\u094B \u0916\u0947\u0932\u094B\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E \u0938\u0947 \u0935\u093F\u092D\u093E\u091C\u093F\u0924 \u0915\u0930\u0928\u0947 \u092A\u0930 \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0939\u094B\u0924\u0940 \u0939\u0948\u0964\\n\\n\u092A\u094D\u0930\u0924\u093F \u0917\u0947\u092E \u0914\u0938\u0924 \u092C\u093E\u092F-\u0907\u0928: \u092A\u094D\u0930\u0924\u093F \u0917\u0947\u092E \u0914\u0938\u0924 \u092C\u093E\u092F-\u0907\u0928 \u0905\u0902\u0915\u0964 \u0917\u0923\u0928\u093E \u0935\u093F\u0927\u093F \u0915\u0941\u0932 \u0916\u0930\u0940\u0926\u093E\u0930\u0940 \u0915\u094B \u0916\u0947\u0932\u094B\u0902 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E \u0938\u0947 \u0935\u093F\u092D\u093E\u091C\u093F\u0924 \u0915\u0930\u0915\u0947 \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0915\u0940 \u091C\u093E\u0924\u0940 \u0939\u0948\u0964",
    "UIData_ShowProblem_3xqp": "VPIP: \u092A\u094D\u0930\u0940\u092B\u094D\u0932\u0949\u092A \u091C\u093F\u0924\u0928\u0940 \u0939\u0948\u0902\u0921 \u0916\u0947\u0932\u0924\u0947 \u0939\u094B (Ante \u0928\u0939\u0940\u0902). Loose/tight \u0926\u093F\u0916\u093E\u0924\u093E \u0939\u0948\u0964\\n\\nPFR: \u092A\u094D\u0930\u0940\u092B\u094D\u0932\u0949\u092A \u0930\u0947\u091C\u093C / VPIP \u0939\u0948\u0902\u0921\u0964\\n\\n3-bet: \u0930\u0947\u091C\u093C \u0915\u0947 \u092C\u093E\u0926 \u0930\u0940-\u0930\u0947\u091C\u093C / VPIP \u0939\u0948\u0902\u0921\u0964\\n\\nC-bet: \u092A\u093F\u091B\u0932\u0940 \u0938\u094D\u091F\u094D\u0930\u0940\u091F \u0932\u0940\u0921 \u0915\u0947 \u092C\u093E\u0926 \u092B\u093F\u0930 \u092C\u0947\u091F\u0964\\n\\nAF: \u091C\u093C\u094D\u092F\u093E\u0926\u093E = \u0906\u0915\u094D\u0930\u093E\u092E\u0915 (bet/raise vs call). {\uFF08\u4E0B\u6CE8\u7684\u6B21\u6570+\u52A0\u6CE8\u7684\u6B21\u6570\uFF09/\u8DDF\u6CE8\u7684\u6B21\u6570}/50 (\u0905\u0927\u093F\u0915\u0924\u092E 100%; \u092E\u0942\u0932 \u0905\u0927\u093F\u0915\u0924\u092E 50)\u0964\\n\\nWTSD: \u092B\u094D\u0932\u0949\u092A \u0926\u0947\u0916\u0915\u0930 \u0936\u094B\u0921\u093E\u0909\u0928 \u0924\u0915 %\u0964\\n\\nAll-in Wins: \u0911\u0932-\u0907\u0928 \u0935\u093F\u0928\u0930\u0947\u091F (\u090A\u0901\u091A\u093E = \u0915\u092E \u092C\u094D\u0932\u092B\u093C)\u0964\\n\\nVPIP Wins: VPIP \u0939\u0948\u0902\u0921 \u0915\u0940 \u0935\u093F\u0928\u0930\u0947\u091F\u0964",
