    "UITexasSetting_6li2vmg3": "\u0935\u094D\u092F\u0915\u094D\u0924\u093F\u0924\u094D\u0935 \u0928\u093F\u0930\u094D\u0927\u093E\u0930\u0923",
    "UITexasSetting_qAONskmY": "\u0915\u093E\u0930\u094D\u0921 \u092B\u0947\u0938 \u0938\u0947\u091F\u093F\u0902\u0917",
    "UITexasSetting_HK3O9Fa8": "\u0915\u093E\u0930\u094D\u0921 \u0936\u0948\u0932\u0940",
    "UITexasSetting_LrI45uIK": "\u0927\u094D\u0935\u0928\u093F \u092A\u094D\u0930\u092D\u093E\u0935 \u0938\u0947\u091F\u093F\u0902\u0917",
    "CardNames": "\u0906\u0908\u0938\u0940\u092C\u0940\u0938\u0940, \u0907\u0902\u0921\u0938\u094D\u091F\u094D\u0930\u093F\u092F\u0932 \u090F\u0902\u0921 \u0915\u092E\u0930\u094D\u0936\u093F\u092F\u0932 \u092C\u0948\u0902\u0915 \u0911\u092B \u091A\u093E\u0907\u0928\u093E^\u090F\u092C\u0940\u0938\u0940, \u091A\u0940\u0928 \u0915\u093E \u0915\u0943\u0937\u093F \u092C\u0948\u0902\u0915^\u0938\u0940\u0938\u0940\u092C\u0940, \u091A\u093E\u0907\u0928\u093E \u0915\u0902\u0938\u094D\u091F\u094D\u0930\u0915\u094D\u0936\u0928 \u092C\u0948\u0902\u0915^\u0938\u0940\u090F\u092E\u092C\u0940, \u091A\u093E\u0907\u0928\u093E \u092E\u0930\u094D\u091A\u0947\u0902\u091F\u094D\u0938 \u092C\u0948\u0902\u0915^\u0915\u0949\u092E, \u091A\u093E\u0907\u0928\u093E \u092C\u0948\u0902\u0915 \u0911\u092B \u0915\u092E\u094D\u092F\u0941\u0928\u093F\u0915\u0947\u0936\u0902\u0938^\u0938\u0940\u090F\u092E\u092C\u0940\u0938\u0940, \u091A\u093E\u0907\u0928\u093E \u092E\u093F\u0928\u0936\u0947\u0902\u0917 \u092C\u0948\u0902\u0915^\u0938\u0940\u0908\u092C\u0940, \u091A\u093E\u0907\u0928\u093E \u090F\u0935\u0930\u092C\u094D\u0930\u093E\u0907\u091F \u092C\u0948\u0902\u0915^\u091C\u0940\u0921\u0940\u092C\u0940, \u0917\u0941\u0906\u0902\u0917\u094D\u0921\u094B\u0902\u0917 \u0935\u093F\u0915\u093E\u0938 \u092C\u0948\u0902\u0915^\u092C\u0940\u0913\u0938\u0940, \u092C\u0948\u0902\u0915 \u0911\u092B \u091A\u093E\u0907\u0928\u093E^\u0938\u0940\u0906\u0908\u092C\u0940,\u0914\u0926\u094D\u092F\u094B\u0917\u093F\u0915 \u092C\u0948\u0902\u0915^\u0938\u094D\u092A\u093E\u092C\u0948\u0902\u0915, \u0938\u0947\u092B \u092C\u0948\u0902\u0915^\u090F\u091A\u090F\u0915\u094D\u0938\u092C\u0940, \u0939\u0941\u0906 \u091C\u093C\u093F\u092F\u093E \u092C\u0948\u0902\u0915^\u090F\u0938\u092A\u0940\u0921\u0940\u092C\u0940, \u0936\u0902\u0918\u093E\u0908 \u092A\u0941\u0921\u094B\u0902\u0917 \u0921\u0947\u0935\u0932\u092A\u092E\u0947\u0902\u091F \u092C\u0948\u0902\u0915^\u092C\u0940\u091C\u0947\u092C\u0948\u0902\u0915, \u092C\u0948\u0902\u0915 \u0911\u092B \u092C\u0940\u091C\u093F\u0902\u0917^\u092C\u094B\u0939\u093E\u0908\u092C, \u092C\u094B\u0939\u093E\u0908 \u092C\u0948\u0902\u0915^\u090F\u091A\u0915\u0947\u092C\u0940\u0908\u090F, \u092C\u0948\u0902\u0915 \u0911\u092B \u0908\u0938\u094D\u091F \u090F\u0936\u093F\u092F\u093E^QDCCB, \u0915\u093C\u093F\u0902\u0917\u0926\u093E\u0913 \u092C\u0948\u0902\u0915^CITIC, \u091A\u0940\u0928 CITIC \u092C\u0948\u0902\u0915",
    "UIMatch_Sharechips100": "\u091F\u093F\u092A\u094D\u0938^\u092A\u094D\u0930\u092E\u094B\u0936\u0928\u0932 \u0909\u092A\u0939\u093E\u0930 \u092F\u0942\u0938\u0940 \u0915\u0947 \u0932\u093F\u090F \u0906\u092A\u0915\u0940 \u092F\u094B\u0917\u094D\u092F\u0924\u093E \u092A\u0930 \u092C\u0927\u093E\u0908\u0964 \u0915\u094D\u092F\u093E \u0906\u092A \u0935\u093F\u0935\u0930\u0923 \u0926\u0947\u0916\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092C\u0941\u0932\u0947\u091F\u093F\u0928 \u092C\u094B\u0930\u094D\u0921 \u092A\u0930 \u091C\u093E\u0928\u093E \u091A\u093E\u0939\u0924\u0947 \u0939\u0948\u0902? \u0915\u0941\u0932 \u0909\u092A\u0932\u092C\u094D\u0927 \u0930\u093E\u0936\u093F: {0}\u092F\u0942\u0938\u0940^\u0926\u0947\u0916\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u091C\u093E\u090F\u0901^\u092F\u0942\u0938\u0940 \u092E\u0924 \u0915\u0930\u094B",
