    "UINiuZaiInsurance_titleOne": "\u0938\u091F\u094D\u091F\u0947\u092C\u093E\u091C\u0940 \u0915\u094D\u0937\u0947\u0924\u094D\u0930 [\u0938\u0902\u092C\u0902\u0927\u093F\u0924 \u092C\u093E\u0927\u093E\u0913\u0902 \u0915\u0947 \u0938\u093E\u0925 \u092A\u0941\u0930\u0938\u094D\u0915\u093E\u0930 \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0915\u0930\u0947\u0902]",
    "UINiuZaiXiaZhuQu_content01": "1. \u091C\u0940\u0924, \u0939\u093E\u0930 \u0914\u0930 \u091F\u093E\u0908 \u0915\u094D\u0937\u0947\u0924\u094D\u0930: \u0915\u093E\u0909\u092C\u0949\u092F \u091C\u0940\u0924\u0947, \u091F\u093E\u0908, \u092C\u0941\u0932\u094D\u0938 \u091C\u0940\u0924\u0947;",
    "UINiuZaiXiaZhuQu_content02": "2. \u0915\u094B\u0908 \u092D\u0940 \u0939\u0948\u0902\u0921 \u0915\u093E\u0930\u094D\u0921 \u0915\u094D\u0937\u0947\u0924\u094D\u0930: \u092B\u094D\u0932\u0936/\u0915\u0928\u0947\u0915\u094D\u091F\u0947\u0921 \u0915\u093E\u0930\u094D\u0921/\u0909\u092A\u092F\u0941\u0915\u094D\u0924 \u0915\u0928\u0947\u0915\u094D\u091F\u0947\u0921 \u0915\u093E\u0930\u094D\u0921, \u0907\u0915\u094D\u0915\u0947 \u0915\u0940 \u091C\u094B\u0921\u093C\u0940;",
    "UINiuZaiXiaZhuQu_content03": "3. \u0935\u093F\u091C\u0947\u0924\u093E \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930 \u0915\u094D\u0937\u0947\u0924\u094D\u0930: \u0909\u091A\u094D\u091A \u0915\u093E\u0930\u094D\u0921/\u090F\u0915 \u091C\u094B\u0921\u093C\u0940, \u0926\u094B \u091C\u094B\u0921\u093C\u0940, \u0924\u0940\u0928 \u0924\u0930\u0939 \u0915\u0947/\u0938\u094D\u091F\u094D\u0930\u0947\u091F \u092B\u094D\u0932\u0936, \u092B\u0941\u0932 \u0939\u093E\u0909\u0938, \u0915\u093F\u0902\u0917 \u0915\u093E\u0902\u0917/\u0938\u094D\u091F\u094D\u0930\u0947\u091F \u092B\u094D\u0932\u0936/\u0930\u0949\u092F\u0932 \u092B\u094D\u0932\u0936",
    "UINiuZai_high_one": "\u0909\u091A\u094D\u091A \u0915\u093E\u0930\u094D\u0921/\u091C\u094B\u0921\u093C\u0940",
    "UINiuZaiXiaZhuQu_content04": "\u0939\u0941\u0906\u0902\u0917 \u091F\u094B\u0902\u0917",
    "UINiuZaiInsurance_titleTwo": "\u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930 \u0915\u093E \u0906\u0915\u093E\u0930 [\u0938\u0942\u091F \u0915\u0940 \u092A\u0930\u0935\u093E\u0939 \u0915\u093F\u090F \u092C\u093F\u0928\u093E]",
    "UINiuZaiXiaZhuQu_content05": "1. \u0915\u093E\u0930\u094D\u0921 \u0915\u093E \u092A\u094D\u0930\u0915\u093E\u0930: \u0915\u093F\u0902\u0917 \u091F\u094B\u0902\u0917 > \u092B\u094D\u0932\u0936 > \u090F\u0915 \u0924\u0930\u0939 \u0915\u0947 \u091A\u093E\u0930 > \u092A\u0942\u0930\u093E \u0918\u0930 > \u092B\u094D\u0932\u0936 > \u0938\u0940\u0927\u093E > \u0924\u0940\u0928 \u0924\u0930\u0939 \u0915\u093E > \u0926\u094B \u091C\u094B\u0921\u093C\u0947 > \u091C\u094B\u0921\u093C\u093E >",
    "UINiuZaiXiaZhuQu_content06": "\u0939\u093E\u0908 \u0915\u093E\u0930\u094D\u0921;",
    "UINiuZaiXiaZhuQu_content07": "2.\u090F\u0915\u0932 \u0915\u093E\u0930\u094D\u0921:A>K>Q>J>10>9>8>7>6>5>4>3>2;",
    "UINiuZaiXiaZhuQu_content08": "3. \u0938\u092E\u093E\u0928 \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930: \u092A\u0939\u0932\u0947 \u0938\u092C\u0938\u0947 \u092C\u0921\u093C\u0947 \u090F\u0915\u0932 \u0915\u093E\u0930\u094D\u0921 \u0915\u0940 \u0924\u0941\u0932\u0928\u093E \u0915\u0930\u0947\u0902, \u092F\u0926\u093F \u0935\u0939\u0940 \u0915\u093E\u0930\u094D\u0921 \u0938\u092E\u093E\u0928 \u0939\u0948, \u0924\u094B \u0924\u0941\u0932\u0928\u093E \u0915\u094B \u0928\u0940\u091A\u0947 \u0915\u0940 \u0913\u0930 \u091C\u093E\u0930\u0940 \u0930\u0916\u0947\u0902, \u091C\u0948\u0938\u0947 \u0915\u093F 5 \u0915\u093E\u0930\u094D\u0921",
    "UINiuZaiXiaZhuQu_content09": "\u092F\u0926\u093F \u0915\u093E\u0930\u094D\u0921 \u0938\u092E\u093E\u0928 \u0939\u0948\u0902, \u0924\u094B \u092F\u0939 \u0921\u094D\u0930\u093E \u0939\u0948;",
    "UINiuZaiInsurance_titleThree": "\u0935\u093F\u0938\u094D\u092B\u094B\u091F \u0928\u093F\u092F\u092E",
    "UINiuZaiXiaZhuQu_content011": "\u091C\u092C \u0921\u0940\u0932\u0930 \u0915\u0947 \u0936\u0947\u0937 \u091A\u093F\u092A\u094D\u0938 \u0938\u092D\u0940 \u0935\u093F\u091C\u0947\u0924\u093E \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u094B \u092E\u0941\u0906\u0935\u091C\u093E \u0926\u0947\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u0928\u0939\u0940\u0902 \u0939\u094B\u0924\u0947 \u0939\u0948\u0902, \u0924\u094B \u0921\u0940\u0932\u0930 \u0915\u0947 \u0936\u0947\u0937 \u091A\u093F\u092A\u094D\u0938",
    "UINiuZaiXiaZhuQu_content012": "\u0936\u0947\u0937 \u0905\u0902\u0915 \u0935\u093F\u091C\u0947\u0924\u093E \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u0906\u0928\u0941\u092A\u093E\u0924\u093F\u0915 \u0930\u0942\u092A \u0938\u0947 \u0906\u0935\u0902\u091F\u093F\u0924 \u0915\u093F\u090F \u091C\u093E\u090F\u0902\u0917\u0947, \u0914\u0930 \u0928\u093F\u092A\u091F\u093E\u0928 \u092A\u0942\u0930\u093E \u0939\u094B\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0924\u092F \u0915\u093F\u090F \u091C\u093E\u090F\u0902\u0917\u0947\u0964",
