    "Uiclubrechargeconfirmorderfailed": "\u0915\u093E\u0930\u094D\u0930\u0935\u093E\u0908",
    "UITeaxinDeailt": "1. \u091C\u092C \u0938\u092D\u0940 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0906 \u091C\u093E\u090F\u0902 \u0924\u094B \u0917\u093E\u0930\u094D\u0921 \u0938\u0915\u094D\u0930\u093F\u092F \u0915\u0930\u0947\u0902\\n\\n2. \u0935\u0930\u094D\u0924\u092E\u093E\u0928 \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930 \u0915\u0947 \u0938\u092C\u0938\u0947 \u092C\u0921\u093C\u0947 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0926\u094D\u0935\u093E\u0930\u093E \u0916\u0930\u0940\u0926\u093E \u0917\u092F\u093E\u0964 \u092F\u0926\u093F \u0915\u0908 \u092A\u0949\u091F \u0939\u0948\u0902, \u0924\u094B \u0938\u092C\u0938\u0947 \u092C\u0921\u093C\u0947 \u092A\u0949\u091F \u092E\u0947\u0902 \u0905\u0917\u094D\u0930\u0923\u0940 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0916\u0930\u0940\u0926\u0947\u0917\u093E, \u0914\u0930 \u0915\u0947\u0935\u0932 \u0938\u092C\u0938\u0947 \u092C\u0921\u093C\u0947 \u092A\u0949\u091F \u0915\u094B \u0916\u0930\u0940\u0926\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948\\n\\n3. \u091C\u092C \u092A\u0949\u091F \u092E\u0947\u0902 3 \u0938\u0947 \u0905\u0927\u093F\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0936\u093E\u092E\u093F\u0932 \u0939\u094B\u0902\u0917\u0947, \u0924\u094B \u0911\u0930\u094D\u0915\u0947\u0938\u094D\u091F\u094D\u0930\u093E \u0938\u0915\u094D\u0930\u093F\u092F \u0928\u0939\u0940\u0902 \u0939\u094B\u0917\u093E\u0964 (\u091C\u092C \u0906\u092A 2 \u0932\u094B\u0917 \u092F\u093E 3 \u0932\u094B\u0917 \u0939\u094B\u0902 \u0924\u094B \u0906\u092A \u092C\u094D\u0930\u094B\u0915\u0930\u0947\u091C \u0916\u0930\u0940\u0926 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902)\u0964\\n\\n4.\u092B\u094D\u0932\u0949\u092A \u0925\u094D\u0930\u0940 \u0916\u0930\u0940\u0926\u093E \u0928\u0939\u0940\u0902 \u091C\u093E \u0938\u0915\u0924\u093E, \u091F\u0930\u094D\u0928 \u0907\u0902\u0936\u094D\u092F\u094B\u0930\u0947\u0902\u0938 \u0930\u093E\u0936\u093F 0.25*\u092A\u0949\u091F, \u0928\u0926\u0940 \u092C\u0940\u092E\u093E \u0930\u093E\u0936\u093F 0.5*\u092A\u0949\u091F\\n\\n5. \u092F\u0926\u093F \u091F\u0930\u094D\u0928 \u0921\u093E\u092F\u092E\u0902\u0921 \u0916\u0930\u0940\u0926\u0928\u0947 \u092E\u0947\u0902 \u0935\u093F\u092B\u0932 \u0930\u0939\u0924\u093E \u0939\u0948, \u0924\u094B \u0930\u093F\u0935\u0930 \u0915\u094B \u0938\u092D\u0940 \u092A\u094D\u0930\u0924\u093F\u0938\u094D\u0925\u093E\u092A\u0928 \u0915\u093E\u0930\u094D\u0921 \u0916\u0930\u0940\u0926\u0928\u0947 \u0939\u094B\u0902\u0917\u0947, \u0914\u0930 \u0930\u093F\u0935\u0930 \u0915\u093E \u092D\u0941\u0917\u0924\u093E\u0928 \u091F\u0930\u094D\u0928 \u0915\u0940 \u092C\u0940\u092E\u093E \u0930\u093E\u0936\u093F \u0938\u0947 \u0905\u0927\u093F\u0915 \u0939\u094B\u0928\u093E \u091A\u093E\u0939\u093F\u090F\\n\\n6. \u092F\u0926\u093F \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u092A\u0941\u0928\u0903\u092A\u0942\u0930\u094D\u0924\u093F \u0915\u093E\u0930\u094D\u0921\u094B\u0902 \u0915\u093E \u0915\u0947\u0935\u0932 \u090F\u0915 \u0939\u093F\u0938\u094D\u0938\u093E \u0916\u0930\u0940\u0926\u0924\u093E \u0939\u0948, \u0924\u094B \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0947 \u092C\u0940\u092C\u0940\u090F\u0921 \u0939\u094B\u0928\u0947 \u0915\u0947 \u091C\u094B\u0916\u093F\u092E \u0938\u0947 \u092C\u091A\u0928\u0947 \u0914\u0930 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0940 \u092C\u0940\u092E\u093E \u0930\u093E\u0936\u093F \u0935\u093E\u092A\u0938 \u0932\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u093F\u0938\u094D\u091F\u092E \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0936\u0947\u0937 \u092A\u0941\u0928\u0903\u092A\u0942\u0930\u094D\u0924\u093F \u0915\u093E\u0930\u094D\u0921 \u0916\u0930\u0940\u0926 \u0932\u0947\u0917\u093E\\n\\n7. \u0915\u0930\u093F\u092F\u0930 \u0921\u0947\u091F\u093E [\u0935\u093E\u0938\u094D\u0924\u0935\u093F\u0915 \u0938\u092E\u092F \u092A\u0930\u093F\u0923\u093E\u092E] [\u0905\u0902\u0924\u093F\u092E \u0917\u0947\u092E \u0938\u092E\u0940\u0915\u094D\u0937\u093E] \u0914\u0930 [\u0915\u093E\u0930\u094D\u0921 \u0917\u0947\u092E \u0935\u093F\u0935\u0930\u0923] \u092E\u0947\u0902 \u092A\u094D\u0930\u0926\u0930\u094D\u0936\u093F\u0924 \u0939\u094B\u0924\u093E \u0939\u0948\\n\\n8.\u0939\u094B\u0932\u094D\u0921\u092E, \u091C\u092C Omahaouts 30 \u0938\u0947 \u0905\u0927\u093F\u0915 \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948, \u0924\u094B \u091B\u093E\u0924\u094D\u0930\u093E\u0935\u093E\u0938 \u0938\u0915\u094D\u0930\u093F\u092F \u0928\u0939\u0940\u0902 \u0939\u094B\u0924\u093E \u0939\u0948",
    "UITeaxinDeailt_PeiFu": "1. \u092A\u0942\u0902\u091C\u0940 \u0938\u0941\u0930\u0915\u094D\u0937\u093E: \u092D\u0941\u0917\u0924\u093E\u0928 = \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0928\u093F\u0935\u0947\u0936\\n\\n2. \u092A\u0942\u0930\u094D\u0923 \u092A\u0942\u0932: \u091A\u093E\u0939\u0947 \u0906\u0936\u094D\u0930\u092E \u0938\u092B\u0932 \u0939\u094B \u092F\u093E \u0928\u0939\u0940\u0902, \u0906\u092F \u092C\u0930\u093E\u092C\u0930 \u0939\u0948\\n\\n3. \u0917\u093E\u091C\u0930 \u0916\u0930\u0940\u0926\u0924\u0947 \u0938\u092E\u092F \u0909\u092A\u092D\u094B\u0917 \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u092F\u0942\u0938\u0940 \u092A\u0949\u091F \u0938\u0947 \u0915\u093E\u091F \u0932\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E\\n\\n4. \u092F\u0926\u093F \u0916\u0930\u0940\u0926\u093E\u0930\u0940 \u0938\u092B\u0932 \u0939\u094B\u0924\u0940 \u0939\u0948, \u0924\u094B \u0938\u093F\u0938\u094D\u091F\u092E \u0938\u0940\u0927\u0947 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u092C\u093E\u0927\u093E\u0913\u0902 \u0915\u0947 \u0905\u0928\u0941\u0938\u093E\u0930 \u092E\u0941\u0906\u0935\u091C\u093E \u0926\u0947\u0917\u093E\\n\\n5. \u092F\u0926\u093F \u0928\u0939\u0940\u0902 \u0916\u0930\u0940\u0926\u093E \u0917\u092F\u093E, \u0924\u094B \u0938\u093F\u0938\u094D\u091F\u092E \u0906\u092D\u0942\u0937\u0923 \u0916\u0930\u0940\u0926\u0928\u0947 \u092A\u0930 \u0916\u0930\u094D\u091A \u0915\u0940 \u0917\u0908 \u0930\u093E\u0936\u093F \u0935\u093E\u092A\u0938 \u0932\u0947 \u0932\u0947\u0917\u093E",
    "UILoginviolator": "\u092F\u0926\u093F \u0906\u092A\u0915\u0947 \u0916\u093E\u0924\u0947 \u092A\u0930 \u0928\u093F\u092F\u092E\u094B\u0902 \u0915\u0947 \u0909\u0932\u094D\u0932\u0902\u0918\u0928 \u0915\u093E \u0938\u0902\u0926\u0947\u0939 \u0939\u0948, \u0924\u094B \u0915\u0943\u092A\u092F\u093E \u0915\u094D\u0932\u092C\u090F\u0921\u092E\u093F\u0928 \u0938\u0947 \u0938\u0902\u092A\u0930\u094D\u0915 \u0915\u0930\u0947\u0902!",
