    "UILoading_Text_Decompressing": "\u0921\u0940\u0915\u0902\u092A\u094D\u0930\u0947\u0938\u093F\u0902\u0917 \u0938\u0902\u0938\u093E\u0927\u0928...",
    "UIBringInTips": "\u0916\u0930\u0940\u0926-\u0907\u0928 \u0930\u093E\u0936\u093F \u0914\u0930 \u091C\u092E\u093E, \u091C\u092E\u093E \u0930\u093E\u0936\u093F \u0915\u093E \u0909\u092A\u092F\u094B\u0917 \u0905\u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u092C\u0948\u0932\u0947\u0902\u0938 \u0936\u0940\u091F \u0915\u094B \u092C\u0926\u0932\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0915\u093F\u092F\u093E \u091C\u093E\u0924\u093E \u0939\u0948, \u0914\u0930 \u0936\u0947\u0937 \u091C\u092E\u093E \u0924\u093E\u0932\u093F\u0915\u093E \u0938\u0947 \u092C\u093E\u0939\u0930 \u0928\u093F\u0915\u0932\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0938\u093E\u092E\u093E\u0928\u094D\u092F \u0930\u0942\u092A \u0938\u0947 \u0935\u093E\u092A\u0938 \u0915\u0930 \u0926\u0940 \u091C\u093E\u090F\u0917\u0940",
