    "UIHitGamePlayTips1": "\u0915\u094D\u0930\u093F\u091F\u093F\u0915\u0932 \u0939\u093F\u091F \u0917\u0947\u092E\u092A\u094D\u0932\u0947",
    "UIHitGamePlayTips2": "\u0915\u094D\u0930\u093F\u091F \u0917\u0947\u092E\u092A\u094D\u0932\u0947 \u092E\u0947\u0902 \u092D\u093E\u0917 \u0932\u0947\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0906\u092A\u0915\u094B \u0939\u0930 {0} \u0930\u093E\u0909\u0902\u0921 \u092E\u0947\u0902 {1}\u092C\u0940\u092C\u0940 \u0915\u094D\u0930\u093F\u091F \u0935\u0948\u0932\u094D\u092F\u0942 \u0915\u093E \u0928\u093F\u0935\u0947\u0936 \u0915\u0930\u0928\u093E \u0939\u094B\u0917\u093E",
    "UIHitGamePlayTips3": "\u0917\u0902\u092D\u0940\u0930 \u0939\u093F\u091F \u091F\u094D\u0930\u093F\u0917\u0930\u093F\u0902\u0917 \u0938\u094D\u0925\u093F\u0924\u093F\u092F\u093E\u0901",
    "UIHitGamePlayTips4": "\u092E\u0939\u0924\u094D\u0935\u092A\u0942\u0930\u094D\u0923 \u0939\u093F\u091F \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E",
    "UIHitGamePlayTips5": "\u092C\u0940\u092C\u0940 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902",
    "UIHitGamePlayTips6": "\u0916\u0947\u0932 \u0936\u0941\u0930\u0942 \u0939\u094B\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926, \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0905\u0902\u0924\u0930\u093E\u0932 \u092A\u0930 \u0939\u093E\u0925\u094B\u0902 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u0928\u093F\u0930\u094D\u0927\u093E\u0930\u093F\u0924 \u0915\u0930\u0947\u0902\u0964 \u0915\u093E\u0930\u094D\u0921 \u092C\u093E\u0902\u091F\u0928\u0947 \u0938\u0947 \u092A\u0939\u0932\u0947, \u0938\u092D\u0940 \u092D\u093E\u0917 \u0932\u0947\u0928\u0947 \u0935\u093E\u0932\u0947 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0938\u0947\u091F \u092E\u0939\u0924\u094D\u0935\u092A\u0942\u0930\u094D\u0923 \u092E\u093E\u0928 \u092A\u0949\u091F \u092E\u0947\u0902 \u0921\u093E\u0932 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902\u0964 \u0915\u093E\u0930\u094D\u0921 \u092C\u093E\u0902\u091F\u0947 \u091C\u093E\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926, \u0935\u0947 \u0938\u0940\u0927\u0947 \u092B\u094D\u0932\u0949\u092A\u092B\u094D\u0932\u0949\u092A \u091A\u0930\u0923 \u092E\u0947\u0902 \u092A\u094D\u0930\u0935\u0947\u0936 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964 \u092F\u0926\u093F \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0947 \u091A\u093F\u092A\u094D\u0938 \u092E\u0939\u0924\u094D\u0935\u092A\u0942\u0930\u094D\u0923 \u0939\u093F\u091F \u092E\u093E\u0928 \u0915\u0947 \u0932\u093F\u090F \u0905\u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u0939\u0948\u0902, \u0924\u094B \u0935\u0947 \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u091C\u093E\u090F\u0902\u0917\u0947\u0964",
    "UIHitGamePlayTips7": "\u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u094B\u0921 \u092E\u0947\u0902, \u091A\u093E\u0932\u0942 \u0915\u0949\u0932\u091F\u093E\u0907\u092E \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "UIHitGamePlayTips8": "\u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u094B\u0921 \u092E\u0947\u0902, \u0915\u094D\u0930\u093F\u091F\u093F\u0915\u0932 \u0939\u093F\u091F \u092E\u094B\u0921 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "UIHitGamePlayTips9": "\u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u094B\u0921 \u092E\u0947\u0902, \u091A\u093E\u0930\u0932\u0942\u090F\u0913\u090F\u092B \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "UIHitGamePlayTips10": "\u091A\u093E\u0930\u0932\u0942\u090F\u0913\u090F\u092B, \u0914\u0930 \u0915\u094D\u0930\u093F\u091F\u093F\u0915\u0932 \u0939\u093F\u091F \u092E\u094B\u0921 \u0909\u092A\u0932\u092C\u094D\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948",
    "UIHitGamePlayTips11": "\u091A\u093E\u0932\u0942AOF, \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0917\u0947\u092E\u092A\u094D\u0932\u0947 \u091A\u093E\u0932\u0942 \u0915\u0930\u0928\u0947 \u092E\u0947\u0902 \u0905\u0938\u092E\u0930\u094D\u0925",
