    "UIAnteRandomJump3": "\u0905\u0927\u093F\u0915\u0924\u092E \u092A\u0942\u0930\u094D\u0935",
    "UIAnteRandomJump4": "\u0915\u0943\u092A\u092F\u093E \u0926\u0930\u094D\u091C \u0915\u0930\u0947\u0902",
    "UIAnteRandomJump5": "\u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u0905\u0902\u0924\u0930\u093E\u0932 \u092E\u093E\u0928",
    "UIAnteRandomJump6": "\u0938\u0947\u091F\u093F\u0902\u0917 \u0915\u0947 \u0928\u094D\u092F\u0942\u0928\u0924\u092E \u0914\u0930 \u0905\u0927\u093F\u0915\u0924\u092E \u090F\u0902\u091F\u0947 \u0905\u0902\u0924\u0930\u093E\u0932 \u092E\u093E\u0928 \u0914\u0930 \u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u0905\u0902\u0924\u0930\u093E\u0932 \u092E\u093E\u0928 \u0915\u0947 \u092E\u093E\u0927\u094D\u092F\u092E \u0938\u0947, \u0924\u093E\u0932\u093F\u0915\u093E \u0915\u0947 \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0939\u093E\u0925 \u092E\u0947\u0902 \u0928\u093F\u0935\u0947\u0936 \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u090F\u0902\u091F\u0947 \u092E\u0942\u0932\u094D\u092F \u0938\u0947\u091F\u093F\u0902\u0917 \u0915\u0947 \u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u0905\u0902\u0924\u0930\u093E\u0932 \u092E\u0942\u0932\u094D\u092F \u0915\u0947 \u0905\u0928\u0941\u0938\u093E\u0930 \u0905\u0902\u0924\u0930\u093E\u0932 \u092E\u0947\u0902 \u092C\u0947\u0924\u0930\u0924\u0940\u092C \u0922\u0902\u0917 \u0938\u0947 \u0915\u0942\u0926 \u0930\u0939\u093E \u0939\u0948",
    "UIAnteRandomJump7": "\u0928\u094D\u092F\u0942\u0928\u0924\u092E \u092A\u0942\u0930\u094D\u0935{0}, \u0905\u0927\u093F\u0915\u0924\u092E \u092A\u0942\u0930\u094D\u0935{1}, \u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u0905\u0902\u0924\u0930\u093E\u0932 \u091B\u0932\u093E\u0902\u0917 {2}",
    "UIAnteRandomJump8": "\u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u091B\u0932\u093E\u0902\u0917 \u0938\u0947 \u092A\u0939\u0932\u0947 \u0928\u094D\u092F\u0942\u0928\u0924\u092E \u092E\u093E\u0928 0.1",
    "UIAnteRandomJump9": "\u0939\u0948 \u092A\u0942\u0930\u094D\u0935 \u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u091B\u0932\u093E\u0902\u0917 \u0905\u0927\u093F\u0915\u0924\u092E \u092E\u093E\u0928 \u0938\u0947 \u0905\u0927\u093F\u0915 \u0939\u0948",
