    "Mahjong_DiscardChangeTips": "\u0917\u0941\u092E \u0915\u093E\u0930\u094D\u0921 \u092A\u0930\u093F\u0935\u0930\u094D\u0924\u0928: \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0926\u094D\u0935\u093E\u0930\u093E \u0917\u0941\u092E \u0915\u093E\u0930\u094D\u0921 \u0915\u093E \u0928\u093F\u0930\u094D\u0927\u093E\u0930\u0923 \u092A\u0942\u0930\u093E \u0915\u0930\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926, \u0936\u0941\u0930\u0941\u0906\u0924\u0940 \u0939\u093E\u0925 \u092E\u0947\u0902 \u0917\u0941\u092E \u0915\u093E\u0930\u094D\u0921 \u0915\u094B \u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u0930\u0942\u092A \u0938\u0947 \u0926\u0942\u0938\u0930\u0947 \u0938\u0942\u091F \u0915\u0947 \u0915\u093E\u0930\u094D\u0921 \u0938\u0947 \u092C\u0926\u0932 \u0926\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E\u0964 \u092C\u093E\u0926 \u0915\u0940 \u0915\u093E\u0930\u094D\u0921 \u0916\u0947\u0932\u0928\u0947 \u0915\u0940 \u092A\u094D\u0930\u0915\u094D\u0930\u093F\u092F\u093E \u092E\u0947\u0902, \u0917\u093E\u092F\u092C \u0915\u093E\u0930\u094D\u0921\u094B\u0902 \u0915\u094B \u0905\u092D\u0940 \u092D\u0940 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0926\u094D\u0935\u093E\u0930\u093E \u092E\u0948\u0928\u094D\u092F\u0941\u0905\u0932 \u0930\u0942\u092A \u0938\u0947 \u0916\u0947\u0932\u093E \u091C\u093E\u0928\u093E \u0906\u0935\u0936\u094D\u092F\u0915 \u0939\u0948, \u0914\u0930 \u0939\u0942 \u0915\u093E\u0930\u094D\u0921 \u0915\u0947 \u0939\u093E\u0925 \u092E\u0947\u0902 \u0915\u094B\u0908 \u092D\u0940 \u0917\u093E\u092F\u092C \u0915\u093E\u0930\u094D\u0921 \u0928\u0939\u0940\u0902 \u0939\u094B \u0938\u0915\u0924\u093E \u0939\u0948;",
    "Mahjong_BloodRiveerJokerTips": '\u0932\u093E\u0932 \u0915\u0947\u0902\u0926\u094D\u0930 "\u0930\u0947\u0921\u0930" \u0939\u0948, \u091C\u094B \u090F\u0915 \u0938\u093E\u0930\u094D\u0935\u092D\u094C\u092E\u093F\u0915 \u0915\u093E\u0930\u094D\u0921 \u0939\u0948, \u0914\u0930 \u0915\u093F\u0938\u0940 \u092D\u0940 \u0915\u093E\u0930\u094D\u0921 \u0915\u0947 \u0938\u094D\u0925\u093E\u0928 \u092A\u0930 \u0915\u093F\u0938\u0940 \u092D\u0940 \u0938\u0902\u092F\u094B\u091C\u0928 \u092E\u0947\u0902 \u0909\u092A\u092F\u094B\u0917 \u0915\u093F\u092F\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948; \u0906\u092A \u0917\u0947\u092E \u092E\u0947\u0902 "\u0930\u0947\u0921 \u0938\u0947\u0902\u091F\u0930" \u0930\u0947\u0921\u0930\u094D\u0938 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u091A\u0941\u0928 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902; \u092F\u093E \u0930\u0947\u0921\u0930 \u0915\u0947 \u092C\u093F\u0928\u093E \u0916\u0947\u0932\u0928\u093E \u091A\u0941\u0928\u0947\u0902;',
    "Mahjong_BloodRiverRateTypeOptionTips": '\u091A\u0941\u0928\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F 6 \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930 \u0939\u0948\u0902, \u0914\u0930 \u0938\u092D\u0940 \u0921\u093F\u092B\u093C\u0949\u0932\u094D\u091F \u0915\u0940 \u091C\u093E\u0901\u091A \u0915\u0930 \u0932\u0940 \u0917\u0908 \u0939\u0948;\\n\u090F\u0915\u0964 \u092F\u0926\u093F \u091A\u0941\u0928\u093E \u0917\u092F\u093E \u0939\u0948, \u0924\u094B \u0935\u093F\u0915\u0932\u094D\u092A\u094B\u0902 \u092E\u0947\u0902 \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930\u094B\u0902 \u0915\u094B \u0916\u0947\u0932\u093E \u091C\u093E \u0938\u0915\u0924\u093E \u0939\u0948, \u0914\u0930 \u0938\u0902\u092C\u0902\u0927\u093F\u0924 \u0917\u0941\u0923\u0915\u094B\u0902 \u0915\u0947 \u0905\u0928\u0941\u0938\u093E\u0930 \u0917\u0923\u0928\u093E \u0915\u0940 \u091C\u093E \u0938\u0915\u0924\u0940 \u0939\u0948;\\n\u092C\u0940\u0964 \u092F\u0926\u093F \u091C\u093E\u0901\u091A \u0928\u0939\u0940\u0902 \u0915\u0940 \u0917\u0908 \u0939\u0948, \u0924\u094B \u0935\u093F\u0915\u0932\u094D\u092A\u094B\u0902 \u092E\u0947\u0902 \u0915\u093E\u0930\u094D\u0921 \u092A\u094D\u0930\u0915\u093E\u0930 \u0928\u0939\u0940\u0902 \u091A\u0932\u093E\u090F \u091C\u093E \u0938\u0915\u0924\u0947 \u0939\u0948\u0902;\\n\u0909\u0928\u092E\u0947\u0902 \u0938\u0947, "\u092E\u0947\u0928\u0915\u093F\u0902\u0917" \u090F\u0915 \u0905\u0932\u0917 \u0917\u0923\u0928\u093E \u0939\u0948, \u0914\u0930 \u0928\u093F\u092F\u092E \u0915\u093E \u0905\u0930\u094D\u0925 \u0939\u0948: \u0938\u094D\u092A\u0930\u094D\u0936, \u0913\u092A\u0928 \u092C\u093E\u0930, \u0905\u0902\u0924\u093F\u092E \u0938\u094D\u0935-\u0938\u094D\u092A\u0930\u094D\u0936 \u0914\u0930 \u092C\u0902\u0926\u0942\u0915 \u092B\u093E\u092F\u0930\u093F\u0902\u0917 \u091C\u0948\u0938\u0940 \u0915\u094B\u0908 \u091F\u093E\u0907\u0932 \u0928\u0939\u0940\u0902\u0964 \u090F\u0915 \u091B\u093F\u092A\u093E \u0939\u0941\u0906 \u0916\u0902\u092D\u093E \u0905\u092D\u0940 \u092D\u0940 \u0938\u094D\u092A\u0937\u094D\u091F \u092E\u093E\u0928\u093E \u091C\u093E\u0924\u093E \u0939\u0948;\\n\u0939\u0942 \u091F\u093E\u0907\u0932\u094D\u0938 +3/+5 \u092C\u093E\u0930: \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0917\u0947\u092E \u092E\u0947\u0902, \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0939\u0942 \u091F\u093E\u0907\u0932 \u0905\u0924\u093F\u0930\u093F\u0915\u094D\u0924 \u0939\u094B\u0924\u0940 \u0939\u0948 (\u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0947 \u092A\u093E\u0938 \u0939\u0942 \u091F\u093E\u0907\u0932\u094D\u0938 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E - 1) x 5 \u092C\u093E\u0930\u0964 \u0909\u0926\u093E\u0939\u0930\u0923 \u0915\u0947 \u0932\u093F\u090F, \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0940 \u092A\u0939\u0932\u0940 \u091C\u0940\u0924\u0928\u0947 \u0935\u093E\u0932\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u0938\u093E\u092E\u093E\u0928\u094D\u092F \u0917\u0941\u0923\u091C \u0939\u0948, \u0926\u0942\u0938\u0930\u0940 \u092C\u093E\u0930 \u0938\u093E\u092E\u093E\u0928\u094D\u092F \u0917\u0941\u0923\u091C + 5 \u0939\u0948, \u0914\u0930 \u0924\u0940\u0938\u0930\u0940 \u092C\u093E\u0930 \u0938\u093E\u092E\u093E\u0928\u094D\u092F \u0917\u0941\u0923\u091C + 10 \u092C\u093E\u0930 \u0939\u0948;',
    "Mahjong_ResultRateNone": "\u0935\u093F\u091C\u0947\u0924\u093E \u0915\u093E\u0930\u094D\u0921 \u0926\u094B\u0917\u0941\u0928\u093E \u0928\u0939\u0940\u0902 \u0939\u0948",
    "Mahjong_ResultRateAdd": "\u0935\u093F\u091C\u0947\u0924\u093E \u0915\u093E\u0930\u094D\u0921 +{0} \u092C\u093E\u0930",
