    "OpCodeString_SNGBI": "\u090F\u0938\u090F\u0928\u091C\u0940 \u092C\u093E\u092F-\u0907\u0928",
    "OpCodeString_SNGAW": "\u090F\u0938\u090F\u0928\u091C\u0940 \u092A\u0941\u0930\u0938\u094D\u0915\u093E\u0930 \u092A\u0942\u0932 \u0907\u0928\u093E\u092E",
    "OpCodeString_SNGQUIT": "\u090F\u0938\u090F\u0928\u091C\u0940 \u0928\u093F\u0915\u093E\u0938\u0940",
