    "OpCodeString_CLUBPFTSNG": "\u0915\u094D\u0932\u092C\u090F\u0938\u090F\u0928\u091C\u0940\u0930\u093E\u0915\u0947 \u0932\u093E\u092D \u0936\u0947\u092F\u0930",
    "OpCodeString_SELFSNG": "SNG\u0930\u093E\u0915\u0947 \u0932\u093E\u092D \u0936\u0947\u092F\u0930",
