    "OpCodeString_SNGCREATE": "\u090F\u0938\u090F\u0928\u091C\u0940 \u092A\u094D\u0930\u0924\u093F\u092F\u094B\u0917\u093F\u0924\u093E \u092C\u0928\u093E\u090F\u0902",
    "OpCodeString_SNGRECORD": "\u090F\u0938\u090F\u0928\u091C\u0940 \u0930\u093F\u0915\u0949\u0930\u094D\u0921\u093F\u0902\u0917 \u0936\u0941\u0932\u094D\u0915",
    "OpCodeString_SNGRECRTN": "\u090F\u0938\u090F\u0928\u091C\u0940 \u0930\u093F\u0915\u0949\u0930\u094D\u0921\u093F\u0902\u0917 \u0936\u0941\u0932\u094D\u0915 \u0935\u093E\u092A\u0938 \u0915\u0930\u0947\u0902",
    "UIClub_Manager_PrologueSetTitle": "\u0916\u0947\u0932 \u0906\u0930\u0902\u092D\u093F\u0915 \u092A\u094D\u0930\u0926\u0930\u094D\u0936\u0928",
