    "Mahjong_BuyHorse": "\u0918\u094B\u0921\u093C\u093E \u0916\u0930\u0940\u0926\u0947\u0902",
    "Mahjong_BuyHorseTips": '\\n2, \u0916\u0947\u0932 \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926, \u0918\u094B\u0921\u093C\u093E \u0916\u094B\u0932\u093E \u091C\u093E\u090F\u0917\u093E, \u0914\u0930 \u0917\u0932\u0924 \u0915\u093E\u0930\u094D\u0921 \u0935\u093E\u0932\u093E \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u093E\u0930\u094D\u0921 \u092C\u093F\u0902\u0926\u0941\u0913\u0902 \u0915\u0947 \u0905\u0928\u0941\u0938\u093E\u0930, \u0936\u0947\u0937 \u0915\u093E\u0930\u094D\u0921 \u0935\u0949\u0932 \u092F\u093E \u0928\u090F \u0915\u093E\u0930\u094D\u0921 (\u0930\u0942\u092E \u0935\u093F\u0915\u0932\u094D\u092A) \u0938\u0947 \u092F\u093E\u0926\u0943\u091A\u094D\u091B\u093F\u0915 \u0930\u0942\u092A \u0938\u0947 \u0907\u0938\u0947 \u0909\u0924\u094D\u092A\u0928\u094D\u0928 \u0915\u0930\u0947\u0917\u093E: \u0935\u093E\u0928 \u091F\u093F\u092F\u093E\u0913 \u091F\u094D\u092F\u0942\u092C 1, 5, 9, \u0921\u094B\u0902\u0917\u092B\u0947\u0902\u0917 "\u091C\u0940\u0924\u0928\u0947 \u0935\u093E\u0932\u093E \u0918\u094B\u0921\u093C\u093E" \u0939\u0948, \u0914\u0930 \u0905\u0928\u094D\u092F "\u0939\u093E\u0930\u0928\u0947 \u0935\u093E\u0932\u0947 \u0918\u094B\u0921\u093C\u0947" \u0939\u0948\u0902;\\n3, \u092F\u0926\u093F \u0936\u0947\u0937 \u091F\u093E\u0907\u0932 \u0915\u0940 \u0926\u0940\u0935\u093E\u0930 \u0918\u094B\u0921\u093C\u0947 \u0915\u0940 \u091F\u093E\u0907\u0932\u094B\u0902 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u0915\u0947 \u0932\u093F\u090F \u092A\u0930\u094D\u092F\u093E\u092A\u094D\u0924 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0924\u094B \u0936\u0947\u0937 \u0915\u094B \u0916\u094B\u0932\u0947\u0902; 4, \u092F\u0926\u093F \u0906\u092A "\u0935\u093F\u0928 \u0939\u0949\u0930\u094D\u0938" \u0916\u0930\u0940\u0926\u0924\u0947 \u0939\u0948\u0902, \u0924\u094B \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 "\u0935\u093F\u0928 \u0939\u0949\u0930\u094D\u0938" \u0939\u0949\u0930\u094D\u0938 \u091F\u093E\u0907\u0932 \u0905\u0928\u094D\u092F \u0924\u0940\u0928 \u0905\u0928\u0939\u0949\u0930\u094D\u0938\u094D\u0921 \u091F\u093E\u0907\u0932\u094D\u0938 \u0938\u0947 \u092E\u0947\u0932 \u0916\u093E\u0924\u0940 \u0939\u0948, \u0914\u0930 \u092D\u0941\u0917\u0924\u093E\u0928 \u0924\u0940\u0928 \u0932\u094B\u0917\u094B\u0902 \u092E\u0947\u0902 \u0938\u0947 \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0915\u0947 \u0932\u093F\u090F \u0926\u094B\u0917\u0941\u0928\u093E \u0939\u094B\u0917\u093E; \u092F\u0926\u093F \u0906\u092A "\u0916\u094B\u092F\u093E \u0939\u0941\u0906 \u0918\u094B\u0921\u093C\u093E" \u0916\u0930\u0940\u0926\u0924\u0947 \u0939\u0948\u0902, \u0924\u094B \u0915\u094B\u0908 \u092E\u0941\u0906\u0935\u091C\u093E \u0928\u0939\u0940\u0902 \u0926\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E;\\n4, \u0939\u0949\u0930\u094D\u0938 \u091F\u093E\u0907\u0932\u094D\u0938 \u0915\u0947 \u0928\u093F\u092A\u091F\u093E\u0928 \u092E\u0947\u0902 \u0915\u094B\u0902\u0917 \u091F\u093E\u0907\u0932\u0947\u0902 \u0936\u093E\u092E\u093F\u0932 \u0928\u0939\u0940\u0902 \u0939\u0948\u0902;',
