    "UICreateTable_QuickChangeRoom": "\u0924\u094D\u0935\u0930\u093F\u0924 \u0924\u093E\u0932\u093F\u0915\u093E \u092A\u0930\u093F\u0935\u0930\u094D\u0924\u0928",
    "UICreateTable_QuickChangeRoomTips": "\u0924\u094D\u0935\u0930\u093F\u0924 \u0924\u093E\u0932\u093F\u0915\u093E \u092A\u0930\u093F\u0935\u0930\u094D\u0924\u0928, \u090F\u0915 \u0939\u093E\u0925 \u0915\u0940 \u0938\u092E\u093E\u092A\u094D\u0924\u093F \u0915\u0947 \u092C\u093E\u0926, \u0938\u092E\u093E\u0928 \u0938\u094D\u0924\u0930 \u0915\u0947 \u0924\u094D\u0935\u0930\u093F\u0924 \u0924\u093E\u0932\u093F\u0915\u093E \u092A\u0930\u093F\u0935\u0930\u094D\u0924\u0928 \u092B\u093C\u0902\u0915\u094D\u0936\u0928 \u0915\u093E \u0938\u092E\u0930\u094D\u0925\u0928 \u0915\u0930\u0924\u093E \u0939\u0948",
