    "UICreateTableSquidSingleTips": "\u090F\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u0915\u0947\u0935\u0932 \u090F\u0915 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u093F\u0932 \u0938\u0915\u0924\u093E \u0939\u0948\u0964 \u091C\u092C \u0907\u0938 \u0930\u093E\u0909\u0902\u0921 \u092E\u0947\u0902 \u0915\u0947\u0935\u0932 \u090F\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u0924\u093E \u0939\u0948, \u0924\u094B \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0917\u0947\u092E \u0907\u0938 \u0930\u093E\u0909\u0902\u0921 \u092E\u0947\u0902 \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948, \u0914\u0930 \u091C\u093F\u0928 \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u094B \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u093E\u0930\u094D\u0915 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u0924\u093E \u0939\u0948, \u0909\u0928\u094D\u0939\u0947\u0902 \u092D\u0941\u0917\u0924\u093E\u0928 \u0915\u0930\u0928\u093E \u0939\u094B\u0917\u093E\\n\u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092C\u094B\u0928\u0938 = \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u0942\u0932\u094D\u092F \u0928\u093F\u0930\u094D\u0927\u093E\u0930\u093F\u0924 \u0915\u0930\u0947\u0902\\n\u092E\u0941\u0906\u0935\u091C\u093C\u0947 \u0915\u0940 \u0930\u093E\u0936\u093F = \u0907\u0938 \u0926\u094C\u0930 \u092E\u0947\u0902 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E * \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u093E \u092E\u0942\u0932\u094D\u092F",
    "UICreateTableSquidMubleTips": '\u090F\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u0915\u0908 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u093F\u0932 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u091C\u092C \u0907\u0938 \u0930\u093E\u0909\u0902\u0921 \u092E\u0947\u0902 "\u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u090A\u092A\u0930\u0940 \u0938\u0940\u092E\u093E \u0924\u0915 \u092A\u0939\u0941\u0901\u091A \u091C\u093E\u0924\u093E \u0939\u0948" \u092F\u093E "\u0915\u0947\u0935\u0932 \u090F\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u0924\u093E \u0939\u0948", \u0924\u094B \u0907\u0938 \u0930\u093E\u0909\u0902\u0921 \u092E\u0947\u0902 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0917\u0947\u092E \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948, \u0914\u0930 \u091C\u093F\u0928 \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u094B \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u093E, \u0909\u0928\u094D\u0939\u0947\u0902 \u0915\u094D\u0930\u092E\u0936\u0903 \u092E\u0941\u0906\u0935\u091C\u093E \u0926\u0947\u0928\u093E \u0939\u094B\u0917\u093E\u0964 \u090F\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u094B \u091C\u093F\u0924\u0928\u0947 \u0905\u0927\u093F\u0915 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u093F\u0932\u0947\u0902\u0917\u0947, \u0907\u0928\u093E\u092E \u0909\u0924\u0928\u093E \u0939\u0940 \u0905\u0927\u093F\u0915 \u0939\u094B\u0917\u093E\u0964\\n\u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092C\u094B\u0928\u0938 = \u0930\u0916\u0947 \u0917\u090F \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E * \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u093E \u092E\u0942\u0932\u094D\u092F * \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0928 \u0915\u093F\u090F \u0917\u090F \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E\\n\u092A\u094D\u0930\u0924\u093F \u0935\u094D\u092F\u0915\u094D\u0924\u093F \u092E\u0941\u0906\u0935\u091C\u093C\u093E \u0930\u093E\u0936\u093F = \u0907\u0938 \u0916\u0947\u0932 \u092E\u0947\u0902 \u0909\u0924\u094D\u092A\u093E\u0926\u093F\u0924 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E * \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u093E \u092E\u0942\u0932\u094D\u092F',
    "UICreateTableSquidCoinTips": "\u092E\u093E\u0924\u094D\u0930\u093E \u092A\u094D\u0930\u0924\u093F \u0935\u093F\u0926\u094D\u0930\u0942\u092A",
    "UICreateTableSquidNumTips": "\u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E. \u0939\u0930 \u092C\u093E\u0930 \u091C\u0940\u0924\u0928\u0947 \u092A\u0930 \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u094B \u090F\u0915 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092E\u093F\u0932 \u0938\u0915\u0924\u093E \u0939\u0948\u0964 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E \u0938\u0940\u092E\u093F\u0924 \u0939\u0948\u0964 \u0939\u0921\u093C\u092A\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0939\u093F\u0938\u093E\u092C-\u0915\u093F\u0924\u093E\u092C \u0924\u092F \u0939\u094B \u091C\u093E\u090F\u0917\u093E.",
    "UICreateTableSquidClassicTips": "\u090F\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0947\u0935\u0932 1 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0915\u0930 \u0938\u0915\u0924\u093E \u0939\u0948\u0964 \u091C\u092C \u0907\u0938 \u0930\u093E\u0909\u0902\u0921 \u092E\u0947\u0902 \u0915\u0947\u0935\u0932 1 \u0916\u093F\u0932\u093E\u0921\u093C\u093F\u092F\u094B\u0902 \u0915\u094B \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u0924\u093E \u0939\u0948, \u0924\u094B \u0907\u0938 \u0930\u093E\u0909\u0902\u0921 \u092E\u0947\u0902 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0917\u0947\u092E \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B \u091C\u093E\u0924\u093E \u0939\u0948",
    "UICreateTableSquidBattleTips": "\u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0939\u0930 \u092C\u093E\u0930 \u091C\u0940\u0924\u0928\u0947 \u092A\u0930 \u090F\u0915 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u092A\u094D\u0930\u093E\u092A\u094D\u0924 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0938\u094D\u0915\u094D\u0935\u093F\u0921 \u0915\u0940 \u0915\u0941\u0932 \u0938\u0902\u0916\u094D\u092F\u093E \u0938\u0940\u092E\u093F\u0924 \u0939\u0948\u0964 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0939\u0921\u093C\u092A\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926 \u0928\u093F\u092A\u091F \u091C\u093E\u090F\u0917\u093E",
    "UIMineMallUSDTShopPayDialogScanTip ": "\u091F\u094D\u0930\u093E\u0902\u0938\u092B\u0930 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F QR \u0915\u094B\u0921 \u0938\u094D\u0915\u0948\u0928 \u0915\u0930\u0947\u0902",
