    "OpCodeString_PROPVSEFFECT": "\u092A\u094D\u0930\u0949\u092A\u094D\u0938 \u0916\u0930\u0940\u0926\u0947\u0902 - \u0935\u0940\u0921\u093F\u092F\u094B \u092A\u094D\u0930\u092D\u093E\u0935",
    "OpCodeString_PROPTABLETHEME": "\u092A\u094D\u0930\u0949\u092A\u094D\u0938 \u0916\u0930\u0940\u0926\u0947\u0902 - \u092E\u0947\u091C\u093C\u092A\u094B\u0936",
    "OpCodeString_PROPAVATAR": "\u092A\u094D\u0930\u0949\u092A\u094D\u0938 \u0916\u0930\u0940\u0926\u0947\u0902 - \u0905\u0935\u0924\u093E\u0930",
    "OpCodeString_MALLGOODS": "\u092E\u0949\u0932 \u0909\u0924\u094D\u092A\u093E\u0926",
    "UIMahjong_LeaveCountDownTips": "\u0915\u094D\u092F\u094B\u0902\u0915\u093F \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u092C\u0940\u091A \u092E\u0947\u0902 \u0939\u0940 \u091A\u0932\u093E \u091C\u093E\u0924\u093E \u0939\u0948, \u092F\u0926\u093F \u0915\u094B\u0908 \u0928\u092F\u093E \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0936\u093E\u092E\u093F\u0932 \u0928\u0939\u0940\u0902 \u0939\u094B\u0924\u093E \u0939\u0948 \u0924\u094B \u0909\u0932\u091F\u0940 \u0917\u093F\u0928\u0924\u0940 \u0915\u0947 \u092C\u093E\u0926 \u091F\u0947\u092C\u0932 \u0915\u094B \u092D\u0902\u0917 \u0915\u0930 \u0926\u093F\u092F\u093E \u091C\u093E\u090F\u0917\u093E\u0964",
    "UIMahjong_LeaveTips": "\u0915\u094D\u092F\u094B\u0902\u0915\u093F \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u092C\u0940\u091A \u092E\u0947\u0902 \u0939\u0940 \u091A\u0932\u093E \u091C\u093E\u0924\u093E \u0939\u0948, \u091F\u0947\u092C\u0932 \u091C\u0932\u094D\u0926\u0940 \u092D\u0902\u0917 \u0939\u094B \u091C\u093E\u090F\u0917\u0940",
    "UIMahjong_DelayTips": "\u0924\u093E\u0932\u093F\u0915\u093E \u0930\u093E\u0909\u0902\u0921 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u092C\u0922\u093C\u093E\u0924\u0940 \u0939\u0948:",
