    "UIEgg_GameRuleTips": "\u0926\u094B\u0939\u0930\u0940\u0915\u0930\u0923 \u0915\u0940 \u0905\u0928\u0941\u092E\u0924\u093F: \u0915\u093E\u0930\u094D\u0921 \u092C\u093E\u0902\u091F\u0947 \u091C\u093E\u0928\u0947 \u0915\u0947 \u092C\u093E\u0926, \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0926\u094B\u0917\u0941\u0928\u093E \u0915\u0930\u0928\u093E \u092F\u093E \u0926\u094B\u0917\u0941\u0928\u093E \u0928 \u0915\u0930\u0928\u093E \u091A\u0941\u0928 \u0938\u0915\u0924\u093E \u0939\u0948, \u091C\u093F\u0938\u0915\u0947 \u092A\u0930\u093F\u0923\u093E\u092E\u0938\u094D\u0935\u0930\u0942\u092A \u0917\u0941\u0923\u0915 *2\\n\u0915\u093E\u0930\u094D\u0921 \u0930\u093F\u0915\u0949\u0930\u094D\u0921\u0930: \u091A\u093E\u0932\u0942 \u0939\u094B\u0928\u0947 \u092A\u0930, \u091F\u0947\u092C\u0932\\n\u092E\u0947\u0902 \u090F\u0915 \u0915\u093E\u0930\u094D\u0921 \u0930\u093F\u0915\u0949\u0930\u094D\u0921\u093F\u0902\u0917 \u092B\u093C\u0902\u0915\u094D\u0936\u0928 \u0939\u094B\u0924\u093E \u0939\u0948 \u092C\u091A\u0947 \u0939\u0941\u090F 10 \u0915\u093E\u0930\u094D\u0921\u094B\u0902 \u0915\u093E \u092A\u094D\u0930\u0926\u0930\u094D\u0936\u0928: \u0938\u093E\u092E\u093E\u0928\u094D\u092F \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0915\u0947 \u0939\u093E\u0925 \u092E\u0947\u0902 \u092C\u091A\u0947 \u0939\u0941\u090F \u0915\u093E\u0930\u094D\u0921\u094B\u0902 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E \u092A\u094D\u0930\u0926\u0930\u094D\u0936\u093F\u0924 \u0928\u0939\u0940\u0902 \u0939\u094B\u0924\u0940 \u0939\u0948, \u0932\u0947\u0915\u093F\u0928 \u092F\u0939 \u0924\u092C \u092A\u094D\u0930\u0926\u0930\u094D\u0936\u093F\u0924 \u0939\u094B\u0917\u0940 \u091C\u092C \u091A\u093E\u0930\u0932\u0942 \u0915\u0947 \u092A\u093E\u0938 10 \u0915\u093E\u0930\u094D\u0921 \u092C\u091A\u0947 \u0939\u094B\u0902\u0917\u0947\u0964",
