    "UICreateMahjongMtt27": "\u092F\u0939 \u092A\u094D\u0930\u0924\u093F\u092F\u094B\u0917\u093F\u0924\u093E \u0930\u093F\u092A\u0940\u091F \u0938\u0947\u091F\u093F\u0902\u0917 \u0915\u093E \u0939\u093F\u0938\u094D\u0938\u093E \u0939\u0948, \u092A\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0939\u091F\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0915\u0943\u092A\u092F\u093E \u092A\u0939\u0932\u0947 \u0930\u093F\u092A\u0940\u091F \u0935\u093F\u0915\u0932\u094D\u092A \u0915\u094B \u0905\u0915\u094D\u0937\u092E \u0915\u0930\u0947\u0902\u0964 \u092F\u0926\u093F \u0905\u0915\u094D\u0937\u092E \u0928\u0939\u0940\u0902 \u0915\u093F\u092F\u093E \u0917\u092F\u093E \u0939\u0948, \u0924\u094B \u092E\u093F\u0932\u093E\u0928 \u0938\u094D\u0935\u091A\u093E\u0932\u093F\u0924 \u0930\u0942\u092A \u0938\u0947 \u092A\u0941\u0928\u0903 \u092C\u0928\u093E\u090F \u091C\u093E\u090F\u0902\u0917\u0947",
