    "UICreateMahjongMttIllustrate4": "\u090F\u092E\u091F\u0940\u091F\u0940 \u0936\u0941\u0932\u094D\u0915",
    "UICreateMahjongMttIllustrate5": '\u092E\u0942\u0932 \u0915\u0940\u092E\u0924: \u092A\u094D\u0930\u0924\u093F \u0935\u094D\u092F\u0915\u094D\u0924\u093F \u0907\u0915\u093E\u0908 \u0915\u0940\u092E\u0924 * \u0906\u0935\u0947\u0926\u0915\u094B\u0902 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E\\n\u0930\u093F\u092F\u093E\u092F\u0924\u0940 \u092E\u0942\u0932\u094D\u092F: \u091B\u0942\u091F \u0915\u0947 \u092C\u093E\u0926 \u092A\u094D\u0930\u0924\u093F \u0935\u094D\u092F\u0915\u094D\u0924\u093F \u0907\u0915\u093E\u0908 \u092E\u0942\u0932\u094D\u092F "\u0906\u0935\u0947\u0926\u0915\u094B\u0902 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E\\n\u0909\u0926\u093E\u0939\u0930\u0923 \u0915\u0947 \u0932\u093F\u090F: \u092A\u094D\u0930\u0924\u093F \u0916\u093F\u0932\u093E\u0921\u093C\u0940 \u0907\u0915\u093E\u0908 \u092E\u0942\u0932\u094D\u092F 2\u0921\u0947\u092E\u0902\u0921 \u0939\u0948, \u0914\u0930 \u092A\u0902\u091C\u0940\u0915\u0930\u0923 \u0915\u0940 \u0938\u0902\u0916\u094D\u092F\u093E 200 \u0939\u0948, \u0936\u0941\u0932\u094D\u0915 \u0939\u0948: 2*200',
    "UICreateMahjongMttIllustrate6": "\u0935\u0940\u0921\u093F\u092F\u094B \u091F\u0947\u092C\u0932 \u091A\u093E\u0930\u094D\u091C",
