    "Mahjong_RuleContent2_2": "\u30AB\u30FC\u30C9\u3092\u5931\u3063\u305F\u4EBA\u306F\u9283\u3092\u30AF\u30EA\u30C3\u30AF\u3057\u305F\u30D7\u30EC\u30FC\u30E4\u30FC\u306E\u30B9\u30B3\u30A2\u3092\u96C6\u3081\u3001\u4ED6\u306E 3 \u4EBA\u306E\u30D7\u30EC\u30FC\u30E4\u30FC\u304C\u81EA\u5206\u3067\u30AB\u30FC\u30C9\u3092\u5F15\u3044\u305F\u5834\u5408\u306B\u652F\u6255\u3044\u307E\u3059\u3002\u30AB\u30FC\u30C9\u3092\u7D1B\u5931\u3057\u305F\u30D7\u30EC\u30A4\u30E4\u30FC\u306F\u30B2\u30FC\u30E0\u306B\u53C2\u52A0\u3067\u304D\u306A\u304F\u306A\u308A\u3001\u81EA\u7531\u306B\u9000\u5834\u3067\u304D\u307E\u3059\u3002",
    "Mahjong_RuleTitle3": "\u30AB\u30FC\u30C9\u3092 3 \u679A\u5909\u66F4\u3057\u307E\u3059",
