    "Mahjong_RuleTitle4": "\u30C9\u30A2\u304C 1 \u3064\u3042\u308A\u307E\u305B\u3093",
    "Mahjong_RuleContent4_1": "\u30AB\u30FC\u30C9\u304C\u914D\u3089\u308C\u305F\u5F8C\u3001\u30D7\u30EC\u30A4\u30E4\u30FC\u306F\u958B\u59CB\u624B\u3067\u300C\u6B20\u640D\u300D\u3068\u3057\u3066\u30B9\u30FC\u30C8 (\u30C1\u30E5\u30FC\u30D6\u3001\u30D0\u30FC\u3001\u4E07) \u306E\u30AB\u30FC\u30C9\u3092\u6C7A\u5B9A\u3057\u3066\u30D7\u30EC\u30A4\u3059\u308B\u5FC5\u8981\u304C\u3042\u308A\u307E\u3059\u3002\u3064\u307E\u308A\u3001\u30B2\u30FC\u30E0\u5168\u4F53\u3092\u901A\u3058\u3066\u3001\u30D7\u30EC\u30A4\u30E4\u30FC\u306F\u305D\u306E\u30B9\u30FC\u30C8\u306E\u30AB\u30FC\u30C9\u3092\u3059\u3079\u3066\u6368\u3066\u3001Hu \u30AB\u30FC\u30C9\u3092\u7D44\u307F\u5408\u308F\u305B\u308B\u305F\u3081\u306B\u6B8B\u308A\u306E 2 \u3064\u306E\u30B9\u30FC\u30C8\u306E\u307F\u3092\u4F7F\u7528\u3059\u308B\u5FC5\u8981\u304C\u3042\u308A\u307E\u3059\u3002",
