    "Mahjong_StandardRuleContent1_1": "\u80E1\u3092\u6253\u5012\u3059\u308B\u306B\u306F\u3001\u5358\u8A9E\u30AB\u30FC\u30C9\u3092\u542B\u3080 136 \u679A\u306E\u30AB\u30FC\u30C9\u3092\u4F7F\u7528\u3057\u307E\u3059 (\u3064\u307E\u308A\u3001\u6771\u3001\u5357\u3001\u897F\u3001\u5317\u3001\u4E2D\u3001\u30D5\u30A1\u3001\u767D)\u3002",
    "Mahjong_StandardRuleContent1_2": "\u30B5\u30A4\u30B3\u30ED\u3092\u632F\u3063\u3066\u30C7\u30A3\u30FC\u30E9\u30FC\u306BOK\u3092\u51FA\u3057\u3001\u6700\u521D\u306BHu\u30AB\u30FC\u30C9\u3092\u51FA\u3057\u305F\u30D7\u30EC\u30A4\u30E4\u30FC\u304C\u30D0\u30F3\u30AB\u30FC\u3068\u306A\u308A\u307E\u3059\u3002\u9283\u304C\u8907\u6570\u56DE\u767A\u5C04\u3055\u308C\u305F\u5834\u5408\u3001\u6557\u8005\u306F\u30D0\u30F3\u30AB\u30FC\u306B\u306A\u308A\u307E\u3059\u3002\u30B2\u30FC\u30E0\u306B\u8CA0\u3051\u305F\u5834\u5408\u3001\u30D0\u30F3\u30AB\u30FC\u306F\u30D0\u30F3\u30AF\u3092\u7D9A\u3051\u307E\u3059\u3002",
