    "Mahjong_StandardRuleContent5_2": "\u8D64\u30D2\u30C3\u30C8\u306F\u56FA\u5B9A\u30ED\u30FC\u30B0\u306B\u3059\u308B\u3053\u3068\u3082\u3001\u3053\u306E\u30E9\u30A6\u30F3\u30C9\u306B\u30ED\u30FC\u30B0\u3092\u6301\u305F\u306A\u3044\u3053\u3068\u3082\u9078\u629E\u3067\u304D\u307E\u3059\u3002",
    "Mahjong_StandardRuleContent5_3": "\u306A\u3089\u305A\u8005",
