    "Mahjong_StandardRuleTitle5_3": "3\u3002\u624B\u306B\u30C1\u30FC\u30C8\u304C\u306A\u3044\u5834\u5408\u3001\u305D\u308C\u306F\u786C\u3044\u3072\u3052\u3067\u3042\u308A\u3001\u30DE\u30EB\u30C1\u30D7\u30E9\u30A4\u30E4\u30FCx2\u3067\u3059\u3002 (\u30AA\u30D7\u30B7\u30E7\u30F3)",
    "Mahjong_StandardRuleTitle6": "\u30D5\u30ED\u30FC\u30C8\uFF08\u30AA\u30D7\u30B7\u30E7\u30F3\uFF09",
    "Mahjong_StandardRuleContent6_1": "\u30D5\u30ED\u30FC\u30C6\u30A3\u30F3\u30B0\u3059\u308B\u304B\u3069\u3046\u304B\u3092\u9078\u629E\u3067\u304D\u307E\u3059\u3002\u6D6E\u304B\u306A\u3051\u308C\u3070\u305D\u308C\u4EE5\u4E0A\u306E\u52DD\u3061\u8CA0\u3051\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u30D5\u30ED\u30FC\u30C6\u30A3\u30F3\u30B0\u306E\u5834\u5408\u3001\u8FFD\u52A0\u306E\u52DD\u6557\u306F\u6C7A\u6E08\u6642\u306B\u30D5\u30ED\u30FC\u30C8\u306E\u500D\u7387\u306B\u57FA\u3065\u3044\u3066\u8A08\u7B97\u3055\u308C\u307E\u3059\u3002",
    "Mahjong_StandardRuleContent6_2": "\u6700\u521D\u306B\u3001\u5404\u30D7\u30EC\u30A4\u30E4\u30FC\u306F\u30AB\u30FC\u30C9\u3092\u5F15\u304F\u524D\u306B\u30D5\u30ED\u30FC\u30C8\u306E\u500D\u6570 (1/2/3/5 \u56DE) \u3092\u9078\u629E\u3057\u307E\u3059\u3002\u6C7A\u6E08\u3059\u308B\u5834\u5408\u3001\u52DD\u3063\u305F\u30D7\u30EC\u30A4\u30E4\u30FC\u3068\u8CA0\u3051\u305F\u30D7\u30EC\u30A4\u30E4\u30FC\u306E\u52DD\u7387\u3092\u52A0\u7B97\u3057\u3066\u3001\u8FFD\u52A0\u306E\u52DD\u6557\u3092\u8A08\u7B97\u3057\u307E\u3059\u3002",
