    "UIAutoChangeTable3": "\u73FE\u5728\u306E\u30C6\u30FC\u30D6\u30EB\u306F\u3001{0} \u30CF\u30F3\u30C9\u306B\u53C2\u52A0\u3057\u305F\u5F8C\u306B\u518D\u30E9\u30F3\u30C0\u30E0\u306B\u5272\u308A\u5F53\u3066\u3089\u308C\u307E\u3059",
    "UIAutoChangeTable4": "\u81EA\u52D5\u30C6\u30FC\u30D6\u30EB\u5909\u66F4",
    "UIAutoChangeTable5": "\u624B\u304C\u7D42\u308F\u3063\u305F\u3089\u81EA\u52D5\u7684\u306B\u30C6\u30FC\u30D6\u30EB\u306B\u5207\u308A\u66FF\u308F\u308A\u307E\u3059",
    "UIEgg_TwoRate": "2 \u756A\u76EE\u306E\u65C5\u884C\u6599\u91D1",
    "UIEgg_AddRate": "\u30C0\u30D6\u30EB",
    "UIEgg_PressRate": "\u5E73\u5747\u6291\u5236",
    "UIEgg_HeadRate": "\u521D\u56DE\u8A2A\u554F\u7387\u3092\u53D6\u5F97\u3059\u308B",
    "UIEgg_TwoRateTips": "\u3059\u3079\u3066\u306E\u30CF\u30F3\u30C9\u306E\u3046\u3061\u3001\u5354\u529B\u3057\u3066 2 \u756A\u76EE\u306E\u30B2\u30FC\u30E0\u3092\u7372\u5F97\u3059\u308B\u5272\u5408",
