    "adaptation20002": "##\uACC4\uC18D \uD50C\uB808\uC774\uD558\uAC70\uB098",
    "adaptation20003": "\uB9F9\uC778\uC774 \uD50C\uB808\uC774\uD558\uB3C4\uB85D \uD558\uB294 \uD638\uC2A4\uD305 \uBAA8\uB4DC\uB97C \uC120\uD0DD\uD574\uC57C \uD569\uB2C8\uB2E4. \uAC8C\uC784\uC744 \uC885\uB8CC\uD558\uBA74 \uC774 \uD578\uB4DC\uAC00 \uB05D\uB098\uBA74 \uC790\uB3D9\uC73C\uB85C \uC77C\uC5B4\uB0A9\uB2C8\uB2E4",
    "adaptation20004": "\uCCAD\uC911\uC740 \uC74C\uC131\uC744 \uBCF4\uB0BC \uC218 \uC5C6\uB2E4",
    "adaptation20005": "Pot",
    "adaptation20006": "Blinds",
    "adaptation20007": "Ante",
    "adaptation20008": "\uC81C\uD55C \uC0AC\uD56D",
    "adaptation20009": "\uAD00\uB9AC\uC790 \uC124\uC815 \uD50C\uB808\uC774\uC5B4\uC758 \uCD5C\uC18C \uD50C\uB808\uC774 \uC2DC\uAC04\uC740 \uB2E4\uC74C\uACFC \uAC19\uC2B5\uB2C8\uB2E4.<color=#ff0000>##\uC2DC\uAC04</color>, \uD50C\uB808\uC774\uC5B4\uB294 \uC774 \uAE30\uAC04 \uB3D9\uC548 \uD14C\uC774\uBE14\uC744 \uB5A0\uB0A0 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uADF8\uB807\uC9C0 \uC54A\uC73C\uBA74 \uD638\uC2A4\uD305 \uBAA8\uB4DC\uAC00 \uAD6C\uD604\uB429\uB2C8\uB2E4.",
    "adaptation20010": "UC \uC794\uC561\uC774 \uBD80\uC871\uD569\uB2C8\uB2E4. \uCDA9\uC804\uD574\uC8FC\uC138\uC694",
    "adaptation20011": "\uAD00\uB9AC\uC790\uAC00 Muck\uC744 \uCF30\uC2B5\uB2C8\uB2E4",
    "adaptation20012": "\uAD00\uB9AC\uC790\uAC00 Muck\uC744 \uAED0\uC2B5\uB2C8\uB2E4",
    "adaptation20013": "\uAD00\uB9AC\uC790\uAC00 \uCF1C\uC84C\uC2B5\uB2C8\uB2E4.forced Straddle",
    "adaptation20014": "\uAD00\uB9AC\uC790\uAC00 Straddle\uC744 \uAC15\uC81C \uC885\uB8CC\uD588\uC2B5\uB2C8\uB2E4",
    "adaptation20015": "\uAD00\uB9AC\uC790\uAC00 \uC9C0\uC5F0##\uBD84",
    "adaptation20016": "\uB2F9\uC2E0\uC740##\uC5D0 \uC608\uC57D\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uAC8C\uC784\uC744 \uD588\uB294\uB370 \uC774 \uAC8C\uC784\uC5D0 \uCC38\uC5EC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "adaptation20017": "OUTS>16 \uB610\uB294 OUTS=0, \uC778\uC288\uC5B4\uB7F0\uC2A4\uB97C \uAD6C\uB9E4\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "adaptation20018": "\uC2DC\uC2A4\uD15C \uC790\uB3D9 \uCD94\uAC00 \uAE30\uB2A5 \uBCF4\uD5D8, \uAD6C\uB9E4## UC",
    "adaptation20019": "\uC774\uBC88\uC5D0 \uD22C\uC790\uD558\uB294 \uBCF4\uD5D8\uC758 \uCD5C\uB300 \uAE08\uC561\uC740 \uC790\uC2E0\uC758 \uD31F \uD3EC\uC778\uD2B8 0.45 \uC774\uBA70, \uCD5C\uB300 \uAE08\uC561\uC740 \uC790\uB3D9\uC73C\uB85C \uAD6C\uB9E4\uB418\uC5C8\uC2B5\uB2C8\uB2E4#",
    "adaptation20020": "2\uCC28 \uBCF4\uD5D8 \uCD5C\uB300 \uAE08\uC561\uC740 1/2Pot\uC774\uBA70, \uCD5C\uB300 \uAE08\uC561\uC740 \uC790\uB3D9\uC73C\uB85C \uAD6C\uB9E4\uB418\uC5C8\uC2B5\uB2C8\uB2E4.##",
    "adaptation20021": "\uD604\uC7AC \uAC8C\uC784\uC5D0\uC11C BB \uD3EC\uC9C0\uC158\uC774 \uC544\uB2CC \uACBD\uC6B0, BB\uC758 UC\uB7C9\uC744 \uCC28\uAC10\uD55C \uD6C4 \uAC8C\uC784\uC5D0 \uCC38\uAC00\uD558\uAC8C \uB429\uB2C8\uB2E4.",
