    "UINiuZai_Betting_area": "\uBCA0\uD305 \uAD6C\uC5ED",
    "UINiuZaiInsurance_titleOne": "\uBCA0\uD305 \uC601\uC5ED [\uD574\uB2F9 \uD655\uB960\uB85C \uBCF4\uC0C1 \uBC1B\uAE30]",
    "UINiuZaiXiaZhuQu_content01": "1. \uC2B9\uB9AC, \uD328\uBC30 \uBC0F \uB3D9\uC810 \uC9C0\uC5ED: \uCE74\uC6B0\uBCF4\uC774 \uC2B9\uB9AC, \uBB34\uC2B9\uBD80, \uBD88\uC2A4 \uC2B9\uB9AC;",
    "UINiuZaiXiaZhuQu_content02": "2. \uBAA8\uB4E0 \uD578\uB4DC \uCE74\uB4DC \uC601\uC5ED: \uD50C\uB7EC\uC2DC/\uC5F0\uACB0 \uCE74\uB4DC/\uC288\uD2B8 \uC5F0\uACB0 \uCE74\uB4DC, \uC5D0\uC774\uC2A4 \uC30D;",
    "UINiuZaiXiaZhuQu_content03": "3. \uC704\uB2DD \uCE74\uB4DC \uC720\uD615 \uC601\uC5ED: \uD558\uC774 \uCE74\uB4DC/\uC6D0 \uD398\uC5B4, \uD22C \uD398\uC5B4, \uC4F0\uB9AC \uCE74\uB4DC/\uC2A4\uD2B8\uB808\uC774\uD2B8 \uD50C\uB7EC\uC2DC, \uD480 \uD558\uC6B0\uC2A4, \uD0B9\uCF69/\uC2A4\uD2B8\uB808\uC774\uD2B8 \uD50C\uB7EC\uC2DC/\uB85C\uC5F4 \uD50C\uB7EC\uC2DC",
    "UINiuZai_high_one": "\uD558\uC774 \uCE74\uB4DC/\uD398\uC5B4",
    "UINiuZaiXiaZhuQu_content04": "\uD669\uD1B5",
    "UINiuZaiInsurance_titleTwo": "\uCE74\uB4DC \uC0AC\uC774\uC988 [\uC288\uD2B8 \uC0C1\uAD00\uC5C6\uC74C]",
    "UINiuZaiXiaZhuQu_content05": "1. \uCE74\uB4DC \uC720\uD615: \uB85C\uC584 \uD1B5>\uD3EC \uD50C\uB7EC\uC26C>\uD3EC \uC624\uBE0C \uC5B4 \uCE74\uC778\uB4DC>\uD480 \uD558\uC6B0\uC2A4>\uD50C\uB7EC\uC2DC>\uC2A4\uD2B8\uB808\uC774\uD2B8>\uC4F0\uB9AC \uC624\uBE0C \uC5B4 \uCE74\uC778\uB4DC>\uD22C \uD398\uC5B4>\uD398\uC5B4>",
    "UINiuZaiXiaZhuQu_content06": "\uD558\uC774\uCE74\uB4DC;",
    "UINiuZaiXiaZhuQu_content07": "2.\uB2E8\uC77C \uCE74\uB4DC:A>K>Q>J>10>9>8>7>6>5>4>3>2;",
    "UINiuZaiXiaZhuQu_content08": "3. \uB3D9\uC77C\uD55C \uCE74\uB4DC \uC720\uD615: \uAC00\uC7A5 \uD070 \uB2E8\uC77C \uCE74\uB4DC\uB97C \uBA3C\uC800 \uBE44\uAD50\uD558\uACE0 \uB3D9\uC77C\uD55C \uACBD\uC6B0 \uC544\uB798\uCABD\uC73C\uB85C \uACC4\uC18D \uBE44\uAD50\uD569\uB2C8\uB2E4. \uC608\uB97C \uB4E4\uC5B4, 5",
    "UINiuZaiXiaZhuQu_content09": "\uCE74\uB4DC\uAC00 \uB3D9\uC77C\uD558\uBA74 \uBB34\uC2B9\uBD80\uAC00 \uB429\uB2C8\uB2E4.",
    "UINiuZaiInsurance_titleThree": "\uD3ED\uBC1C\uC801\uC778 \uC740\uD589\uAC00 \uADDC\uCE59",
    "UINiuZaiXiaZhuQu_content011": "\uB51C\uB7EC\uC758 \uB0A8\uC740 \uCE69\uC774 \uBAA8\uB4E0 \uC2B9\uB9AC \uD50C\uB808\uC774\uC5B4\uC5D0\uAC8C \uBCF4\uC0C1\uD558\uAE30\uC5D0 \uCDA9\uBD84\uD558\uC9C0 \uC54A\uC740 \uACBD\uC6B0 \uB51C\uB7EC\uC758 \uB0A8\uC740 \uCE69\uC740",
    "UINiuZaiXiaZhuQu_content012": "\uB0A8\uC740 \uD3EC\uC778\uD2B8\uB294 \uC2B9\uB9AC\uD55C \uD50C\uB808\uC774\uC5B4\uC5D0\uAC8C \uBE44\uB840\uD558\uC5EC \uBC30\uBD84\uB418\uBA70, \uC815\uC0B0 \uD6C4 \uAC1D\uC2E4\uC5D0\uC11C \uC815\uC0B0\uB429\uB2C8\uB2E4.",
