    "UIGameNiuZai_XianHong": "\uBE68\uAC04\uC0C9 \uD55C\uACC4\uC5D0 \uB3C4\uB2EC\uD588\uC2B5\uB2C8\uB2E4",
    "UIMatch_RoomItemMark": "\uCC38\uC5EC \uC911",
    "UIMTT_Howtoplay_rules": "\uACBD\uC7C1 \uADDC\uC815",
    "UIMTT_Howtoplay_rulesc": "MTT [Multi Table Tournament]\uB294 \uC5EC\uB7EC \uD14C\uC774\uBE14\uC5D0\uC11C \uB3D9\uC2DC\uC5D0 \uC9C4\uD589\uB418\uB294 MTT\uB97C \uB9D0\uD569\uB2C8\uB2E4. \uC120\uC218\uB4E4\uC774 \uD0C8\uB77D\uD568\uC5D0 \uB530\uB77C \uD14C\uC774\uBE14\uC740 \uD1B5\uD569\uB418\uBA70, \uACB0\uC2B9\uC804\uC5D0 \uC9C4\uCD9C\uD558\uAE30 \uC704\uD574\uC11C\uB294 \uD558\uB098\uC758 \uD14C\uC774\uBE14\uB85C \uCD95\uC18C\uB429\uB2C8\uB2E4. \uD55C \uC0AC\uB78C\uC774 \uAC8C\uC784\uC5D0 \uB0A8\uC544 \uCE69\uC744 \uAC00\uC9C0\uACE0 \uC788\uC744 \uB54C. \uCC54\uD53C\uC5B8\uC774 \uC0DD\uC131\uB418\uACE0 \uAC8C\uC784\uC774 \uC885\uB8CC\uB429\uB2C8\uB2E4",
    "UIMTT_Howtoplay_scoreboard": "\uCE69 \uBC14\uC774\uC778",
    "UIMTT_Howtoplay_scoreboardc": "\uAC8C\uC784 \uC911\uC5D0 \uBAA8\uB4E0 \uD50C\uB808\uC774\uC5B4\uB294 \uC790\uB3D9\uC73C\uB85C \uB3D9\uC77C\uD55C \uACE0\uC815 \uC218\uC758 \uCE69\uC744 \uBC14\uC774\uC778\uD569\uB2C8\uB2E4. \uD50C\uB808\uC774\uC5B4\uB294 \uAC00\uC785\uB9CC \uD558\uBA74 \uCC38\uAC00\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAC8C\uC784 \uC911\uC5D0\uB294 \uCE69\uC744 \uB9C8\uC74C\uB300\uB85C \uCD94\uAC00\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "UIMTT_Howtoplay_blind": "Blinds",
    "UIMTT_Howtoplay_blindc": "\uAC8C\uC784 \uB0B4 \uBE14\uB77C\uC778\uB4DC\uC758 \uAD6C\uC870\uB294 \uD45C\uC900 \uB77C\uC6B4\uB4DC\uC758 \uACE0\uC815 \uBE14\uB77C\uC778\uB4DC\uC640 \uB2E4\uB985\uB2C8\uB2E4. \uC2DC\uC791 \uBE14\uB77C\uC778\uB4DC\uAC00 \uC788\uC73C\uBA70 \uAC8C\uC784\uC774 \uC9C4\uD589\uB428\uC5D0 \uB530\uB77C \uBE14\uB77C\uC778\uB4DC \uB808\uBCA8\uC774 \uC815\uAE30\uC801\uC73C\uB85C \uACC4\uC18D \uC99D\uAC00\uD558\uACE0 \uAC8C\uC784 \uC18D\uB3C4\uAC00 \uC810\uC810 \uB354 \uBE68\uB77C\uC9D1\uB2C8\uB2E4.",
    "UIMTT_Howtoplay_Zmtime": "\uBE14\uB77C\uC778\uB4DC \uC2DC\uAC04 \uC99D\uAC00",
    "UIMTT_Howtoplay_Zmtimec": "\uBE14\uB77C\uC778\uB4DC \uC99D\uAC00 \uC2DC\uAC04\uC740 \uB300\uD68C \uC8FC\uCD5C\uC790\uAC00 \uC124\uC815\uD569\uB2C8\uB2E4. \uBE14\uB77C\uC778\uB4DC \uC99D\uAC00 \uC2DC\uAC04\uB9C8\uB2E4 \uBE14\uB77C\uC778\uB4DC\uAC00 \uD55C \uB2E8\uACC4\uC529 \uC99D\uAC00\uD569\uB2C8\uB2E4. \uBE14\uB77C\uC778\uB4DC \uD0C0\uC784\uC740 \uAC8C\uC784\uC758 \uC18D\uB3C4\uB97C \uC81C\uC5B4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAC8C\uC784\uC774 \uC2DC\uC791\uB41C \uD6C4\uC5D0\uB294 \uBE14\uB77C\uC778\uB4DC \uD0C0\uC784\uC744 \uBCC0\uACBD\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "UIMTT_Howtoplay_refactor": "\uC7AC\uAD6C\uB9E4",
    "UIMTT_Howtoplay_refactorc": "\uD50C\uB808\uC774\uC5B4\uAC00 \uAC8C\uC784\uC5D0\uC11C \uC81C\uAC70\uB418\uBA74 \uB2E4\uC2DC \uAD6C\uB9E4\uD558\uC5EC \uBD80\uD65C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD658\uB9E4 \uAC00\uB2A5 \uD69F\uC218\uC5D0\uB294 \uB300\uD68C \uC8FC\uCD5C\uC790\uAC00 \uC815\uD55C \uC81C\uD55C\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uB4F1\uB85D \uB2E8\uACC4\uC5D0\uC11C\uB9CC \uC7AC\uAD6C\uB9E4\uAC00 \uAC00\uB2A5\uD569\uB2C8\uB2E4. \uB4F1\uB85D\uAE08\uC9C0 \uB2E8\uACC4 \uBC0F \uBCF8\uC120 \uB2E8\uACC4\uC5D0\uC11C\uB294 \uC7AC\uAD6C\uB9E4\uAC00 \uBD88\uAC00\uB2A5\uD569\uB2C8\uB2E4.",
    "UIMTT_Howtoplay_Intermission": "\uC911\uC9C0",
    "UIMTT_Howtoplay_Intermissionc": "\uCF1C\uAE30\uD558\uD504\uD0C0\uC784 \uD734\uC2DD \uD6C4, \uACBD\uAE30\uB294 55\uBD84\uB9C8\uB2E4 \uC790\uB3D9\uC73C\uB85C \uC77C\uC2DC\uC815\uC9C0\uB418\uBA70, 3\uBD84 \uD734\uC2DD\uC2DC\uAC04\uC774 \uC2DC\uC791\uB429\uB2C8\uB2E4.",
    "UIMTT_Howtoplay_czhz": "\uD14C\uC774\uBE14 \uC7AC\uBC30\uC815",
    "UIMTT_Howtoplay_czhzc": "MTT \uB300\uD68C\uC5D0\uC11C\uB294 \uD50C\uB808\uC774\uC5B4\uAC00 \uD0C8\uB77D\uD558\uACE0 \uC0C8\uB85C\uC6B4 \uD50C\uB808\uC774\uC5B4\uAC00 \uCC38\uAC00\uD558\uAE30 \uC704\uD574 \uB4F1\uB85D\uD569\uB2C8\uB2E4. \uC778\uC6D0 \uC218\uC758 \uADE0\uD615\uC744 \uB9DE\uCD94\uAE30 \uC704\uD574 \uD14C\uC774\uBE14\uC744 \uB098\uB204\uB294 \uC77C\uC774 \uBC1C\uC0DD\uD569\uB2C8\uB2E4. \uD14C\uC774\uBE14 \uBD84\uD560\uC740 \uAD6D\uC81C\uB300\uD68C \uADDC\uC815\uC744 \uC5C4\uACA9\uD558\uAC8C \uB530\uB985\uB2C8\uB2E4.",
    "UIMTT_Howtoplay_mc": "\uC21C\uC704",
    "UIMTT_Howtoplay_mcc": "\uBA85\uC0AC\uB294 \uD50C\uB808\uC774\uC5B4\uAC00 \uAC8C\uC784\uC5D0\uC11C \uC81C\uAC70\uB41C \uC21C\uC11C\uB300\uB85C \uACC4\uC0B0\uB429\uB2C8\uB2E4. \uB450 \uBA85\uC758 \uD50C\uB808\uC774\uC5B4\uAC00 \uD0C8\uB77D\uD560 \uACBD\uC6B0, \uC120\uBC1C \uCE69\uC744 \uAE30\uC900\uC73C\uB85C \uC21C\uC704\uAC00 \uACB0\uC815\uB418\uBA70, \uC120\uBC1C \uCE69\uC774 \uB354 \uB9CE\uC740 \uD50C\uB808\uC774\uC5B4\uAC00 1\uC704\uAC00 \uB429\uB2C8\uB2E4.",
    "UIMTT_Howtoplay_jl": "\uC0C1",
    "UIMTT_Howtoplay_jlc": "\uCD5C\uC885 \uAC8C\uC784\uC758 \uCD1D \uBC14\uC774\uC778 \uC218\uC5D0 \uB530\uB77C \uAC8C\uC784\uC5D0 \uCC38\uC5EC\uD55C \uCD5C\uC885 \uC778\uC6D0\uC774 \uD655\uC778 \uBCF4\uC0C1 \uC11C\uD074\uC5D0 \uB4E4\uC5B4\uC624\uAC8C \uB429\uB2C8\uB2E4. \uBCF4\uC0C1 \uC11C\uD074\uC5D0 \uB4E4\uC5B4\uAC04 \uD50C\uB808\uC774\uC5B4\uB294 \uCD5C\uC885 \uBE44\uC728",
