    "UiVoiceprint_10031": "\uC6A9\uC758\uC790<color=#DDBA82>{0}</color>\uB85C\uBD07\uC774 \uAC8C\uC784\uC758 \uC21C\uC11C\uB97C \uBC29\uD574\uD558\uACE0 \uC788\uB098\uC694? \uC2E4\uC81C \uC0AC\uB78C\uC758 \uC131\uBB38 \uAC80\uC99D \uC5EC\uBD80 \uC2DC\uC791",
    "UiVoiceprint_10032": "\uD655\uC778\uC744 \uC2DC\uC791\uD558\uC138\uC694",
    "UiVoiceprint_10033": "\uC2E4\uC81C \uC0AC\uB78C\uC758 \uC131\uBB38\uC744 \uD655\uC778\uD560\uC9C0 \uC5EC\uBD80\uB97C<color=#DDBA82>{0}</color>\uC18C\uBAA8\uD560 \uAC83\uC774\uB2E4<color=#DDBA82>{1}</color>\uD655\uC778 \uC2DC\uAC04.",
    "UiVoiceprint_10034": "\uC774 \uBC29\uC5D0\uC11C \uC2E4\uC81C \uC131\uBB38 \uD655\uC778\uC744 \uC2DC\uC791\uD560 \uC218 \uC788\uB294 \uD69F\uC218\uB294<color=#DDBA82>0</color>\uADF8\uB9AC\uACE0 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "UiVoiceprint_10035": "{0} \uC774\uD6C4\uC5D0 \uD655\uC778 \uAC00\uB2A5",
    "UiVoiceprint_10036": "<color=#DDBA82>{0}</color>\uC774 \uBC29\uC740 \uB85C\uBD07\uC774 \uC544\uB2CC \uAC83\uC73C\uB85C \uD655\uC778\uB418\uC5C8\uC2B5\uB2C8\uB2E4.<color=#DDBA82>{1}\uC744(\uB97C) \uB2E4\uC2DC \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4</color>\u3002",
    "UiVoiceprint_10037": "\uD50C\uB808\uC774\uC5B4\uB294 \uC77C\uC5B4\uC11C\uAE30 \uC704\uD574 \uC791\uB3D9\uD558\uACE0 \uC190\uC774 \uB05D\uB098\uBA74 \uD50C\uB808\uC774\uC5B4\uAC00 \uC77C\uC5B4\uC11C\uBBC0\uB85C \uB85C\uBD07 \uC131\uBB38 \uD655\uC778\uC744 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "UiVoiceprint_10038": "\uD50C\uB808\uC774\uC5B4\uAC00 \uBC29\uC744 \uB098\uAC00\uAE30 \uC704\uD574 \uC791\uB3D9\uD558\uACE0 \uC190\uC774 \uBC29\uC744 \uB098\uAC00\uBBC0\uB85C \uB85C\uBD07 \uC131\uBB38 \uD655\uC778\uC744 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "UiVoiceprint_10039": "\uD50C\uB808\uC774\uC5B4\uB294 \uC790\uB3D9\uC73C\uB85C \uC5EC\uB7EC \uBC88 \uD655\uC778\uD558\uBA70 \uC2DC\uC2A4\uD15C\uC5D0 \uC758\uD574 \uD50C\uB808\uC774\uC5B4\uAC00 \uBC29\uC5D0\uC11C \uCAD3\uACA8\uB098\uBBC0\uB85C \uB85C\uBD07 \uC131\uBB38 \uD655\uC778\uC744 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "UiVoiceprint_10040": "\uD50C\uB808\uC774\uC5B4\uB294 \uC790\uB3D9\uC73C\uB85C \uC5EC\uB7EC \uBC88 \uC811\uACE0, \uD578\uB4DC\uAC00 \uB05D\uB09C \uD6C4 \uD50C\uB808\uC774\uC5B4\uB294 \uBC29\uC5D0\uC11C \uCAD3\uACA8\uB098\uBBC0\uB85C \uB85C\uBD07 \uC131\uBB38 \uD655\uC778\uC744 \uC2DC\uC791\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "UiVoiceprint_10041": "\uC2E4\uC81C \uC778\uBB3C \uD655\uC778 \uAE30\uB85D",
    "UiVoiceprint_10042": "<color=#DDBA82>{0}</color>(ID:<color=#DDBA82>{1}</color>)\uAC00 \uC2E4\uC81C \uC131\uBB38 \uD655\uC778\uC744 \uC2DC\uC791\uD569\uB2C8\uB2E4. \uC81C\uD55C \uC2DC\uAC04 \uB0B4\uC5D0 \uC2DC\uD5D8\uC5D0 \uC751\uC2DC\uD558\uC9C0 \uC54A\uAC70\uB098 \uD1F4\uC2E4\uD558\uB294 \uACBD\uC6B0, \uADC0\uD558\uC758 \uACC4\uC815\uC740 \uC989\uC2DC \uC790\uB3D9\uC73C\uB85C \uB3D9\uACB0\uB429\uB2C8\uB2E4.",
    "UiVoiceprint_10043": "\uAC80\uC99D\uB41C \uC131\uBB38\uC774 \uC81C\uCD9C\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC2DC\uC2A4\uD15C\uC758 \uACB0\uC815\uC744 \uAE30\uB2E4\uB824\uC8FC\uC138\uC694.",
    "UiVoiceprint_10044": "\uC2E4\uBA85\uC778\uC99D \uCC38\uC5EC\uB97C \uAC70\uBD80\uD558\uC2DC\uBA74 \uACC4\uC815\uC774 \uB3D9\uACB0\uB429\uB2C8\uB2E4. \uC9C8\uBB38\uC774 \uC788\uC73C\uC2DC\uBA74 \uACE0\uAC1D \uC11C\uBE44\uC2A4\uC5D0 \uBB38\uC758\uD558\uC2ED\uC2DC\uC624.",
    "UiVoiceprint_10045": "<color=#DDBA82>{0}</color>(ID:<color=#DDBA82>{1}</color>)\uAC00 \uC2E4\uC81C \uC131\uBB38 \uD655\uC778\uC744 \uC2DC\uC791\uD569\uB2C8\uB2E4. \uC81C\uD55C \uC2DC\uAC04 \uB0B4\uC5D0 \uC2DC\uD5D8\uC744 \uCE58\uB974\uC9C0 \uC54A\uAC70\uB098 \uAC15\uC81C \uD1F4\uC2E4 \uC870\uCE58\uB97C \uB2F9\uD560 \uACBD\uC6B0, \uADC0\uD558\uC758 \uACC4\uC815\uC740 \uC989\uC2DC \uC790\uB3D9\uC73C\uB85C \uB3D9\uACB0\uB429\uB2C8\uB2E4.",
    "UiVoiceprint_10046": "<color=#DDBA82>{0}</color>\uAC8C\uC784\uC9C8\uC11C\uB97C \uBC29\uD574\uD558\uB294 \uB85C\uBD07\uC73C\uB85C \uC758\uC2EC\uB418\uC5B4 \uC131\uBB38\uAC80\uC99D\uC744 \uC9C4\uD589\uC911\uC785\uB2C8\uB2E4.",
    "UiVoiceprint_10047": "\uD22C\uD45C",
    "UiVoiceprint_10048": "\uB2E4\uC74C\uC5D0\uB294 \uB2E4\uC2DC \uB098\uD0C0\uB098\uC9C0 \uB9C8\uC138\uC694",
    "UiVoiceprint_10049": "1, \uB204\uAC00 \uD22C\uD45C\uC5D0 \uCC38\uC5EC\uD560 \uC218 \uC788\uB098\uC694?\\n\uD604\uC7AC \uAC8C\uC784\uC5D0 \uCC38\uC5EC\uD558\uAE30 \uC704\uD574 \uBC14\uC774\uC778 \uC911\uC778 \uD50C\uB808\uC774\uC5B4\uC785\uB2C8\uB2E4.\\n\\n2, \uD22C\uD45C\uD558\uB294 \uBC29\uBC95\uC740 \uBB34\uC5C7\uC785\uB2C8\uAE4C?\\n\uC778\uC99D\uB41C \uD50C\uB808\uC774\uC5B4\uC758 \uC6D0\uBCF8 \uC131\uBB38\uACFC \uBC29\uAE08 \uC81C\uCD9C\uD55C \uC778\uC99D \uC131\uBB38\uC744 \uBE44\uAD50\uD558\uC5EC \uB3D9\uC77C \uC778\uBB3C\uC778\uC9C0 \uD22C\uD45C \uC804 \uD655\uC778\uD574\uC8FC\uC138\uC694.\\n\\n3, \uD22C\uD45C \uACB0\uACFC \uBC1C\uD45C\\n\uD22C\uD45C \uACB0\uACFC\uB294 \uC2DC\uC2A4\uD15C \uC2EC\uC0AC \uD6C4 \uBC29\uC1A1 \uD615\uC2DD\uC73C\uB85C \uBC1C\uD45C\uB429\uB2C8\uB2E4. \uADDC\uCE59\uC744 \uC704\uBC18\uD55C \uD50C\uB808\uC774\uC5B4\uC758 \uACC4\uC815\uC740 \uC9C1\uC811 \uB3D9\uACB0\uB429\uB2C8\uB2E4",
    "UiVoiceprint_10050": "\uD22C\uD45C\uD558\uAE30 \uC804\uC5D0 \uBE44\uAD50\uD574 \uBCF4\uC138\uC694",
