    "Mahjong_LowScore": "\uCD5C\uC800 \uC810\uC218",
    "UIDialogRecentAwardRecord_MonthData": "\uC9C0\uB09C 1\uAC1C\uC6D4 \uB3D9\uC548\uC758 \uB370\uC774\uD130",
