    "UICreateTable_PrivateGame_Tips": "\uBE44\uBC00\uBC88\uD638 \uC124\uC815\uC744 \uD1B5\uD574 \uD50C\uB808\uC774\uC5B4\uB294 \uBC29\uC5D0 \uC785\uC7A5\uD558\uAE30 \uC704\uD574 \uBE44\uBC00\uBC88\uD638\uB97C \uC785\uB825\uD574\uC57C \uD569\uB2C8\uB2E4",
    "UICreateTable_Deposit_Tips": "\uC564\uD2F0 \uBCA0\uD305\uC5D0 \uB530\uB77C \uCCAD\uAD6C * \uD578\uB4DC \uB2F9 \uBC1C\uC0DD\uD560 \uC218 \uC788\uB294 170\uC758 \uCD5C\uB300 \uBC30\uC218",
    "UICreateTable_Anju_Tips": "\uD14C\uC774\uBE14 \uC885\uB8CC \uD6C4 \uBAA8\uB4E0 \uC2B9\uB9AC \uD50C\uB808\uC774\uC5B4\uB294 \uC124\uC815 \uAE08\uC561\uC5D0 \uBE44\uB840\uD558\uC5EC \uB808\uC774\uD06C\uB97C \uCCAD\uAD6C\uBC1B\uAC8C \uB429\uB2C8\uB2E4.",
    "UICreateTable_Anba_Tips": "\uAC01 \uD578\uB4DC \uD6C4\uC5D0 \uBAA8\uB4E0 \uC2B9\uB9AC \uD50C\uB808\uC774\uC5B4\uB294 \uC124\uC815 \uBE44\uB840 \uAC12\uC758 \uB808\uC774\uD06C\uB97C \uCCAD\uAD6C\uBC1B\uAC8C \uB429\uB2C8\uB2E4. \uC608\uB97C \uB4E4\uC5B4, \uCD5C\uB300 \uC124\uC815 \uD55C\uB3C4\uB294 \uD55C\uB3C4 \uAC12\uC744 \uCD08\uACFC\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    "UICreateTable_GPS_Tips": "\uAC19\uC740 \uD14C\uC774\uBE14\uC5D0\uC11C GPS \uC704\uCE58\uAC00 \uC124\uC815\uAC12 \uBC94\uC704 \uB0B4\uC5D0 \uC788\uB294 \uD50C\uB808\uC774\uC5B4\uB294 \uAC8C\uC784 \uCC38\uC5EC\uAC00 \uC81C\uD55C\uB429\uB2C8\uB2E4",
    "UICreateTable_IP_Tips": "\uAC19\uC740 \uD14C\uC774\uBE14\uC5D0 \uAC19\uC740 IP \uC8FC\uC18C\uB97C \uAC00\uC9C4 \uD50C\uB808\uC774\uC5B4\uB294 \uAC8C\uC784 \uCC38\uC5EC\uAC00 \uC81C\uD55C\uB429\uB2C8\uB2E4",
    "UICreateTable_BringIn_Tips": "\uD50C\uB808\uC774\uC5B4\uB294 \uAD6C\uB9E4\uD560 \uB54C\uB9C8\uB2E4 \uAC80\uD1A0\uB97C \uBC1B\uC544\uC57C \uD569\uB2C8\uB2E4",
    "UICreateTable_Cheat_Tips": "\uD50C\uB808\uC774\uC5B4\uB294 \uC124\uC815\uB41C \uC635\uC158\uC5D0 \uB530\uB77C \uD14C\uC774\uBE14\uC5D0\uC11C \uC601\uC0C1, \uC74C\uC131, \uC5BC\uAD74 \uC778\uC99D \uAE30\uB2A5\uC744 \uACBD\uD5D8\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4",
    "UICreateTable_AutoRecharge_Tips": "\uD50C\uB808\uC774\uAE30 \uD6C4, \uAC8C\uC784\uC5D0\uC11C \uC124\uC815\uC774 \uC124\uC815 \uAC12\uBCF4\uB2E4 \uB0AE\uC744 \uB54C \uD50C\uB808\uC774\uC5B4\uB294 \uC124\uC815 \uACE0\uC815 \uCE69\uC744 \uC790\uB3D9\uC73C\uB85C \uBCF4\uCDA9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4",
