    "UICreateTableGuildIDTip": "\uAC19\uC740 \uC720\uB2C8\uC628 \uC758 \uB2E4\uB978 \uBB38\uC5B4\uB4E4\uACFC \uAC8C\uC784\uC744 \uACF5\uC720\uD558\uBA74, \uADF8 \uBB38\uC5B4\uC758 \uBAA8\uB4E0 \uBB38\uD56D\uC774 \uC774 \uAC8C\uC784\uC5D0 \uC785\uC7A5\uD558\uC5EC \uAC8C\uC784\uC5D0 \uCC38\uC5EC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4",
    "UICreateTablePriveteGameTip": "\uBE44\uACF5\uAC1C \uAC8C\uC784: \uD50C\uB808\uC774\uC5B4\uB294 \uC124\uC815 \uBE44\uBC00\uBC88\uD638",
    "UICreateTableAOFTip": "\uB97C \uD1B5\uD574 \uBC29\uC5D0 \uC785\uC7A5\uD558\uB824\uBA74 \uBE44\uBC00\uBC88\uD638\uB97C \uC785\uB825\uD574\uC57C \uD569\uB2C8\uB2E4. \uD50C\uB808\uC774\uC5B4\uC758 \uCC28\uB840\uAC00 \uB418\uBA74 \uC62C\uC778 \uB610\uB294 \uD3F4\uB4DC\uC758 \uB450 \uAC00\uC9C0 \uC635\uC158\uB9CC \uC788\uC2B5\uB2C8\uB2E4",
    "UICreateTableAutopeoplenumTip": "\uC77C\uC815 \uC778\uC6D0\uC774 \uCC29\uC11D\uD558\uBA74 \uC790\uB3D9\uC73C\uB85C \uAC8C\uC784\uC774 \uC2DC\uC791\uB429\uB2C8\uB2E4.",
    "UICreateTableTotalHandsTip": "\uCD1D \uD578\uB4DC \uC81C\uD55C: \uD50C\uB808\uC774\uC5B4\uC758 \uCD1D \uD578\uB4DC \uC218\uAC00 \uC774 \uAC12\uBCF4\uB2E4 \uC791\uC544\uC11C \uC549\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "UICreateTableDoubleCardTip": "\uB450 \uC138\uD2B8\uC758 \uCE74\uB4DC: \uCF1C\uAE30 \uB450 \uC138\uD2B8\uC758 \uCE74\uB4DC, Allin\uC774 \uD50C\uB86D \uB610\uB294 \uD134\uC5D0\uC11C \uD50C\uB808\uC774\uB41C \uD6C4, \uB0A8\uC740 \uBAA8\uB4E0 \uD50C\uB808\uC774\uC5B4\uB294 \uB098\uBA38\uC9C0 \uACF5\uAC1C \uCE74\uB4DC\uB97C \uB450 \uBC88 \uCC98\uB9AC\uD558\uC5EC \uACB0\uACFC\uB97C \uACB0\uC815\uD558\uACE0 \uAC01 \uB77C\uC6B4\uB4DC\uC758 \uC2B9\uC790\uAC00 1/2\uAC1C\uC758 \uD31F\uC744 \uAC00\uC838\uAC08 \uC218 \uC788\uB2E4\uB294 \uB370 \uB3D9\uC758\uD569\uB2C8\uB2E4",
    "UICreateTableInsuranceTip": "\uAC8C\uC784 \uB0B4 \uBAA8\uB4E0 \uD50C\uB808\uC774\uC5B4\uAC00 \uC62C\uC778\uB41C \uD6C4, \uD604\uC7AC \uC120\uB450 \uD50C\uB808\uC774\uC5B4\uC5D0\uAC8C \uC778\uC288\uC5B4\uB7F0\uC2A4",
    "UICreateTableDelayReadTip": "\uCE74\uB4DC\uAC00 \uCC98\uB9AC\uB418\uACE0 \uD50C\uB808\uC774\uC5B4\uAC00 \uC791\uB3D9\uD560 \uCC28\uB840\uAC00 \uC544\uB2CC \uACBD\uC6B0 \uD50C\uB808\uC774\uC5B4\uC758 \uC190\uC5D0 \uC788\uB294 \uCE74\uB4DC\uB294 \uBCF4\uC774\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uD50C\uB808\uC774\uC5B4\uAC00 \uC870\uC791\uD560 \uCC28\uB840\uAC00 \uB41C \uD6C4\uC5D0\uC57C \uD578\uB4DC \uCE74\uB4DC\uAC00 \uD45C\uC2DC\uB429\uB2C8\uB2E4",
    "UICreateTableForTheBlindTip": "\uD50C\uB808\uC774\uC5B4\uAC00 \uC549\uC558\uC744 \uB54C BB \uC704\uCE58\uC5D0 \uC788\uC9C0 \uC54A\uC740 \uACBD\uC6B0 \uBE14\uB77C\uC778\uB4DC \uCC44\uC6B0\uAE30\uB77C\uACE0 \uD558\uB294 \uCD94\uAC00 \uD544\uC218 \uBCA0\uD305\uC744 \uC9C0\uBD88\uD574\uC57C \uD558\uBA70 \uC774\uB294 \uC77C\uBC18\uC801\uC73C\uB85C BB \uBCA0\uD305\uC785\uB2C8\uB2E4.",
    "UICreateTableStraddleTip": "1\uC744 \uC120\uD0DD\uD558\uBA74 1\uAC1C\uC758 \uAC15\uC81C \uCEA1\uCC98\uAC00 \uBC1C\uC0DD\uD569\uB2C8\uB2E4.\\n2\uC744 \uC120\uD0DD\uD558\uBA74 1\uAC1C\uC758 \uAC15\uC81C \uCEA1\uCC98\uC640 1\uAC1C\uC758 \uC218\uB3D9 \uCEA1\uCC98\uAC00 \uBC1C\uC0DD\uD569\uB2C8\uB2E4.\\n3\uC744 \uC120\uD0DD\uD558\uBA74 1\uAC1C\uC758 \uAC15\uC81C \uCEA1\uCC98\uC640 2\uAC1C\uC758 \uC218\uB3D9 \uCEA1\uCC98\uAC00 \uBC1C\uC0DD\uD569\uB2C8\uB2E4.\\n\uB4F1\uB4F1",
    "UICreateCowboyBankerTip": "\uBC45\uCEE4 \uBC14\uC774\uC778(Banker Buy-in), \uB8F8 \uC624\uD508 \uC2DC \uBC45\uCEE4 \uBC14\uC774\uC778 \uAE08\uC561, \uBC45\uCEE4\uB85C \uC0AC\uC6A9\uB418\uB294 \uAE08\uC561",
    "UICreateCowboyLimitRedTip": "\uBCF4\uB108\uC2A4 \uD55C\uB3C4, \uCD5C\uB300 \uBCA0\uD305 \uBC94\uC704 \uC81C\uD55C",
    "UICreateTableLowScoreTip": "\uD558\uB2E8 \uD3EC\uC778\uD2B8, \uAE30\uBCF8 \uBC88\uD638",
    "UICreateRoomSubOptionMahjongThreeTip": "\uC138 \uC7A5\uC758 \uCE74\uB4DC\uB97C \uBCC0\uACBD\uD558\uACE0, \uAC01 \uD50C\uB808\uC774\uC5B4\uB294 \uB3D9\uC77C\uD55C \uBAA8\uC591\uC758 \uCE74\uB4DC 3\uC7A5\uC744 \uC120\uD0DD\uD558\uACE0 \uBB34\uC791\uC704\uB85C \uB2E4\uB978 1\uBA85\uC758 \uD50C\uB808\uC774\uC5B4\uC640 \uAD50\uD658\uD569\uB2C8\uB2E4",
    "UICreateTableMaxWinRateTip": "Hu \uCE74\uB4DC\uC758 \uCD5C\uB300 \uD55C\uB3C4, \uCD5C\uB300 \uC2B9\uC218",
    "Mahjong_Raise": "\uB5A0 \uC788\uB294",
    "Mahjong_RaiseTips": "\uCC98\uC74C\uC5D0 \uAC01 \uD50C\uB808\uC774\uC5B4\uB294 \uCE74\uB4DC\uB97C \uBCF4\uAE30 \uC804\uC5D0 \uBD80\uB3D9\uC758 \uBC30\uC218\uB97C \uC120\uD0DD\uD569\uB2C8\uB2E4. \uC815\uC0B0 \uC2DC \uD328\uC790\uC758 \uB4DC\uB9AC\uD504\uD2B8 \uD3EC\uC778\uD2B8 + \uD328\uC790\uC758 \uB4DC\uB9AC\uD504\uD2B8 \uD3EC\uC778\uD2B8",
    "Mahjong_KnockdownMode": "\uBAA8\uB4DC",
    "Mahjong_KnockdownModeTips": "\uBAA8\uB4DC\uB294 \uC120\uD0DD \uC0AC\uD56D\uC785\uB2C8\uB2E4. \uBAA8\uB450 \uC120\uD0DD\uD558\uAC70\uB098 \uC120\uD0DD\uD558\uC9C0 \uC54A\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC120\uD0DD \uC0AC\uD56D\uC740 \uC801\uC6A9\uB418\uC9C0\uB9CC \uC120\uD0DD \uC0AC\uD56D\uC740 \uC801\uC6A9\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.\\n\uB2E8\uC5B4 \uD0C0\uC77C\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uB2E8\uC5B4 \uD0C0\uC77C\uC744 \uC81C\uAC70\uD558\uACE0 108\uC7A5\uC758 \uCE74\uB4DC\uB97C \uB0A8\uACA8\uB461\uB2C8\uB2E4.\\n\uB2F9\uC2E0\uC740 \uCFF5\uD6C4\uB97C \uC7A1\uC744 \uC218 \uC788\uACE0, \uC120\uD0DD\uD558\uBA74 \uCFF5\uD6C4\uB97C \uC7A1\uC744 \uC218 \uC788\uACE0, \uC120\uD0DD\uD558\uC9C0 \uC54A\uC73C\uBA74 \uCFF5\uD6C4\uB97C \uC7A1\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
    "Mahjong_KnockdownModeNone": "\uC790\uD328 \uC5C6\uC74C",
    "Mahjong_KnockdownModeRobKong": "\uBC14\uBC14\uB9AC\uC548\uC744 \uC7A1\uC744 \uC218 \uC788\uB2E4",
    "Mahjong_KnockdownModeEat": "\uBA39\uC744 \uC218 \uC788\uB294 \uCE74\uB4DC",
    "Mahjong_Result": "\uD6C4\uC9C4\uD0C0\uC624 \uCE74\uB4DC",
    "Mahjong_ResultTips": "Hu \uCE74\uB4DC\uB97C \uC0AC\uC6A9\uD558\uB294 \uC138 \uAC00\uC9C0 \uBC29\uBC95 \uC911 \uD558\uB098\uB97C \uC120\uD0DD\uD558\uC138\uC694.",
    "Mahjong_ResultChicken": "\uB2ED\uB625\uC9D1\uC740 \uBABB \uBA39\uC5B4",
    "Mahjong_ResultEat": "\uBA39\uACE0 \uC2F6\uC740 \uAC83\uC740 \uBB34\uC5C7\uC774\uB4E0 \uBA39\uC5B4\uB77C",
    "Mahjong_ResultOnlySelfDraw": "\uB098 \uC790\uC2E0\uB9CC \uB9CC\uC9C8 \uC218 \uC788\uB2E4",
    "Mahjong_Contract": "\uACC4\uC57D",
    "Mahjong_ContractTips": "\uAC15\uD0C8\uD55C \uC0AC\uB78C\uC774 \uACC4\uC57D\uC744 \uD558\uACE0, \uAC15\uD0C8\uD55C \uC0AC\uB78C\uC744 \uCD94\uCCA8\uD558\uC5EC \uBC88\uD638\uD310\uC744 \uACC4\uC0B0\uD558\uACE0, \uAC15\uD0C8\uB2F9\uD55C \uC0AC\uB78C\uC774 \uACC4\uC57D\uC744 \uD558\uAC8C \uB429\uB2C8\uB2E4.\\n\uCF69\uC744 \uD074\uB9AD\uD558\uC5EC \uACC4\uC57D\uC744 \uC5F4\uACE0, a\uB294 b\uC5D0\uAC8C \uCF69\uC744 \uC8FC\uACE0, b\uC758 \uCF69 \uCE74\uB4DC\uB294 \uC790\uCCB4 \uCD94\uCCA8\uC73C\uB85C \uAC04\uC8FC\uB418\uBA70, a\uB294 \uBAA8\uB4E0 \uC190\uC2E4 \uD3EC\uC778\uD2B8\uB97C \uACC4\uC57D\uD569\uB2C8\uB2E4.\\n12\uC774 \uACC4\uC57D\uC744 \uCCB4\uACB0\uD558\uACE0, a\uAC00 b\uC5D0\uAC8C 4 \uBC94\uD504 \uB610\uB294 \uCF69\uC744 \uC81C\uACF5\uD558\uACE0, b\uAC00 \uC2B9\uB9AC\uD558\uACE0, a\uAC00 \uC190\uC2E4\uB41C \uD3EC\uC778\uD2B8\uB97C \uBAA8\uB450 \uACC4\uC57D\uD569\uB2C8\uB2E4.",
    "Mahjong_Contract12": "12\uCE35 \uACC4\uC57D \uC911",
    "Mahjong_ContractKong": "\uB808\uBC84\uB9AC\uC9C0\uB97C \uC0AC\uC6A9\uD558\uC5EC \uACC4\uC57D \uC2DC\uC791",
    "Mahjong_ContractRobKong": "\uACC4\uC57D\uC744 \uD65C\uC6A9\uD574",
    "Mahjong_Nojoker": "\uB77C\uC774\uC790",
    "Mahjong_NojokerTips": "라이코는 세 가지 모드 중 하나를 선택합니다.\\n빨간색 매체가 Laizi인 경우 단어 카드의 \"중간\"을 Laizi 카드로 선택합니다.\\nLaizi를 실패하고 각 라운드가 시작되기 전에 카드를 뒤집습니다. 이 카드의 포인트 + 1이 이번 라운드의 플롭 카드입니다. Flop이 5백만을 산출하면 60,000이 라이지가 됩니다.\\n그 중 'Rogue x2'가 체크된 옵션이다. 트릭을 칠 때 도적이 없으면 힘든 수염입니다. 승수는 x2",
    "Mahjong_NojokerRed": "\uB808\uB4DC \uB85C\uADF8",
