    "Mahjong_RuleContent6_5": '"\uCF5C \uC804\uC1A1"\uC740 \uD50C\uB808\uC774\uC5B4\uAC00 \uCF69 \uCE74\uB4DC\uC5D0\uC11C \uC2B9\uB9AC \uD3EC\uC778\uD2B8\uB97C \uCF69 \uCE74\uB4DC\uB97C \uAC00\uC9C4 \uD50C\uB808\uC774\uC5B4\uC5D0\uAC8C \uC804\uC1A1\uD574\uC57C \uD569\uB2C8\uB2E4.',
    "Mahjong_RuleContent7_2": '"\uC138\uAE08 \uD658\uAE09", \uC190\uC5D0 \uC788\uB294 \uCE74\uB4DC\uB97C \uBAA8\uB450 \uBF51\uC558\uC744 \uB54C \uCE74\uB4DC\uB97C \uB4E3\uC9C0 \uBABB\uD55C \uD50C\uB808\uC774\uC5B4\uB294 \uCF69 \uCE74\uB4DC \uC774\uB4DD\uC744 \uBAA8\uB450 \uBC18\uD658\uD569\uB2C8\uB2E4',
    "Mahjong_RuleTitle19": "\uBC14\uC774\uC778 \uADDC\uC815",
    "Mahjong_RuleContent19_1": '\uBC14\uC774\uC778\uC740 "\uCD5C\uD558\uC704 \uC810\uC218 * 24\uD68C"(\uCD5C\uC18C \uBC14\uC774\uC778 "\uCD5C\uD558\uC704 \uC810\uC218 * 25\uD68C"\uC640 \uB3D9\uC77C)\uB97C \uAE30\uC900\uC73C\uB85C \uD55C \uBC14\uC774\uC778\uBCF4\uB2E4 \uCEE4\uC57C \uD569\uB2C8\uB2E4. \uAC8C\uC784\uC758 \uCE69\uC774 "\uCD5C\uC800 \uC810\uC218 * 24 \uD68C" \uC774\uD558\uC778 \uACBD\uC6B0, \uC77C\uC5B4\uB098\uC11C \uACC4\uC18D\uD558\uB824\uBA74 \uCE69\uC744 \uCD94\uAC00\uD574\uC57C \uD569\uB2C8\uB2E4',
    "UIMatch_ServerHead": "\uACF5\uC2DD \uACE0\uAC1D \uC11C\uBE44\uC2A4",
    "UICreateTableSquidModeTip": "\uC5EC\uB7EC \uD50C\uB808\uC774\uC5B4\uAC00 \uC5EC\uB7EC \uAC1C\uC758 \uC624\uC9D5\uC5B4\uB97C \uC5BB\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD55C \uBA85\uC758 \uD50C\uB808\uC774\uC5B4\uB9CC \uC624\uC9D5\uC5B4\uB97C \uC5BB\uC9C0 \uBABB\uD558\uBA74 \uD604\uC7AC \uC624\uC9D5\uC5B4 \uB77C\uC6B4\uB4DC\uAC00 \uC885\uB8CC\uB429\uB2C8\uB2E4.",
    "UICreateTableSquidModeSingleToggle": "\uB2E8\uC77C \uC624\uC9D5\uC5B4",
    "UICreateTableSquidModeMoreToggle": "\uC624\uC9D5\uC5B4\uAC00 \uB4EC\uBFCD",
    "UIQuickCreateTable": "\uD55C \uBC88\uC758 \uD074\uB9AD\uC73C\uB85C \uD14C\uC774\uBE14 \uC5F4\uAE30",
    "ServerErrorCode_31050": "CallTime\uC744 \uB5A0\uB0A0 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
    "Mahjong_BloodRiverRuleContent3_1": '"\uD53C\uC758 \uAC15" \uD50C\uB808\uC774\uC5B4\uAC00 \uCE74\uB4DC\uB97C \uBF51\uC740 \uD6C4\uC5D0\uB3C4 \uAC8C\uC784\uC740 \uC885\uB8CC\uB418\uC9C0 \uC54A\uC73C\uBA70, \uACC4\uC18D\uD574\uC11C \uC790\uB3D9 \uCE74\uB4DC \uBF51\uAE30 \uC0C1\uD0DC\uAC00 \uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uCE74\uB4DC\uAC00 \uCE74\uB4DC \uADDC\uCE59\uACFC \uC77C\uCE58\uD558\uB294 \uD55C, \uD50C\uB808\uC774\uC5B4\uB294 \uCE74\uB4DC \uBCBD\uC774 \uC18C\uC9C4\uB420 \uB54C\uAE4C\uC9C0 \uACC4\uC18D\uD574\uC11C \uCE74\uB4DC\uB97C \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.',
    "Mahjong_BloodRiverRuleTitle222": "\uCE74\uB4DC \uC720\uD615 \uBC0F \uBC88\uD638:",
