    "UICreateTable_QuickChangeRoom": "\uBE60\uB978 \uD14C\uC774\uBE14 \uBCC0\uACBD",
    "UICreateTable_QuickChangeRoomTips": "\uBE60\uB978 \uD14C\uC774\uBE14 \uBCC0\uACBD\uC740 \uCE74\uB4DC \uD55C \uC7A5\uC744 \uB9C8\uCE5C \uD6C4 \uB3D9\uC77C\uD55C \uC218\uC900\uC758 \uBE60\uB978 \uD14C\uC774\uBE14 \uBCC0\uACBD \uAE30\uB2A5\uC744 \uC9C0\uC6D0\uD569\uB2C8\uB2E4",
    "UIMahjong_QuickChangeRoom": "\uD14C\uC774\uBE14 \uBCC0\uACBD \uC2DC\uC791",
    "UICreateTableSquidSingleTips": "\uD50C\uB808\uC774\uC5B4\uB294 \uC624\uC9D5\uC5B4\uB97C \uD55C \uB9C8\uB9AC\uB9CC \uC5BB\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774\uBC88 \uB77C\uC6B4\uB4DC\uC5D0\uC11C \uD55C \uBA85\uC758 \uD50C\uB808\uC774\uC5B4\uB9CC \uC624\uC9D5\uC5B4\uB97C \uC5BB\uC9C0 \uBABB\uD558\uBA74 \uC774\uBC88 \uB77C\uC6B4\uB4DC\uC5D0\uC11C \uC624\uC9D5\uC5B4 \uAC8C\uC784\uC774 \uC885\uB8CC\uB418\uACE0, \uC624\uC9D5\uC5B4 \uB9C8\uD06C\uB97C \uC5BB\uC9C0 \uBABB\uD55C \uD50C\uB808\uC774\uC5B4\uB294\\n\uC624\uC9D5\uC5B4 \uBCF4\uB108\uC2A4 = \uC624\uC9D5\uC5B4\uC758 \uC124\uC815\uAC12\\n\uBCF4\uC0C1 \uAE08\uC561 = \uC774\uBC88 \uB77C\uC6B4\uB4DC\uC758 \uC624\uC9D5\uC5B4 \uC218 * \uAC01 \uC624\uC9D5\uC5B4\uC758 \uAC00\uCE58",
    "UICreateTableSquidMubleTips": '\uD50C\uB808\uC774\uC5B4\uB294 \uC5EC\uB7EC \uAC1C\uC758 \uC624\uC9D5\uC5B4\uB97C \uC5BB\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774\uBC88 \uB77C\uC6B4\uB4DC\uC5D0\uC11C "\uC624\uC9D5\uC5B4\uAC00 \uC0C1\uD55C\uC120\uC5D0 \uB3C4\uB2EC"\uD558\uAC70\uB098 "\uC624\uC9D5\uC5B4\uB97C \uC5BB\uC9C0 \uBABB\uD55C \uD50C\uB808\uC774\uC5B4\uB294 \uB2E8 \uD55C \uBA85"\uC77C \uACBD\uC6B0, \uC774\uBC88 \uB77C\uC6B4\uB4DC\uC758 \uC624\uC9D5\uC5B4 \uAC8C\uC784\uC740 \uC885\uB8CC\uB418\uBA70, \uC624\uC9D5\uC5B4\uB97C \uC5BB\uC9C0 \uBABB\uD55C \uD50C\uB808\uC774\uC5B4\uB4E4\uC740 \uAC01\uAC01 \uBCF4\uC0C1\uC744 \uBC1B\uAC8C \uB429\uB2C8\uB2E4. \uD50C\uB808\uC774\uC5B4\uAC00 \uB354 \uB9CE\uC740 \uC624\uC9D5\uC5B4\uB97C \uC5BB\uC744\uC218\uB85D \uBCF4\uC0C1\uB3C4 \uCEE4\uC9D1\uB2C8\uB2E4.\\n\uC624\uC9D5\uC5B4 \uBCF4\uB108\uC2A4 = \uBCF4\uC720\uD55C \uC624\uC9D5\uC5B4 \uC218 * \uAC01 \uC624\uC9D5\uC5B4\uC758 \uAC00\uCE58 * \uD68D\uB4DD\uD558\uC9C0 \uBABB\uD55C \uC624\uC9D5\uC5B4 \uC218\\n1\uC778\uB2F9 \uBCF4\uC0C1\uAE08\uC561 = \uBCF8 \uAC8C\uC784\uC5D0\uC11C \uC0DD\uC0B0\uB41C \uC624\uC9D5\uC5B4 \uC218 * \uC624\uC9D5\uC5B4 1\uAC1C\uC758 \uAC00\uCE58',
    "UICreateTableSquidCoinTips": "\uC624\uC9D5\uC5B4 1\uAC1C\uB2F9 \uAE08\uC561",
    "UICreateTableSquidNumTips": "\uCD1D \uC624\uC9D5\uC5B4 \uC218. \uD50C\uB808\uC774\uC5B4\uB294 \uC2B9\uB9AC\uD560 \uB54C\uB9C8\uB2E4 \uC624\uC9D5\uC5B4 \uD55C \uB9C8\uB9AC\uB97C \uC5BB\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uCD1D \uC624\uC9D5\uC5B4 \uC218\uB294 \uC81C\uD55C\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC815\uC0B0\uC740 \uD6A1\uB839 \uD6C4 \uC815\uC0B0\uB429\uB2C8\uB2E4.",
    "UICreateTableSquidClassicTips": "\uD50C\uB808\uC774\uC5B4\uB294 1\uAC1C\uC758 \uC624\uC9D5\uC5B4\uB9CC \uC5BB\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774\uBC88 \uB77C\uC6B4\uB4DC\uC5D0\uC11C 1\uBA85\uC758 \uD50C\uB808\uC774\uC5B4\uB9CC \uC624\uC9D5\uC5B4\uB97C \uC5BB\uC9C0 \uBABB\uD558\uBA74 \uC774\uBC88 \uB77C\uC6B4\uB4DC\uC758 \uC624\uC9D5\uC5B4 \uAC8C\uC784\uC774 \uC885\uB8CC\uB429\uB2C8\uB2E4",
    "UICreateTableSquidBattleTips": "\uD50C\uB808\uC774\uC5B4\uB294 \uC2B9\uB9AC\uD560 \uB54C\uB9C8\uB2E4 \uC624\uC9D5\uC5B4 1\uAC1C\uB97C \uC5BB\uC744 \uC218 \uC788\uC73C\uBA70, \uCD1D \uC624\uC9D5\uC5B4 \uC218\uB294 \uC81C\uD55C\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uD50C\uB808\uC774\uC5B4\uB294",
