    "UICreateMahjongMtt19": "\uC790\uB3D9 \uBC18\uBCF5 \uACBD\uC7C1",
    "UICreateMahjongMtt20": "\uB300\uD68C\uAC00 \uC2DC\uC791\uB418\uBA74 \uB3D9\uC77C\uD55C \uB300\uD68C\uAC00 \uBC18\uBCF5\uC801\uC73C\uB85C \uC0DD\uC131\uB429\uB2C8\uB2E4. \uC120\uD0DD\uD55C \uC8FC\uC5D0 \uB530\uB77C \uAE30\uC874 \uB300\uD68C\uC640 \uB3D9\uC2DC\uC5D0 \uC0C8\uB85C\uC6B4 \uB300\uD68C\uAC00 \uC9C4\uD589\uB429\uB2C8\uB2E4",
    "UICreateMahjongMtt21": "\uB300\uD68C \uC785\uAE08\uC561\uC744 \uC0DD\uC131\uD558\uC138\uC694 {0}\uB2E4\uC774\uC544, \uB300\uD68C \uC885\uB8CC \uD6C4 \uC2E4\uC81C \uAE08\uC561\uC774 \uC801\uC6A9\uB429\uB2C8\uB2E4",
    "UICreateMahjongMtt22": "\uC81C\uC791\uC790 \uC635\uC158",
    "UICreateMahjongMtt23": "\uC0C1\uB2E8\uC5D0 \uACE0\uC815",
    "UICreateMahjongMtt24": "\uCDE8\uC18CMTT",
    "UICreateMahjongMtt25": "\uC790\uB3D9 \uBC18\uBCF5 \uAD00\uB9AC",
    "UICreateMahjongMtt26": "\uD655\uC778MTT\uB97C \uCDE8\uC18C\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C?\\n\uBC14\uC774\uC778\uC740 \uD50C\uB808\uC774\uC5B4\uC5D0\uAC8C \uD658\uBD88\uB420 \uAC83\uC785\uB2C8\uB2E4",
    "UICreateMahjongMtt27": "\uC774 \uC77C\uCE58 \uD56D\uBAA9\uC740 \uBC18\uBCF5 \uC124\uC815\uC758 \uC77C\uBD80\uC785\uB2C8\uB2E4. \uC644\uC804\uD788 \uC0AD\uC81C\uD558\uB824\uBA74 \uBA3C\uC800 \uBC18\uBCF5 \uC635\uC158\uC744 \uBE44\uD65C\uC131\uD654\uD558\uC2ED\uC2DC\uC624. \uBE44\uD65C\uC131\uD654\uD558\uC9C0 \uC54A\uC73C\uBA74 \uD1A0\uB108\uBA3C\uD2B8\uAC00 \uC790\uB3D9\uC73C\uB85C \uB2E4\uC2DC \uC0DD\uC131\uB429\uB2C8\uB2E4",
    "UICreateMahjongMtt28": "\uC790\uB3D9 \uBC18\uBCF5 \uD45C\uC2DC",
    "UICreateMahjongMtt29": "\uBC18\uBCF5\uC124\uC815 \uC0AD\uC81C",
    "UICreateMahjongMtt30": "\uC120\uD0DD\uD55C \uC790\uB3D9 \uBC18\uBCF5 \uD1A0\uB108\uBA3C\uD2B8\uB97C \uC0AD\uC81C\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C? (\uC774\uBBF8 \uC0DD\uC131\uB41C \uD1A0\uB108\uBA3C\uD2B8\uB294 \uC0AD\uC81C\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.)",
    "UICreateMahjongMtt31": "MTT \uBCC0\uACBD",
    "UICreateMahjongMtt32": "\uC77C\uC815\uC740 \uC815\uAE30\uC801\uC73C\uB85C \uC790\uB3D9 \uC0DD\uC131\uB429\uB2C8\uB2E4. \uC790\uB3D9 \uBC18\uBCF5 \uAE30\uB2A5\uC744 \uD65C\uC131\uD654\uD558\uC2DC\uACA0\uC2B5\uB2C8\uAE4C?",
    "UICreateMahjongMttIllustrate1": "\uACB0\uC81C \uC548\uB0B4",
    "UICreateMahjongMttIllustrate2": "1. MTT \uC0DD\uC131 \uBE44\uC6A9\uC740 \uC9C0\uC6D0\uC790 \uC218\uC5D0 \uB530\uB77C \uBCC0\uACBD\uB429\uB2C8\uB2E4. \uCD5C\uC885 \uC218\uC218\uB8CC\uB294 \uB9C8\uAC10\uC77C\uAE4C\uC9C0 \uC9C0\uC6D0\uC790 \uC218\uC5D0 \uB530\uB77C \uACB0\uC815\uB429\uB2C8\uB2E4.",
    "UICreateMahjongMttIllustrate3": "2.MTT \uBE44\uB514\uC624 \uD14C\uC774\uBE14 \uC694\uAE08\uC740 \uB300\uD68C \uC2DC\uAC04\uACFC \uB4F1\uB85D \uD69F\uC218\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9D1\uB2C8\uB2E4. \uCD5C\uC885 \uBE44\uC6A9\uC740 \uB4F1\uB85D \uB9C8\uAC10\uC77C\uACFC \uB300\uD68C \uAE30\uAC04\uC5D0 \uB530\uB77C \uB2EC\uB77C\uC9D1\uB2C8\uB2E4.",
    "UICreateMahjongMttIllustrate4": "MTT \uC694\uAE08",
    "UICreateMahjongMttIllustrate5": '\uC815\uAC00 : 1\uC778\uB2F9 \uB2E8\uAC00 * \uC2E0\uCCAD\uC778\uC6D0\\n\uD560\uC778\uAC00\uACA9 : \uD560\uC778 \uD6C4 1\uC778\uB2F9 \uB2E8\uAC00 "\uC2E0\uCCAD\uC778\uC6D0"\\n\uC608\uB97C \uB4E4\uC5B4 \uD50C\uB808\uC774\uC5B4\uB2F9 \uB2E8\uAC00\uB294 2\uB2E4\uC774\uC544\uC774\uACE0, \uB4F1\uB85D \uD69F\uC218\uB294 200\uC774\uBA70, \uC218\uC218\uB8CC\uB294 2*200\uC785\uB2C8\uB2E4.',
    "UICreateMahjongMttIllustrate6": "\uBE44\uB514\uC624 \uD14C\uC774\uBE14 \uC694\uAE08",
    "UICreateMahjongMttIllustrate7": "\uC6D0\uAC00 : \uC6D0\uAC00 * N(\uC2DC\uAC04 \uB2E8\uC704) * \uC2E0\uCCAD\uC778\uC6D0\\n\uD560\uC778\uAC00\uACA9 : \uD560\uC778 \uD6C4 \uAC00\uACA9 *N (\uC2DC\uAC04 \uB2E8\uC704) * \uC2E0\uCCAD\uC778\uC6D0\\n\uC608: \uD14C\uC774\uBE14\uB2F9 20\uB2E4\uC774\uC544, \uC2E0\uCCAD\uC790 \uC218\uB294 200\uBA85, \uC218\uC218\uB8CC: 20*N*200",
    "UICreateMahjongMtt33": "\uB4F1\uB85D \uBC29\uBC95",
    "UICreateMahjongMtt34": "\uB300\uD68C \uC2DC\uC791 \uD655\uC778",
    "UICreateMahjongMttTip1": "\uAC8C\uC784\uC744 \uC2DC\uC791\uD558\uB294 \uC778\uC6D0\uC740 4\uC758 \uBC30\uC218\uC5EC\uC57C \uD569\uB2C8\uB2E4",
    "UICreateMahjongMttTip2": "\uC815\uD655\uD55C \uC6B4\uD589 \uC2DC\uAC04\uC744 \uC785\uB825\uD574\uC8FC\uC138\uC694",
    "UICreateMahjongMttTip3": "\uC62C\uBC14\uB978 \uCD08\uACFC\uADFC\uBB34 \uD55C\uB3C4\uB97C \uC785\uB825\uD558\uC138\uC694",
    "UICreateMahjongMttTip4": "\uC815\uD655\uD55C \uCD1D \uB77C\uC6B4\uB4DC \uC218\uB97C \uC785\uB825\uD558\uC138\uC694",
    "UICreateMahjongMttTip5": "\uC815\uD655\uD55C \uB4F1\uB85D\uBE44\uB97C \uC785\uB825\uD574\uC8FC\uC138\uC694",
    "UICreateMahjongMttTip6": "\uC62C\uBC14\uB978 \uAC08\uD034\uB97C \uC785\uB825\uD558\uC138\uC694",
    "UICreateMahjongMttTip7": "\uB450 \uBC30\uC758 \uAC04\uACA9 \uB77C\uC6B4\uB4DC \uC218\uB97C \uC815\uD655\uD558\uAC8C \uC785\uB825\uD558\uC138\uC694",
    "UICreateMahjongMttTip8": "\uBB34\uC791\uC704\uB85C \uD560\uB2F9\uB41C \uAC04\uACA9 \uB77C\uC6B4\uB4DC\uC758 \uC815\uD655\uD55C \uC218\uB97C \uC785\uB825\uD558\uC2ED\uC2DC\uC624",
    "UICreateMahjongMttTip10": "\uC62C\uBC14\uB978 \uB4F1\uB85D \uC2DC\uC791 \uC2DC\uAC04\uC744 \uC120\uD0DD\uD558\uC138\uC694",
    "UICreateMahjongMttTip11": "\uC62C\uBC14\uB978 \uB300\uD68C \uC2DC\uC791 \uC2DC\uAC04\uC744 \uC120\uD0DD\uD558\uC138\uC694",
    "UICreateMahjongMttTip12": "\uC815\uD655\uD55C \uC870\uAE30 \uC785\uC7A5 \uC2DC\uAC04\uC744 \uC785\uB825\uD574\uC8FC\uC138\uC694",
    "UICreateMahjongMttTip13": "\uC790\uB3D9 \uBC18\uBCF5 \uACBD\uC7C1 \uB0A0\uC9DC\uB97C \uC120\uD0DD\uD558\uC138\uC694",
    "UICreateMahjongMttTip14": "\uB300\uD68C \uC2DC\uC791 \uC2DC\uAC04\uC740 \uB4F1\uB85D \uC2DC\uC791 \uC2DC\uAC04\uBCF4\uB2E4 \uCEE4\uC57C \uD569\uB2C8\uB2E4",
    "UICreateMahjongMttTip15": "\uC218\uC5EC\uB418\uB294 \uC778\uC6D0\uC740 \uAC8C\uC784\uC744 \uC2DC\uC791\uD558\uAE30 \uC704\uD55C \uCD5C\uC18C \uC778\uC6D0\uC744 \uCD08\uACFC\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
