    "UIMahjongMttWaitOther": "\uC544\uC9C1 \uB05D\uB098\uC9C0 \uC54A\uC740 \uD14C\uC774\uBE14\uC774 \uC788\uC73C\uB2C8 \uC870\uAE08\uB9CC \uAE30\uB2E4\uB824\uC8FC\uC138\uC694",
    "UICreateMahjongMtt35": "\uD37C\uC13C\uD2B8 \uAE08\uC561",
    "UICreateMahjongMtt36": "\uACE0\uC815 \uAE08\uC561",
    "UICreateMahjongMtt37": "\uCC38\uACE0: \uD604\uC7AC \uAE08\uC561\uC740 \uB3D9\uACB0 \uC608\uC0C1 \uAE08\uC561\uC774\uBA70, \uCD5C\uC885 \uC815\uC0B0\uC740 \uAC8C\uC784 \uC885\uB8CC \uC2DC \uC2E4\uC81C \uACC4\uC0B0\uB41C \uAE08\uC561\uC744 \uAE30\uC900\uC73C\uB85C \uC774\uB8E8\uC5B4\uC9D1\uB2C8\uB2E4.",
    "UICreateMahjongMtt38": "\uC608\uAE08 \uC0DD\uC131",
    "UICreateMahjongMtt39": "\uD1A0\uB108\uBA3C\uD2B8 \uBCF4\uB108\uC2A4",
