    "UICreateMahjongMttTips17": "\uC794\uC561\uC774 \uBD80\uC871\uD558\uBA74 \uBCF4\uB108\uC2A4\uAC00 \uCC28\uAC10\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC0DD\uC131 \uC2E4\uD328",
    "UICreateMahjongMttTips18": "\uCD1D \uBCF4\uB108\uC2A4\uB294 \uB4F1\uB85D\uBE44 \uAE08\uC561\uBCF4\uB2E4 \uC791\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
