    "error1210": "\u0420\u0435\u0436\u0438\u043C \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0441\u043B\u0438\u0448\u043A\u043E\u043C \u0447\u0430\u0441\u0442\u043E, \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u043E \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u0432 \u0442\u0435\u0447\u0435\u043D\u0438\u0435 7 \u0434\u043D\u0435\u0439",
    "error1212": "\u041F\u0440\u0438\u043A\u0430\u0437 \u043E \u0432\u044B\u0432\u043E\u0434\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u043D\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442",
    "error1213": "\u041D\u043E\u043C\u0435\u0440 UC \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0437\u0430 \u043F\u0440\u0435\u0434\u0435\u043B\u0430\u043C\u0438 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u0430 \u0438\u043B\u0438 \u043D\u0435 \u043A\u0440\u0430\u0442\u0435\u043D 100",
    "error1214": "\u0412\u0432\u0435\u0434\u0435\u043D\u043D\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u043F\u0440\u0435\u0432\u044B\u0441\u0438\u043B\u0430 \u043B\u0438\u043C\u0438\u0442 \u0440\u0430\u0441\u0447\u0435\u0442\u0430",
    "error1215": "\u0421\u0443\u043C\u043C\u0430 \u0432\u0432\u043E\u0434\u0430 \u043F\u0440\u0435\u0432\u044B\u0441\u0438\u043B\u0430 \u0444\u043E\u043D\u0434 \u041A\u043B\u0443\u0431\u0430",
    "error1300": "\u0412 \u041A\u043B\u0443\u0431\u0435 \u0443\u0436\u0435 \u0435\u0441\u0442\u044C \u0421\u043E\u044E\u0437",
    "error1301": "\u041F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0449\u0435\u0435\u0441\u044F \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0421\u043E\u044E\u0437 \u0430",
    "error1302": "\u0421\u043E\u044E\u0437 \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D",
    "error1303": "\u041D\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u044F \u043D\u0430 \u0434\u0435\u044F\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0421\u043E\u044E\u0437 \u0430",
    "error1304": "\u041D\u0435 \u043C\u043E\u0433\u0443 \u0432\u044B\u0433\u043D\u0430\u0442\u044C \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u041A\u043B\u0443\u0431",
    "error1305": "\u0421\u043E\u044E\u0437 \u0441\u043E\u0437\u0434\u0430\u0435\u0442\u0441\u044F",
    "error1306": "\u0421\u043E\u044E\u0437 \u0430 \u043D\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u0435\u0442",
    "error1307": "\u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u0430",
    "error1308": "\u0423\u0436\u0435 \u043F\u043E\u0434\u0430\u043B\u0430 \u0437\u0430\u044F\u0432\u043A\u0443 \u0432 \u0421\u043E\u044E\u0437",
    "error1400": "\u041D\u0435\u0442 VIP-\u0430\u043A\u0442\u0438\u0432\u0430\u0446\u0438\u0438",
    "error1401": "\u041D\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0441\u043B\u043E\u043C\u0430\u0442\u044C \u043F\u043B\u0430\u0449",
