    "error1403": "\u041C\u043E\u0436\u043D\u043E \u0441\u043B\u043E\u043C\u0430\u0442\u044C, \u043D\u0435\u043B\u044C\u0437\u044F \u0441\u043B\u043E\u043C\u0430\u0442\u044C",
    "error1404": "\u041E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0442 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u044B\u0435 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B",
    "error1405": "\u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B \u043D\u0435\u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B",
    "error1406": "VIP \u043D\u0435\u043B\u044C\u0437\u044F \u043F\u043E\u043D\u0438\u0437\u0438\u0442\u044C",
    "error1407": "VIP-\u0430\u043F\u0433\u0440\u0435\u0439\u0434 \u043D\u0435\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u0435\u043D",
    "error1500": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0432\u0441\u0442\u0443\u043F\u0438\u0442\u0435 \u0432 \u041A\u043B\u0443\u0431, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0441\u0442\u0430\u0442\u044C \u0410\u0433\u0435\u043D\u0442\u043E\u043C",
    "error1501": "\u0414\u0430\u043D\u043D\u044B\u0435 \u043E\u0431 \u0438\u0433\u0440\u043E\u043A\u0435 \u043D\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0442",
    "error1502": "\u0410\u0433\u0435\u043D\u0442 \u0441\u0432\u044F\u0437\u0430\u043D \u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u044F\u043C\u0438 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u0438\u043A-\u043F\u043E\u0434\u0447\u0438\u043D\u0435\u043D\u043D\u044B\u0439. \u041E\u0448\u0438\u0431\u043A\u0430",
    "error1503": "\u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0440\u0438 \u0432\u0441\u0442\u0430\u0432\u043A\u0435 \u0442\u0430\u0431\u043B\u0438\u0446\u044B \u0441 \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u0435\u0439 \u043E \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0438 \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F",
    "error1600": "\u041F\u0441\u0435\u0432\u0434\u043E\u043D\u0438\u043C \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0435\u0437\u0430\u043A\u043E\u043D\u043D\u044B\u043C \u0438 \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u0442\u044C \u043D\u0435\u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0435 \u0441\u0438\u043C\u0432\u043E\u043B\u044B, \u0442\u0430\u043A\u0438\u0435 \u043A\u0430\u043A Emoji, @, % \u0438 \u0437\u0430\u043F\u044F\u0442\u0430\u044F (,)",
    "error1601": "\u041F\u0440\u0435\u0432\u044B\u0448\u0435\u043D\u043E \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0435\u0432",
    "error1700": "\u041D\u0435\u0442 \u0430\u0434\u0440\u0435\u0441\u0430 \u0434\u043E\u0441\u0442\u0430\u0432\u043A\u0438",
    "error1701": "\u041D\u0435\u0442 \u043F\u0440\u0438\u0437\u043E\u0432",
    "error1702": "\u041F\u0440\u0438\u043C\u0435\u043D\u0435\u043D\u0438\u0435",
    "error1703": "\u0423\u0436\u0435 \u043F\u043E\u043B\u0443\u0447\u0435\u043D",
    "error1800": "\u0421\u0431\u043E\u0440 \u0440\u0443\u043A \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u0435\u0442 \u043B\u0438\u043C\u0438\u0442",
