    "BindingAlipayMoidify": "\u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C Alipay",
    "BindingAlipay": "\u041F\u0440\u0438\u0432\u044F\u0437\u0430\u0442\u044C Alipay",
    "BindingCardMoidify": "\u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0431\u0430\u043D\u043A\u043E\u0432\u0441\u043A\u0443\u044E \u043A\u0430\u0440\u0442\u0443",
