    "UIMine_Mission_9": "\u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0430\u0432\u0430\u0442\u0430\u0440",
    "UIMine_Mission_10": "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0439 \u0441\u0430\u0439\u0442",
    "UIMine_Mission_11": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0423\u0441\u043F\u0435\u0448\u043D\u043E",
    "error2500": "\u0415\u0441\u043B\u0438 \u0432\u044B \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u043D\u0435 \u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0442\u043E\u0432\u0430\u0440 \u043F\u043E \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u043C \u043F\u0440\u0438\u0447\u0438\u043D\u0430\u043C, \u043E\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044C \u0432 \u0441\u043B\u0443\u0436\u0431\u0443 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0438 \u043A\u043B\u0438\u0435\u043D\u0442\u043E\u0432.",
    "adaptation20078": "\u041F\u043E\u0437\u0434\u0440\u0430\u0432\u043B\u044F\u0435\u043C##\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C## UC",
    "UITexasMarqueeGame_Title": "\u0422\u0435\u043A\u0443\u0449\u0438\u0439 \u043F\u0440\u0438\u0437\u043E\u0432\u043E\u0439 \u0444\u043E\u043D\u0434",
    "UITexasMarqueeGame_Content": "1.\u0412\u043A\u043B. \u0423\u0441\u043B\u043E\u0432\u0438\u044F: \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u0439 \u0412\u043A\u043B.\\n2. \u0423\u0441\u043B\u043E\u0432\u0438\u044F \u0443\u0447\u0430\u0441\u0442\u0438\u044F: \u041C\u0435\u0440\u043E\u043F\u0440\u0438\u044F\u0442\u0438\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F\u043C, \u043D\u0430\u0445\u043E\u0434\u044F\u0449\u0438\u043C\u0441\u044F \u043E\u043D\u043B\u0430\u0439\u043D \u0438 \u0432 \u0438\u0433\u0440\u0435\\n\u041A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0443\u0447\u0430\u0441\u0442\u043D\u0438\u043A\u043E\u0432, \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0445 \u0432 \u043C\u0435\u0440\u043E\u043F\u0440\u0438\u044F\u0442\u0438\u0438, \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C \u2265 4\\n3. \u0418\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u0438 \u043F\u043E \u043D\u0430\u0433\u0440\u0430\u0436\u0434\u0435\u043D\u0438\u044E: \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u043C \u043E\u0431\u0440\u0430\u0437\u043E\u043C \u0432\u044B\u0431\u0435\u0440\u0435\u0442 \u0438\u0433\u0440\u043E\u043A\u0430 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C \u0432 \u043A\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F.\\n4. \u041E\u043F\u0438\u0441\u0430\u043D\u0438\u0435 \u043D\u0430\u0433\u0440\u0430\u0434\u044B: \u041D\u0430\u0433\u0440\u0430\u0434\u044B \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u0435\u0439 \u0431\u0443\u0434\u0443\u0442 \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u044B \u0432 \u041A\u043E\u0448\u0435\u043B\u0451\u043A \u0438\u0433\u0440\u043E\u043A\u043E\u0432\\n\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u0435. \u042D\u0442\u043E \u0437\u0430\u043D\u044F\u0442\u0438\u0435 \u043F\u0440\u0435\u0434\u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u043E \u0434\u043B\u044F \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u044F \u0443\u0434\u043E\u0432\u043E\u043B\u044C\u0441\u0442\u0432\u0438\u044F \u043E\u0442 \u0438\u0433\u0440\u044B \u0438 \u0443\u043B\u0443\u0447\u0448\u0435\u043D\u0438\u044F \u0438\u0433\u0440\u043E\u0432\u044B\u0445 \u0432\u043F\u0435\u0447\u0430\u0442\u043B\u0435\u043D\u0438\u0439. \u0415\u0441\u043B\u0438 \u0432\u0430\u043C \u043F\u043E\u0432\u0435\u0437\u0435\u0442, \u0432\u044B \u0441\u043C\u043E\u0436\u0435\u0442\u0435 \u043E\u0447\u0438\u0441\u0442\u0438\u0442\u044C \u043F\u0440\u0438\u0437\u043E\u0432\u043E\u0439 \u0444\u043E\u043D\u0434 \u0438 \u0434\u0435\u043B\u0430\u0442\u044C \u0432\u0441\u0435, \u0447\u0442\u043E \u0437\u0430\u0445\u043E\u0442\u0438\u0442\u0435.",
    "UITexasMarqueeGame_Tips": "\u0422\u0435\u043A\u0443\u0449\u0430\u044F \u0441\u0443\u043C\u043C\u0430 \u0432\u043E\u0437\u043D\u0430\u0433\u0440\u0430\u0436\u0434\u0435\u043D\u0438\u044F \u0431\u0443\u0434\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u0430 \u0441\u043B\u0443\u0447\u0430\u0439\u043D\u044B\u043C \u043E\u0431\u0440\u0430\u0437\u043E\u043C \u0432 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u0441 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E\u043C \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u0435\u0439 \u0432 \u043F\u0440\u0438\u0437\u043E\u0432\u043E\u043C \u0444\u043E\u043D\u0434\u0435 \u0432 \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u043C \u0432\u0440\u0435\u043C\u0435\u043D\u0438. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0441 \u043D\u0430\u0438\u0432\u044B\u0441\u0448\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439 \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0441\u0443\u043C\u043C\u0443 \u0431\u043E\u043B\u0435\u0435 5W \u044E\u0430\u043D\u0435\u0439.",
