    "UINiuZaiXiaZhuQu_content01": "1. \u0417\u043E\u043D\u0430 \u043F\u043E\u0431\u0435\u0434, \u043F\u043E\u0440\u0430\u0436\u0435\u043D\u0438\u0439 \u0438 \u043D\u0438\u0447\u044C\u0435\u0439: \u043F\u043E\u0431\u0435\u0434\u0430 \xAB\u041A\u043E\u0432\u0431\u043E\u0435\u0432\xBB, \u043D\u0438\u0447\u044C\u044F, \u043F\u043E\u0431\u0435\u0434\u0430 \xAB\u0411\u044B\u043A\u043E\u0432\xBB;",
    "UINiuZaiXiaZhuQu_content02": "2. \u041B\u044E\u0431\u0430\u044F \u043E\u0431\u043B\u0430\u0441\u0442\u044C \u043A\u0430\u0440\u0442 \u043D\u0430 \u0440\u0443\u043A\u0435: \u0444\u043B\u0435\u0448/\u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B/\u043E\u0434\u043D\u043E\u043C\u0430\u0441\u0442\u043D\u044B\u0435 \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B, \u043F\u0430\u0440\u0430 \u0442\u0443\u0437\u043E\u0432;",
    "UINiuZaiXiaZhuQu_content03": "3. \u041E\u0431\u043B\u0430\u0441\u0442\u044C \u0442\u0438\u043F\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u043E\u0439 \u043A\u0430\u0440\u0442\u044B: \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430/\u043E\u0434\u043D\u0430 \u043F\u0430\u0440\u0430, \u0434\u0432\u0435 \u043F\u0430\u0440\u044B, \u0442\u0440\u043E\u0439\u043A\u0430/\u0441\u0442\u0440\u0438\u0442-\u0444\u043B\u0435\u0448, \u0444\u0443\u043B\u043B-\u0445\u0430\u0443\u0441, \u043A\u0438\u043D\u0433-\u043A\u043E\u043D\u0433/\u0441\u0442\u0440\u0438\u0442-\u0444\u043B\u0435\u0448/\u0440\u043E\u044F\u043B\u044C-\u0444\u043B\u0435\u0448.",
    "UINiuZai_high_one": "\u0421\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430/\u043F\u0430\u0440\u0430",
    "UINiuZaiXiaZhuQu_content04": "\u0425\u0443\u0430\u043D \u0422\u043E\u043D\u0433",
    "UINiuZaiInsurance_titleTwo": "\u0420\u0430\u0437\u043C\u0435\u0440 \u043A\u0430\u0440\u0442\u044B [\u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u043C\u0430\u0441\u0442\u0438]",
    "UINiuZaiXiaZhuQu_content05": "1.\u0422\u0438\u043F \u043A\u0430\u0440\u0442\u044B: \u0420\u043E\u044F\u043B \u0422\u043E\u043D\u0433>\u0424\u043B\u0435\u0448-\u0447\u0435\u0442\u0432\u0435\u0440\u043A\u0430>\u041A\u0430\u0440\u0435>\u0424\u0443\u043B\u043B-\u0445\u0430\u0443\u0441>\u0424\u043B\u0435\u0448>\u0421\u0442\u0440\u0438\u0442>\u0422\u0440\u043E\u0439\u043A\u0430>\u0414\u0432\u0435 \u043F\u0430\u0440\u044B>\u041F\u0430\u0440\u0430>",
    "UINiuZaiXiaZhuQu_content06": "\u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430;",
    "UINiuZaiXiaZhuQu_content07": "2. \u041E\u0434\u0438\u043D\u043E\u0447\u043D\u0430\u044F \u043A\u0430\u0440\u0442\u0430: A>K>Q>J>10>9>8>7>6>5>4>3>2;",
    "UINiuZaiXiaZhuQu_content08": "3. \u041E\u0434\u0438\u043D \u0438 \u0442\u043E\u0442 \u0436\u0435 \u0442\u0438\u043F \u043A\u0430\u0440\u0442\u044B: \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u0430\u043C\u0443\u044E \u0431\u043E\u043B\u044C\u0448\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u0435\u0441\u043B\u0438 \u043E\u0434\u043D\u0430 \u0438 \u0442\u0430 \u0436\u0435 \u043A\u0430\u0440\u0442\u0430 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u0430, \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0439\u0442\u0435 \u0441\u0440\u0430\u0432\u043D\u0435\u043D\u0438\u0435 \u0432\u043D\u0438\u0437, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, 5 \u043A\u0430\u0440\u0442.",
    "UINiuZaiXiaZhuQu_content09": "\u0415\u0441\u043B\u0438 \u043A\u0430\u0440\u0442\u044B \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435, \u044D\u0442\u043E \u043D\u0438\u0447\u044C\u044F;",
    "UINiuZaiInsurance_titleThree": "\u0420\u0430\u0437\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u0440\u0430\u0432\u0438\u043B\u0430",
    "UINiuZaiXiaZhuQu_content011": "\u041A\u043E\u0433\u0434\u0430 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u0444\u0438\u0448\u0435\u043A \u0434\u0438\u043B\u0435\u0440\u0430 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E \u0434\u043B\u044F \u043A\u043E\u043C\u043F\u0435\u043D\u0441\u0430\u0446\u0438\u0438 \u0432\u0441\u0435\u043C \u0432\u044B\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u043C \u0438\u0433\u0440\u043E\u043A\u0430\u043C, \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u0444\u0438\u0448\u043A\u0438 \u0434\u0438\u043B\u0435\u0440\u0430",
    "UINiuZaiXiaZhuQu_content012": "\u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043E\u0447\u043A\u0438 \u0431\u0443\u0434\u0443\u0442 \u043F\u0440\u043E\u043F\u043E\u0440\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u043E \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u044B \u043F\u043E\u0431\u0435\u0434\u0438\u0432\u0448\u0435\u043C\u0443 \u0438\u0433\u0440\u043E\u043A\u0443, \u0438 \u043F\u043E\u0441\u043B\u0435 \u0440\u0430\u0441\u0447\u0435\u0442\u0430 \u0417\u0430\u043A\u0440\u044B\u0442\u044C \u043A\u043E\u043C\u043D\u0430\u0442\u0443",
    "UINiuZaiXiaZhuQu_content013": "\u041A\u043E\u043C\u043D\u0430\u0442\u0430",
    "UINiuZaiToggle_tishi": "\u0421\u043E\u0432\u0435\u0442\u044B \u043F\u043E \u0442\u0438\u043F\u0430\u043C \u043A\u0430\u0440\u0442",
    "UINiuZaiToggle_paiju": "\u041E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u0438\u0433\u0440\u043E\u0432\u043E\u0439 \u043F\u0440\u043E\u0446\u0435\u0441\u0441",
