    "UINiuZaiRule_tips03": "\u041D\u0438\u0447\u044C\u044F",
    "UINiuZaiRule_tipsTwo": "\u041B\u044E\u0431\u0430\u044F \u043E\u0431\u043B\u0430\u0441\u0442\u044C \u0440\u0443\u043A",
    "UINiuZaiRule_tips04": "\u0420\u0430\u0437\u044A\u0435\u043C \u0437\u0430\u043F\u043E\u0434\u043B\u0438\u0446\u043E/\u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u044B\u0439/\u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0439",
    "UINiuZaiRule_tips05": "\u041F\u0430\u0440\u0430",
    "UINiuZaiRule_tips06": "\u041F\u0430\u0440\u0430 \u0410",
    "UINiuZaiRule_tipsThree": "\u041B\u044E\u0431\u0430\u044F \u043E\u0431\u043B\u0430\u0441\u0442\u044C \u0440\u0443\u043A",
    "UINiuZaiRule_tips07": "\u0422\u0440\u0438\u043F/\u043F\u0440\u044F\u043C\u043E\u0439/\u0444\u043B\u0435\u0448",
    "UINiuZaiRule_tips08": "\u0421\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430",
    "UINiuZaiRule_tips09": "\u0414\u0432\u0435 \u043F\u0430\u0440\u044B",
    "UINiuZaiRule_tips010": "\u0410\u043D\u0448\u043B\u0430\u0433",
    "UINiuZaiRule_tips011": "\u041A\u0438\u043D\u0433-\u041A\u043E\u043D\u0433 / \u0421\u0442\u0440\u0438\u0442-\u0444\u043B\u0435\u0448 / \u0420\u043E\u044F\u043B-\u0444\u043B\u0435\u0448",
