    "UiVoiceprint_10024": "{0}\u041E\u0442\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0443\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0432 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0435 \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u043B\u0438\u0446\u0430. \u0410\u043A\u043A\u0430\u0443\u043D\u0442 \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043C\u043E\u0440\u043E\u0436\u0435\u043D \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u0438.",
    "UiVoiceprint_10025": "\u0420\u0430\u0437\u0432\u0435\u0440\u043D\u0443\u0442\u044C {0}?",
    "UiVoiceprint_10026": "\u041C\u043E\u0436\u0435\u0442 \u0432\u043E\u0441\u043F\u0440\u043E\u0438\u0437\u0432\u0435\u0441\u0442\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u043D\u044B\u0439 \u043E\u0440\u0438\u0433\u0438\u043D\u0430\u043B\u044C\u043D\u044B\u0439 \u043E\u0442\u043F\u0435\u0447\u0430\u0442\u043E\u043A \u0433\u043E\u043B\u043E\u0441\u0430 {0} \u0438 \u0441\u0440\u0430\u0432\u043D\u0438\u0442\u044C \u0435\u0433\u043E \u0441 \u0440\u0435\u0430\u043B\u044C\u043D\u044B\u043C \u043E\u0442\u043F\u0435\u0447\u0430\u0442\u043A\u043E\u043C \u0433\u043E\u043B\u043E\u0441\u0430. \u0421\u0442\u043E\u0438\u0442 \u043B\u0438 \u0432\u0430\u043C \u043F\u0440\u043E\u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u0442\u044C \u0437\u0430 \u043D\u0435\u0433\u043E?",
    "UiVoiceprint_10027": "\u041F\u043E\u0441\u043B\u0435 \u0442\u043E\u0433\u043E, \u043A\u0430\u043A \u0432\u0430\u0441 \u043F\u043E\u043C\u0435\u0441\u0442\u044F\u0442 \u043D\u0430 \u0441\u0442\u043E\u043B, \u0432\u044B \u0441\u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u0433\u043E\u043B\u043E\u0441\u043E\u0432\u0430\u043D\u0438\u0438 \u043F\u043E \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0435 \u0438\u0433\u0440\u043E\u043A\u0430 \u0432 \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u043C \u0432\u0440\u0435\u043C\u0435\u043D\u0438.",
    "UiVoiceprint_10028": "\u0415\u0441\u043B\u0438 \u0432\u044B \u043E\u0442\u043A\u0430\u0436\u0435\u0442\u0435\u0441\u044C \u0443\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0432 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0435 \u043B\u0438\u0447\u043D\u043E\u0441\u0442\u0438, \u0432\u0430\u0448\u0430 \u0443\u0447\u0435\u0442\u043D\u0430\u044F \u0437\u0430\u043F\u0438\u0441\u044C \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043C\u043E\u0440\u043E\u0436\u0435\u043D\u0430. \u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043A\u0430\u043A\u0438\u0435-\u043B\u0438\u0431\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u044B, \u043E\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044C \u0432 \u0441\u043B\u0443\u0436\u0431\u0443 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0438 \u043A\u043B\u0438\u0435\u043D\u0442\u043E\u0432",
    "UiVoiceprint_10029": "\u0421\u0438\u0441\u0442\u0435\u043C\u0430 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u043B\u0430 \u0432\u0430\u0441 \u043A\u0430\u043A \u0440\u043E\u0431\u043E\u0442\u0430 \u0438 \u0432\u0430\u0448 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043C\u043E\u0440\u043E\u0436\u0435\u043D. \u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043A\u0430\u043A\u0438\u0435-\u043B\u0438\u0431\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u044B, \u043E\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044C \u0432 \u0441\u043B\u0443\u0436\u0431\u0443 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0438 \u043A\u043B\u0438\u0435\u043D\u0442\u043E\u0432",
    "UiVoiceprint_10030": "\u041F\u0440\u043E\u0432\u0435\u0440\u043E\u0447\u043D\u0430\u044F \u0437\u0430\u043F\u0438\u0441\u044C",
    "UiVoiceprint_10031": "\u0421\u043E\u043C\u043D\u0435\u043D\u0438\u0435<color=#DDBA82>{0}</color>\u0420\u043E\u0431\u043E\u0442 \u043D\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u043F\u043E\u0440\u044F\u0434\u043E\u043A \u0438\u0433\u0440\u044B? \u0418\u043D\u0438\u0446\u0438\u0438\u0440\u043E\u0432\u0430\u0442\u044C, \u0441\u043B\u0435\u0434\u0443\u0435\u0442 \u043B\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0442\u044C \u043E\u0442\u043F\u0435\u0447\u0430\u0442\u043E\u043A \u0433\u043E\u043B\u043E\u0441\u0430 \u0440\u0435\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430",
    "UiVoiceprint_10032": "\u041D\u0430\u0447\u0430\u0442\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0443",
