    "UIShare_ShareFriends": "\u041F\u0440\u0438\u0433\u043B\u0430\u0441\u0438\u0442\u0435 \u0434\u0440\u0443\u0437\u0435\u0439 \u043F\u0440\u0438\u043D\u044F\u0442\u044C \u0443\u0447\u0430\u0441\u0442\u0438\u0435",
    "UIMine_Backpack_FreeServiceVoucherDescriptions": "\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u044F:\\n\u041A\u0430\u0436\u0434\u044B\u0439 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0432\u0430\u0443\u0447\u0435\u0440 \u0441\u043D\u0438\u0436\u0430\u0435\u0442 \u0440\u0435\u0439\u043A \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u0432 \u043B\u044E\u0431\u043E\u043C \u0442\u0443\u0440\u043D\u0438\u0440\u0435 MTT, \u0438 \u0434\u043B\u044F \u0442\u043E\u0433\u043E, \u0447\u0442\u043E\u0431\u044B \u043E\u043D \u0432\u0441\u0442\u0443\u043F\u0438\u043B \u0432 \u0441\u0438\u043B\u0443, \u0435\u0433\u043E \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u0430\u043A\u0442\u0438\u0432\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C.",
    "UIMine_Backpack_RechargeVoucherDescriptions": "\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u044F:\\n\u041E\u0434\u043D\u0430 \u0442\u0440\u0430\u043D\u0437\u0430\u043A\u0446\u0438\u044F {0} UC \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0441\u043F\u0438\u0441\u0430\u043D\u0430 \u0432 \u0432\u0438\u0434\u0435 \u0432\u0430\u0443\u0447\u0435\u0440\u0430 {1} \u0432 \u044E\u0430\u043D\u044F\u0445, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043F\u0440\u0438 \u0441\u043E\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0438 \u043F\u043B\u0430\u0442\u0435\u0436\u0430 \u0432 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0435 \u0414\u0435\u043F\u043E\u0437\u0438\u0442.",
    "UIMine_Backpack_ChipsVoucherDescriptions": "\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u044F:\\n\u041F\u043E\u0441\u043B\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u044F {0} UC \u0431\u0443\u0434\u0435\u0442 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D \u043D\u0435\u043F\u043E\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u0432 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 UC \u0438 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0432\u044B\u0432\u0435\u0434\u0435\u043D.",
    "UIMine_Backpack_OneShopVoucherDescriptions": "\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u044F:\\n\u041F\u043E\u0441\u043B\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u044F \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u043A\u0443\u043F\u043E\u043D \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0441\u0442\u0438 \u043D\u0435\u043F\u043E\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u0432 \u0443\u0447\u0435\u0442\u043D\u0443\u044E \u0437\u0430\u043F\u0438\u0441\u044C \u043A\u0443\u043F\u043E\u043D\u0430 \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0441\u0442\u0438 \u043F\u043E\u043A\u0443\u043F\u043A\u0438 \u0432 \u043E\u0434\u043D\u043E\u043C \u044E\u0430\u043D\u0435. \u041A\u0443\u043F\u043E\u043D \u043D\u0430 \u043F\u043E\u043A\u0443\u043F\u043A\u0443 \u0432 \u043E\u0434\u0438\u043D \u044E\u0430\u043D\u044C \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0434\u043B\u044F \u0443\u0447\u0430\u0441\u0442\u0438\u044F \u0432 \u0430\u043A\u0446\u0438\u0438 \xAB\u041F\u043E\u043A\u0443\u043F\u043A\u0430 \u0432 \u043E\u0434\u0438\u043D \u044E\u0430\u043D\u044C\xBB.",
    "UIMine_Backpack_PropVoucherDescriptions": "\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u0435:\\n\u041A\u0430\u0436\u0434\u044B\u0439 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0449\u0438\u0439 \u043A\u0443\u043F\u043E\u043D 1 \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0432\u043C\u0435\u0441\u0442\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u044F \u043B\u044E\u0431\u043E\u0433\u043E \u0440\u0435\u043A\u0432\u0438\u0437\u0438\u0442\u0430 1 \u0440\u0430\u0437 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u043E, \u043D\u0435 \u0442\u0440\u0430\u0442\u044F UC.",
    "UIMine_Backpack_FreeServiceVoucher": "\u0412\u0430\u0443\u0447\u0435\u0440 \u043D\u0430 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u044B\u0439 \u0440\u0435\u0439\u043A \u0432 \u041C\u0422\u0422",
    "UIMine_Backpack_RechargeVoucher": "{0} \u0414\u0435\u043F\u043E\u0437\u0438\u0442\u043D\u044B\u0439 \u0432\u0430\u0443\u0447\u0435\u0440 \u0432 \u044E\u0430\u043D\u044F\u0445",
    "UIMine_Backpack_ChipsVoucher": "{0}\u0412\u0430\u0443\u0447\u0435\u0440 UC",
    "UIMine_Backpack_OneShopVoucher": "\u041A\u0443\u043F\u043E\u043D \u043D\u0430 \u043F\u043E\u043A\u0443\u043F\u043A\u0443 \u043D\u0430 \u043E\u0434\u0438\u043D \u0434\u043E\u043B\u043B\u0430\u0440",
    "UIMine_Backpack_PropVoucher": "\u041F\u0440\u043E\u043F-\u0432\u0430\u0443\u0447\u0435\u0440",
    "UIMTT_FreeServer": "\u042D\u0442\u043E\u0442 \u0440\u0435\u0439\u043A \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u0435\u043D",
    "UIMine_FreeAward_DetailExplain": "<color=#DCBA82>\u0435\u0436\u0435\u0434\u043D\u0435\u0432\u043D\u044B\u0435 \u0437\u0430\u0434\u0430\u0447\u0438</color>\\n\u0412\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0438\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u0437\u0430\u0434\u0430\u0447 \u0437\u0430 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043D\u043E\u0435 \u0432\u0440\u0435\u043C\u044F, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043D\u0430\u0433\u0440\u0430\u0434\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0440\u0435\u0433\u0443\u043B\u044F\u0440\u043D\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043A\u0430\u0436\u0434\u044B\u0439 \u0434\u0435\u043D\u044C. \u041D\u0435\u0432\u043E\u0441\u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u043D\u0430\u0433\u0440\u0430\u0434\u044B \u0431\u0443\u0434\u0443\u0442 \u0441\u0447\u0438\u0442\u0430\u0442\u044C\u0441\u044F \u043E\u0442\u043A\u0430\u0437\u043E\u043C \u043E\u0442 \u0443\u0447\u0430\u0441\u0442\u0438\u044F.\\n\\n<color=#DCBA82>\u0414\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F</color>\\n\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0435 \u043D\u0430\u0433\u0440\u0430\u0434\u044B, \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0432 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u044B\u0435 \u0438\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u0437\u0430\u0434\u0430\u0447. \u041E\u043D\u0438 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0442 \u0432\u0441\u0435\u0433\u0434\u0430 \u0438 \u043D\u0435 \u0438\u043C\u0435\u044E\u0442 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0439 \u043F\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438.\\n\\n<color=#DCBA82>\u041D\u0430\u0433\u0440\u0430\u0434\u044B</color>\\n\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u0438\u044F \u043D\u0430\u0433\u0440\u0430\u0434\u044B \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u043E\u0441\u0442\u044C \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u044F \u043D\u0430\u0433\u0440\u0430\u0434\u044B \u0432 \u043C\u043E\u0435\u043C \u0440\u044E\u043A\u0437\u0430\u043A\u0435.",
