    "UISetting_SecurityBindFirst": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043F\u0440\u0438\u0432\u044F\u0436\u0438\u0442\u0435 \u0441\u0432\u043E\u0439 \u043C\u043E\u0431\u0438\u043B\u044C\u043D\u044B\u0439 \u0442\u0435\u043B\u0435\u0444\u043E\u043D \u0438\u043B\u0438 \u0430\u0434\u0440\u0435\u0441 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0447\u0442\u044B",
    "UIBindPhoneTips": "\u0412\u044B \u0435\u0449\u0435 \u043D\u0435 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043B\u0438 \u0441\u0432\u043E\u0439 \u043D\u043E\u043C\u0435\u0440 \u043C\u043E\u0431\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430. \u0414\u043B\u044F \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E\u0441\u0442\u0438 \u0432\u0430\u0448\u0435\u0439 \u0443\u0447\u0435\u0442\u043D\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u0438, \u043F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043F\u0440\u0438\u0432\u044F\u0436\u0438\u0442\u0435 \u043D\u043E\u043C\u0435\u0440 \u0441\u0432\u043E\u0435\u0433\u043E \u043C\u043E\u0431\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430. \u0412 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0430\u0437 \u0432\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u043D\u043E\u043C\u0435\u0440 \u0441\u0432\u043E\u0435\u0433\u043E \u043C\u043E\u0431\u0438\u043B\u044C\u043D\u043E\u0433\u043E \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0430.",
    "UISetting_SecurityBindEmailAlert": "\u041F\u043E\u0441\u043B\u0435 \u0441\u043C\u0435\u043D\u044B \u0430\u0434\u0440\u0435\u0441\u0430 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0447\u0442\u044B \u0432\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0430\u0437 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0430\u0434\u0440\u0435\u0441 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0447\u0442\u044B \u0412\u043E\u0439\u0442\u0438",
    "UIHappyShop_Super1WinTitle": "\u041A\u043E\u043B\u043E\u043D\u043A\u0430 \u043B\u043E\u0442\u0435\u0440\u0435\u0438 \u043F\u0440\u043E\u0434\u0443\u043A\u0442\u043E\u0432",
    "UIHappyShop_Super1WinNum": "\u0412\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u044B\u0439 \u043D\u043E\u043C\u0435\u0440",
    "UIHappyShop_Super1WinPlayer": "\u0421\u0447\u0430\u0441\u0442\u043B\u0438\u0432\u0447\u0438\u043A",
    "UIHappyShop_Super1WinTime": "\u0412\u0440\u0435\u043C\u044F \u043B\u043E\u0442\u0435\u0440\u0435\u0438",
    "UIHappyShop_Super1WinLuckNewsTC": "\u041F\u043E\u0437\u0434\u0440\u0430\u0432\u043B\u044F\u0435\u043C \u0432\u0430\u0441 \u0441 \u0442\u0435\u043C, \u0447\u0442\u043E \u0432\u044B \u0441\u0442\u0430\u043B\u0438 \u0441\u0447\u0430\u0441\u0442\u043B\u0438\u0432\u044B\u043C \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0435\u043C \u0432 \u0430\u043A\u0446\u0438\u0438 \xAB\u041F\u043E\u043A\u0443\u043F\u043A\u0430 \u0437\u0430 \u043E\u0434\u0438\u043D \u044E\u0430\u043D\u044C\xBB. \u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0432\u044B\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u0445 \u0414\u0435\u0442\u0430\u043B\u0438 \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \xAB\u041F\u043E\u043A\u0443\u043F\u043A\u0430 \u0437\u0430 \u043E\u0434\u0438\u043D \u044E\u0430\u043D\u044C\xBB \u2014 \xAB\u041C\u043E\u0438 \u043F\u0440\u0438\u0437\u044B\xBB!",
    "UIHappyShop_Super1WinLuckNewsTitle": "\u0421\u043E\u0432\u0435\u0442\u044B \u043F\u043E \u043F\u043E\u0431\u0435\u0434\u0435",
    "UIHappyShop_Super1WinLuckNewsPMD": "\u041F\u043E\u0437\u0434\u0440\u0430\u0432\u043B\u044F\u0435\u043C \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F {0} \u0441 \u0442\u0435\u043C, \u0447\u0442\u043E \u043E\u043D \u0441\u0442\u0430\u043B \u0441\u0447\u0430\u0441\u0442\u043B\u0438\u0432\u044B\u043C \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u0435\u043C \u0438 \u043F\u043E\u043B\u0443\u0447\u0438\u043B {1} \u043F\u0440\u043E\u0434\u0443\u043A\u0442\u043E\u0432 \u0432 \u0440\u0430\u043C\u043A\u0430\u0445 \u0430\u043A\u0446\u0438\u0438 \u043F\u043E \u043F\u043E\u043A\u0443\u043F\u043A\u0435 \u0437\u0430 \u043E\u0434\u0438\u043D \u044E\u0430\u043D\u044C!",
    "UIHappyShop_Super1WinUnLuckNews": "\u0416\u0430\u043B\u044C, \u0447\u0442\u043E \u0432\u044B \u043D\u0435 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u043F\u0440\u0438\u0437 \u0432 \u0430\u043A\u0446\u0438\u0438 {0}, \u043A\u0443\u043F\u0438\u0432 \u0442\u043E\u0432\u0430\u0440\u044B {1} \u043D\u0430 \u043E\u0434\u0438\u043D \u0434\u043E\u043B\u043B\u0430\u0440. \u0421\u043F\u0430\u0441\u0438\u0431\u043E \u0437\u0430 \u0432\u0430\u0448\u0435 \u0443\u0447\u0430\u0441\u0442\u0438\u0435!",
    "UIHappyShop_Super1WinLuckNewsBag": "\u0412 \u0445\u043E\u0434\u0435 \u0430\u043A\u0446\u0438\u0438 \u043F\u043E \u043F\u043E\u043A\u0443\u043F\u043A\u0435 \u0437\u0430 \u043E\u0434\u0438\u043D \u044E\u0430\u043D\u044C \u0431\u044B\u043B\u043E \u043F\u0440\u0438\u043E\u0431\u0440\u0435\u0442\u0435\u043D\u043E \u0432 \u043E\u0431\u0449\u0435\u0439 \u0441\u043B\u043E\u0436\u043D\u043E\u0441\u0442\u0438 {0} \u0442\u043E\u0432\u0430\u0440\u043E\u0432{1}",
    "UIClub_ClubFounder": "\u0421\u043E\u0437\u0434\u0430\u0442\u0435\u043B\u044C",
    "UIHallOfFame_enter": "\u0417\u0430\u043B \u0441\u043B\u0430\u0432\u044B",
    "UIMine_Backpack_PropMTTVoucherDes": "\u041F\u0440\u0438\u043C\u0435\u0447\u0430\u043D\u0438\u0435:\\n\u0412\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u0443\u043C\u0435\u043D\u044C\u0448\u0438\u0442\u044C {0} UC \u043F\u0440\u0438 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438, \u0434\u043E\u043A\u0443\u043F\u043A\u0435 \u0438 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0438 \u0432 \u041C\u0422\u0422. \u042D\u0442\u043E\u0442 \u043A\u0443\u043F\u043E\u043D \u043F\u0440\u0435\u0434\u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D \u0434\u043B\u044F \u0435\u0434\u0438\u043D\u043E\u0440\u0430\u0437\u043E\u0432\u043E\u0433\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u044F \u0440\u0435\u043A\u0432\u0438\u0437\u0438\u0442\u0430.",
    "UIMine_Backpack_PropMTTNoFreeVoucherDes": "\u0412\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u0441\u043D\u0438\u0437\u0438\u0442\u044C {0} UC \u043F\u0440\u0438 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438, \u0440\u0435\u0431\u0430\u0435 \u0438 \u0430\u0434\u0434\u043E\u043D\u0435 \u0432 \u041C\u0422\u0422, \u043D\u043E \u044D\u0442\u043E \u043D\u0435 \u0432\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0440\u0435\u0439\u043A\u0430. \u042D\u0442\u043E\u0442 \u043A\u0443\u043F\u043E\u043D \u043F\u0440\u0435\u0434\u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D \u0434\u043B\u044F \u0435\u0434\u0438\u043D\u043E\u0440\u0430\u0437\u043E\u0432\u043E\u0433\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u044F \u0440\u0435\u043A\u0432\u0438\u0437\u0438\u0442\u0430.",
    "UIMTT_LimitFree": "\u042D\u0442\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043D\u043E\u0435 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u0435",
    "UIMTT_LimitFreeNoServer": "\u042D\u0442\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043D\u043E\u0435 \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0435\u043D\u0438\u0435 (\u0437\u0430 \u0438\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435\u043C \u0420\u0435\u0439\u043A\u0430)",
    "UIClub_NoTelAlert": "\u041A\u043B\u0443\u0431 \u043D\u0435 \u0437\u0430\u043F\u043E\u043B\u043D\u0438\u043B \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u043D\u0443\u044E \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044E",
