    "UISHOPguide": "\u0420\u0443\u043A\u043E\u0432\u043E\u0434\u0441\u0442\u0432\u043E \u0434\u043B\u044F \u043D\u043E\u0432\u0438\u0447\u043A\u043E\u0432",
    "UIClub_belongLeague": "\u041F\u0440\u0438\u043D\u0430\u0434\u043B\u0435\u0436\u043D\u043E\u0441\u0442\u044C \u043A \u0421\u043E\u044E\u0437 \u0443",
    "UIClub_CreateSuccess": "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0423\u0441\u043F\u0435\u0448\u043D\u043E",
    "MsgInfo_4009": "\u0421\u043E\u0437\u0434\u0430\u043D\u043D\u044B\u0439 \u0432\u0430\u043C\u0438 {0}\u041A\u043B\u0443\u0431 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D.",
    "UIClub_InputLeagueId": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u0431\u043E\u0435\u0432\u043E\u0433\u043E \u0441\u043E\u043E\u0431\u0449\u0435\u0441\u0442\u0432\u0430",
    "UIClub_InputClubName": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u041A\u043B\u0443\u0431\u0430",
