    "UIInfo_UploadHead": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 \u0430\u0432\u0430\u0442\u0430\u0440",
    "UIClub_WaitingApproval": "<color=#FF0000>\u0416\u0434\u0443 \u043E\u0442\u0437\u044B\u0432\u0430</color>",
