    "UIHappyShop_LotteryTime": "\u041E\u0441\u0442\u0430\u0432\u0448\u0435\u0435\u0441\u044F \u0432\u0440\u0435\u043C\u044F \u043B\u043E\u0442\u0435\u0440\u0435\u0438",
    "UIHappyShop_LotteryPeople": "\u041F\u0440\u0438\u043D\u044F\u043B\u043E \u0443\u0447\u0430\u0441\u0442\u0438\u0435 {0} \u0447\u0435\u043B\u043E\u0432\u0435\u043A",
    "UIClub_AuditRecords_search": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0432\u0432\u0435\u0434\u0438\u0442\u0435 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0438\u043B\u0438 \u0438\u0434\u0435\u043D\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u043E\u0440 \u041A\u043B\u0443\u0431\u0430",
