    "UIHappyShop_GetEntity": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043F\u0440\u0435\u0434\u043C\u0435\u0442\u044B",
    "UIHappyShop_GetChip": "\u041F\u043E\u0433\u0430\u0441\u0438\u0442\u044C UC",
    "UIHappyShop_GetEntityTips": "\u041F\u0440\u0435\u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u0442\u044C<color=#DDBA82>{0}</color>\u0432 UC, \u0432\u044B \u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C<color=#DDBA82>{1} UC</color>, \u0438 \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u044B\u0435 UC \u0431\u0443\u0434\u0443\u0442 \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u044B \u043D\u0435\u043F\u043E\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u043D\u0430 \u0432\u0430\u0448 \u0430\u043A\u043A\u0430\u0443\u043D\u0442",
    "UIClub_Dissolve": "\u0420\u0430\u0441\u0444\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u041A\u043B\u0443\u0431",
    "UIClub_DissolveTips": "\u041A\u043B\u0443\u0431 \u043D\u0435 \u043F\u043E\u0434\u043B\u0435\u0436\u0438\u0442 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044E \u043F\u043E\u0441\u043B\u0435 \u0435\u0433\u043E \u0440\u0430\u0441\u0444\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u044F, \u0430 \u0432\u0430\u0448\u0438 \u043F\u0440\u0430\u0432\u0430 \u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u044F \u041A\u043B\u0443\u0431\u0430 \u0442\u0430\u043A\u0436\u0435 \u0431\u0443\u0434\u0443\u0442 \u0443\u0442\u0440\u0430\u0447\u0435\u043D\u044B. \u041E\u0442\u043C\u0435\u043D\u0430, \u043F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0439\u0442\u0435 \u043E\u0441\u0442\u043E\u0440\u043E\u0436\u043D\u043E.",
    "UIClub_DissolveTips_Risk": "\u041F\u0440\u0435\u0434\u0443\u043F\u0440\u0435\u0436\u0434\u0435\u043D\u0438\u0435 \u043E \u0440\u0438\u0441\u043A\u0430\u0445",
    "UIClub_AuditRecords_ok": "\u041E\u0434\u043E\u0431\u0440\u0435\u043D\u043E",
    "UIClub_AuditRecords_no": "\u041E\u0442\u043A\u043B\u043E\u043D\u0435\u043D\u043D\u044B\u0439",
    "UIClub_CreateSuccessTips": "\u0422\u0435\u043A\u0443\u0449\u0438\u0439 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u044D\u0444\u0444\u0438\u0446\u0438\u0435\u043D\u0442 \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043F\u0440\u0438\u0431\u044B\u043B\u0438 \u0432\u0430\u0448\u0435\u0433\u043E \u041A\u043B\u0443\u0431\u0430 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442<size=60><color=#DDBA82>{0}%</color></size>\u3002",
