    "UIHappyShop_HasGiveState": "\u041D\u0430\u0433\u0440\u0430\u0434\u0430 \u0432\u044B\u0434\u0430\u043D\u0430",
    "MsgInfo_3014": "\u041F\u043E\u0437\u0434\u0440\u0430\u0432\u043B\u044F\u0435\u043C, \u0423\u0441\u043F\u0435\u0448\u043D\u043E \u0432\u044B\u043A\u0443\u043F\u0438\u043B \u043F\u0440\u0438\u0437 \u0437\u0430 \u043F\u043E\u043A\u0443\u043F\u043A\u0443 \u0432 \u0440\u0430\u0437\u043C\u0435\u0440\u0435 \u043E\u0434\u043D\u043E\u0433\u043E \u044E\u0430\u043D\u044F {0} \u0438 \u043F\u043E\u043B\u0443\u0447\u0438\u043B {1}.",
