    "WalletPlatform_Name": "\u0418\u043C\u044F",
    "UIMine_WalletPlatform_OnceAgainPix": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043F\u0438\u043A\u0441\u0435\u043B\u044C-\u043A\u043E\u0434 \u0435\u0449\u0435 \u0440\u0430\u0437",
