    "UIMatchCommonRoom": "\u0420\u0443\u043A\u043E\u0432\u043E\u0434\u0441\u0442\u0432\u043E \u0421\u0442\u043E\u043B",
    "UIMine_SettingPsdModePDVTip": "\u0422\u043E\u043B\u044C\u043A\u043E 1 \u0442\u0435\u0441\u0442\u043E\u0432 \u0432 \u0434\u0435\u043D\u044C",
    "UIMatchRandomJoinRoomTips1": "\u041D\u0430 \u0434\u0430\u043D\u043D\u044B\u0439 \u043C\u043E\u043C\u0435\u043D\u0442 \u043D\u0435\u0442 \u0421\u0442\u043E\u043B\u0430, \u043A \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u043C\u043E\u0436\u043D\u043E \u0431\u044B\u043B\u043E \u0431\u044B \u043F\u0440\u0438\u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0442\u044C\u0441\u044F.",
    "UIMushModeDepositRule": "\u0414\u0438\u043B\u0435\u0440 \u043A\u043B\u0430\u0434\u0435\u0442 \u043F\u043E \u043E\u0434\u043D\u043E\u043C\u0443 \u0433\u0440\u0438\u0431\u0443 (\u0444\u0438\u043A\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u0444\u0438\u0448\u043A\u0430) \u0432 \u0433\u0440\u0438\u0431\u043D\u043E\u0439 \u043F\u0443\u043B \u0432 \u043A\u0430\u0436\u0434\u043E\u0439 \u0440\u0430\u0437\u0434\u0430\u0447\u0435, \u0430 \u0438\u0433\u0440\u043E\u043A SB \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0431\u0430\u043D\u043A \u0438 \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0433\u0440\u0438\u0431\u043D\u043E\u0439 \u043F\u0443\u043B",
    "UITexasUnSendChat": "\u0412 \u0432\u044B\u0441\u0442\u0443\u043F\u043B\u0435\u043D\u0438\u0438 \u043C\u043E\u0433\u0443\u0442 \u0443\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u043E\u043A\u0438 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C",
