    "UITexasTableSetting_TrProfit": "\u0412\u043A\u043B\u0430\u0434 \u0434\u0436\u0435\u043A\u043F\u043E\u0442\u0430 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 {0}% \u043E\u0442 \u0441\u0443\u043C\u043C\u044B \u043F\u0440\u0438\u0431\u044B\u043B\u0438",
    "UICreateRoom_MaxWinRate": "\u041F\u0440\u0435\u0434\u0435\u043B \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F",
