    "UICreateRoom_ServiceMaxWinRate": "\u041A\u0435\u043F\u043A\u0430",
    "UICreateRoom_ServiceLowScoreRate": "\u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u0440\u0435\u0434\u0435\u043B \u0440\u0435\u0439\u043A\u0430 (\u043A\u0440\u0430\u0442\u043D\u044B\u0439 \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u043C\u0443 \u0431\u0430\u043B\u043B\u0443)",
