    "UIClubMemberProxyRevenueSettings_Jackpot": "\u0421\u043E\u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0435 \u0434\u043E\u043B\u0435\u0439 \u0434\u0436\u0435\u043A\u043F\u043E\u0442\u0430:",
