    "Mahjong_PongToKong": "\u041D\u0430\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0431\u0430\u0440",
    "UICreateTable_PrivateGame_Tips": "\u0427\u0435\u0440\u0435\u0437 \u043F\u0430\u0440\u043E\u043B\u044C \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438\u0433\u0440\u043E\u043A\u0430\u043C \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u0432\u0432\u0435\u0441\u0442\u0438 \u043F\u0430\u0440\u043E\u043B\u044C \u0434\u043B\u044F \u0432\u0445\u043E\u0434\u0430 \u0432 \u043A\u043E\u043C\u043D\u0430\u0442\u0443.",
    "UICreateTable_Deposit_Tips": "\u0421\u043E\u0431\u0435\u0440\u0438\u0442\u0435 \u0432 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u0441 \u0431\u0430\u0437\u043E\u0432\u043E\u0439 \u0441\u0442\u0430\u0432\u043A\u043E\u0439 * 170 \u0440\u0430\u0437 \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0435 \u043A\u0440\u0430\u0442\u043D\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435, \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u043C\u043E\u0436\u0435\u0442 \u0432\u043E\u0437\u043D\u0438\u043A\u043D\u0443\u0442\u044C \u0432 \u043A\u0430\u0436\u0434\u043E\u0439 \u0440\u0430\u0437\u0434\u0430\u0447\u0435",
    "UICreateTable_Anju_Tips": "\u041F\u043E\u0441\u043B\u0435 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u0421\u0442\u043E\u043B\u0430 \u0432\u0441\u0435\u043C \u043F\u043E\u0431\u0435\u0434\u0438\u0432\u0448\u0438\u043C \u0438\u0433\u0440\u043E\u043A\u0430\u043C \u0431\u0443\u0434\u0435\u0442 \u043D\u0430\u0447\u0438\u0441\u043B\u0435\u043D \u0440\u0435\u0439\u043A \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043F\u0440\u043E\u043F\u043E\u0440\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F",
    "UICreateTable_Anba_Tips": "\u041F\u043E\u0441\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0439 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u0441\u043E \u0432\u0441\u0435\u0445 \u0432\u044B\u0438\u0433\u0440\u0430\u0432\u0448\u0438\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0431\u0443\u0434\u0435\u0442 \u0432\u0437\u0438\u043C\u0430\u0442\u044C\u0441\u044F \u0440\u0435\u0439\u043A, \u043F\u0440\u043E\u043F\u043E\u0440\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0439 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044E \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u0440\u0435\u0434\u0435\u043B \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043D\u0435 \u0434\u043E\u043B\u0436\u0435\u043D \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u0442\u044C \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u043D\u043E\u0433\u043E \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F",
    "UICreateTable_GPS_Tips": "\u0418\u0433\u0440\u043E\u043A\u0430\u043C, \u0447\u044C\u0435 \u043C\u0435\u0441\u0442\u043E\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 GPS \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u0434\u0438\u0430\u043F\u0430\u0437\u043E\u043D\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0439 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0437\u0430 \u043E\u0434\u043D\u0438\u043C \u0441\u0442\u043E\u043B\u043E\u043C, \u0437\u0430\u043F\u0440\u0435\u0449\u0435\u043D\u043E \u0443\u0447\u0430\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C \u0432 \u0438\u0433\u0440\u0435",
