    "UIClubTalbe_CreditTips": "\u0414\u043E\u0441\u0442\u0443\u043F\u043D\u0430\u044F \u0441\u0443\u043C\u043C\u0430/\u0441\u0443\u043C\u043C\u0430 \u0431\u0435\u0437 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438",
