    "UITexasIns_InsAmount": "\u041F\u0440\u0435\u043C\u0438\u0443\u043C",
    "UICreateTable_InsTips": "1, \u041A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0421\u0442\u0440\u0430\u0445\u043E\u0432\u043A\u0430\\n\u041C\u0435\u0445\u0430\u043D\u0438\u0437\u043C \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044F \u0440\u0438\u0441\u043A\u043E\u0432 \u0432 \u0425\u043E\u043B\u0434\u0435\u043C\u0435, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0431\u0430\u043B\u0430\u043D\u0441\u0438\u0440\u0443\u0435\u0442 \u043A\u043E\u043B\u0435\u0431\u0430\u043D\u0438\u044F \u0438 \u0437\u0430\u0440\u0430\u043D\u0435\u0435 \u0444\u0438\u043A\u0441\u0438\u0440\u0443\u0435\u0442 \u0447\u0430\u0441\u0442\u044C \u043F\u0440\u0438\u0431\u044B\u043B\u0438. \u041A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0421\u0442\u0440\u0430\u0445\u043E\u0432\u043A\u0430 \u2013 \u0441\u0430\u043C\u0430\u044F \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u043E\u043D\u043D\u0430\u044F \u0438 \u0448\u0438\u0440\u043E\u043A\u043E \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0435\u043D\u043D\u0430\u044F \u0421\u0442\u0440\u0430\u0445\u043E\u0432\u043A\u0430.\\n2, \u043C\u0435\u0436\u0435\u043D\u044C \u0421\u0442\u0440\u0430\u0445\u043E\u0432\u043A\u0430\\n\u0412\u0435\u0434\u0443\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u0432 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0435\u043C \u0431\u0430\u043D\u043A\u0435 \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0434\u0430\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0443 \u043D\u0430 \u0441\u0442\u0440\u0430\u0445\u043E\u0432\u043A\u0443 \u043F\u043E\u0441\u043B\u0435 \u0410\u043B\u043B\u0438\u043D\u0430, \u0441\u0442\u0430\u0432\u043A\u0430 \u0421\u0442\u0440\u0430\u0445\u043E\u0432\u043A\u0438 \u0441 \u043D\u0438\u0437\u043A\u043E\u0439 \u0432\u043E\u0434\u043E\u0439 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 5%, \u0430 \u0448\u0430\u043D\u0441\u044B \u0432\u044B\u0448\u0435, \u0447\u0435\u043C \u0443 \u0442\u0440\u0430\u0434\u0438\u0446\u0438\u043E\u043D\u043D\u043E\u0439 \u0421\u0442\u0440\u0430\u0445\u043E\u0432\u043A\u0438. \u041F\u0435\u0440\u0432\u044B\u0439 \u0432 \u043E\u0442\u0440\u0430\u0441\u043B\u0438 \u0430\u043D\u0430\u043B\u043E\u0433: \u043F\u043E\u043A\u0443\u043F\u0430\u0439\u0442\u0435 \u043C\u0435\u043D\u044C\u0448\u0435, \u0442\u0435\u0440\u044F\u0439\u0442\u0435 \u0431\u043E\u043B\u044C\u0448\u0435.",
