    "UISquidGetDouble": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u0438",
    "UISquidGetDoubleTips": "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u0435 \u0440\u0430\u0437\u043D\u044B\u0445 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432, \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0445 \u0440\u0430\u0437\u043D\u044B\u043C \u043C\u043D\u043E\u0436\u0438\u0442\u0435\u043B\u044F\u043C",
    "UISquidEndReward": "\u041D\u0430\u0433\u0440\u0430\u0434\u044B!",
