    "UIMSGCreateNum": "\u041A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0445 \u0441\u0442\u043E\u043B\u043E\u0432",
    "UIMSGLongPressTips": "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u0438 \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0448\u0430\u0431\u043B\u043E\u043D, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0442\u0430\u0431\u043B\u0438\u0446 \u043E\u0434\u043D\u0438\u043C \u0449\u0435\u043B\u0447\u043A\u043E\u043C \u043C\u044B\u0448\u0438",
    "UICriticalHit_StartGameTips": "\u0414\u043E\u0431\u0440\u043E \u043F\u043E\u0436\u0430\u043B\u043E\u0432\u0430\u0442\u044C \u0432 Crit Poker\\n\u041A\u0430\u0436\u0434\u044B\u0435 {0} \u0440\u0430\u0437\u0434\u0430\u0447 \u043D\u0430 \u044D\u0442\u043E\u043C \u0441\u0442\u043E\u043B\u0435 \u0431\u0443\u0434\u0435\u0442 \u0438\u0433\u0440\u0430\u0442\u044C \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0438\u0433\u0440\u0430. \u0412\u0441\u0435\u043C \u0438\u0433\u0440\u043E\u043A\u0430\u043C \u043D\u0430 \u0421\u0442\u043E\u043B \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u0434\u0435\u043B\u0430\u0442\u044C \u0441\u0442\u0430\u0432\u043A\u0438",
    "UIPaiJu_WPKMode": "\u0421\u0443\u043F\u0435\u0440 \u0431\u044B\u0441\u0442\u0440\u044B\u0439 \u0442\u0435\u043C\u043F",
    "UICreateRoom_ChipsOutTips": "\u041C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0435 \u0437\u0430\u0440\u0435\u0437\u0435\u0440\u0432\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0444\u0438\u0448\u0435\u043A \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0435 \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0431\u0430\u0439-\u0438\u043D\u0430",
    "UIDialogSquid_BloodyPage1": "\u0414\u043E\u0431\u0440\u043E \u043F\u043E\u0436\u0430\u043B\u043E\u0432\u0430\u0442\u044C \u0432 \u0440\u0435\u0436\u0438\u043C \u043A\u0440\u043E\u0432\u0430\u0432\u043E\u0433\u043E \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u0430. \u0412 \u043A\u043E\u043D\u0446\u0435 \u043A\u0430\u0436\u0434\u043E\u0439 \u0438\u0433\u0440\u044B \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0433\u043E \u043F\u0443\u043B\u0430 \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u0430. \u0427\u0435\u043C \u0431\u043E\u043B\u044C\u0448\u0435 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432 \u0443 \u0438\u0433\u0440\u043E\u043A\u0430, \u0442\u0435\u043C \u0431\u043E\u043B\u044C\u0448\u0435 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0441\u0447\u0435\u0442\u043D\u044B\u0439 \u0431\u043E\u043D\u0443\u0441.",
    "UIDialogSquid_BloodyPage2": "\u0418\u0433\u0440\u043E\u043A, \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u0434\u043E\u0441\u0442\u0430\u043B\u0441\u044F \u043A\u0430\u043B\u044C\u043C\u0430\u0440, \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0432\u044B\u0439\u0442\u0438 \u0438\u0437 \u0438\u0433\u0440\u044B \u043D\u0430 \u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0435. \u0415\u0441\u043B\u0438 \u043E\u043D \u0432\u044B\u0439\u0434\u0435\u0442 \u0438\u0437 \u043A\u043E\u043C\u043D\u0430\u0442\u044B, \u043E\u043D \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u0432\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u043C \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0438 \u0434\u043E \u0442\u0435\u0445 \u043F\u043E\u0440, \u043F\u043E\u043A\u0430 \u043D\u0435 \u0432\u0435\u0440\u043D\u0435\u0442\u0441\u044F \u0432 \u0421\u0442\u043E\u043B \u0438\u043B\u0438 \u043F\u043E\u043A\u0430 \u043D\u0435 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0440\u0430\u0443\u043D\u0434 \u0438\u0433\u0440\u044B \u0441 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u0430\u043C\u0438. \u0418\u0433\u0440\u043E\u043A\u0438 \u0431\u0435\u0437 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432 \u0431\u0443\u0434\u0443\u0442 \u043D\u0430\u043A\u0430\u0437\u0430\u043D\u044B, \u0435\u0441\u043B\u0438 \u0443\u0439\u0434\u0443\u0442 \u043D\u0430 \u043F\u043E\u043B\u043F\u0443\u0442\u0438, \u0430 \u0448\u0442\u0440\u0430\u0444 \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D \u043C\u0435\u0436\u0434\u0443 \u0438\u0433\u0440\u043E\u043A\u0430\u043C\u0438 \u0441 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u0430\u043C\u0438 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0440\u0430\u0443\u043D\u0434\u0430 \u0441 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u0430\u043C\u0438.",
    "UIDialogSquid_BloodyPage3": "\u041A\u043E\u0433\u0434\u0430 \u0432\u0441\u0435 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u044B \u0431\u0443\u0434\u0443\u0442 \u0440\u043E\u0437\u0434\u0430\u043D\u044B \u0438\u043B\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0443 \u043E\u0434\u043D\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043D\u0435 \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432, \u0438\u0433\u0440\u0430 \u043F\u0435\u0440\u0435\u0439\u0434\u0435\u0442 \u0432 \u0440\u0435\u0436\u0438\u043C \u043F\u043E\u0441\u0435\u043B\u0435\u043D\u0438\u044F, \u0438 \u0438\u0433\u0440\u043E\u043A\u0430\u043C \u0431\u0435\u0437 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u0431\u0443\u0434\u0435\u0442 \u0432\u044B\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432\u044B\u0435 \u0431\u043E\u043D\u0443\u0441\u044B (\u043F\u043E\u0434\u0440\u043E\u0431\u043D\u0435\u0435 \u0441\u043C. \u0432 \u041F\u0440\u0430\u0432\u0438\u043B\u0430\u0445 \u0431\u043E\u043D\u0443\u0441\u043E\u0432)",
    "UIDialogSquid_NormalPage1": "\u0414\u043E\u0431\u0440\u043E \u043F\u043E\u0436\u0430\u043B\u043E\u0432\u0430\u0442\u044C \u0432 \u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u0435\u0436\u0438\u043C \u0438\u0433\u0440\u044B \u0432 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432. \u0412 \u043A\u043E\u043D\u0446\u0435 \u043A\u0430\u0436\u0434\u043E\u0439 \u0438\u0433\u0440\u044B \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0433\u043E \u043F\u0443\u043B\u0430 \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432, \u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u0447\u0435\u043B\u043E\u0432\u0435\u043A \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u043E\u0433\u043E \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u0430",
    "UIDialogSquid_BloodyTip": "\u041A\u0440\u043E\u0432\u0430\u0432\u0430\u044F \u0431\u0438\u0442\u0432\u0430 \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u043E\u0432",
