    "UICommon_HasBeenMute": "\u0417\u0430\u043F\u0440\u0435\u0449\u0435\u043D\u043E",
    "UICreateTable_PowerSavingTips": "\u0412\u043A\u043B.\u0420\u0435\u0436\u0438\u043C \u044D\u043D\u0435\u0440\u0433\u043E\u0441\u0431\u0435\u0440\u0435\u0436\u0435\u043D\u0438\u044F, \u0441\u043B\u043E\u0439 \u043C\u0430\u0441\u043A\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u0434\u043B\u044F \u0437\u0430\u043C\u0435\u043D\u044B \u0432\u0438\u0434\u0435\u043E\u044D\u0444\u0444\u0435\u043A\u0442\u043E\u0432 \u043D\u0430 \u0432\u0438\u0434\u0435\u043E \u043F\u043B\u0435\u0435\u0440\u0430 \u0432 \u0421\u0442\u043E\u043B",
    "UI_HasBeenMuteByAdmin": "\u0411\u044B\u043B \u0437\u0430\u0431\u0430\u043D\u0435\u043D \u0410\u0434\u043C\u0438\u043D\u043E\u043C, \u043E\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044C \u0432 \u0441\u043B\u0443\u0436\u0431\u0443 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0438",
