    "UIClub_LoadRecordFail": "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0440\u0443\u0447\u043D\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u0438 \u041E\u0448\u0438\u0431\u043A\u0430",
    "UIClub_DataError": "\u0410\u043D\u043E\u043C\u0430\u043B\u0438\u044F \u0434\u0430\u043D\u043D\u044B\u0445 \u0440\u0443\u043A",
    "UIClub_Of2": "\u041E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0441\u0432\u043E\u0439 \u043E\u0442\u0437\u044B\u0432 \u0437\u0434\u0435\u0441\u044C",
    "UIClub_Of3": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0441\u0432\u043E\u0439 \u043E\u0442\u0437\u044B\u0432 \u0437\u0434\u0435\u0441\u044C",
    "UIClub_Please3": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u043D\u0438\u0435 \u043E\u0442\u0437\u044B\u0432\u0430",
    "UIClub_Text60": "\u041E\u0431\u0440\u0430\u0442\u043D\u0430\u044F \u0441\u0432\u044F\u0437\u044C \u043F\u043E \u0438\u0433\u0440\u0435",
    "UIClub_Text61": "\u041A\u0430\u043C\u0435\u0440\u0430",
    "UIClub_AvatarFail": "\u041E\u0448\u0438\u0431\u043A\u0430 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438 \u0430\u0432\u0430\u0442\u0430\u0440\u0430",
    "UIClub_AvatarSaveFail": "\u0410\u0432\u0430\u0442\u0430\u0440 \u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C\u041E\u0448\u0438\u0431\u043A\u0430",
    "UIClub_AvatarDoneUpdate": "\u0410\u0432\u0430\u0442\u0430\u0440 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D",
    "UIClub_AvatarUpdateFail": "\u0410\u0432\u0430\u0442\u0430\u0440 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D \u041E\u0448\u0438\u0431\u043A\u0430",
    "UIClub_UpdateFail2": "\u041F\u043E\u043B \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D \u041E\u0448\u0438\u0431\u043A\u0430",
