    "UIClub_Can2": "\u041D\u0438\u043A\u043D\u0435\u0439\u043C \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D",
    "UIClub_SaveFail4": "\u041D\u0438\u043A\u043D\u0435\u0439\u043C \u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C\u041E\u0448\u0438\u0431\u043A\u0430",
    "UIClub_DoneSave3": "\u041F\u0441\u0435\u0432\u0434\u043E\u043D\u0438\u043C \u0431\u044B\u043B \u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C",
    "UIClub_Code": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043E\u0440\u0438\u0433\u0438\u043D\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u0430\u0440\u043E\u043B\u044C",
    "UIClub_Text65": "\u041F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u043B\u0438\u0447\u043D\u043E\u0441\u0442\u044C",
    "UIClub_Text66": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043F\u043E\u0434\u043E\u0436\u0434\u0438\u0442\u0435",
    "UIClub_Code2": "\u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0430\u0440\u043E\u043B\u044F \u0434\u043E\u0441\u0442\u0438\u0433\u0430\u0435\u0442",
    "UIClub_No8": "\u0410\u043A\u043A\u0430\u0443\u043D\u0442 \u0437\u0430\u043C\u043E\u0440\u043E\u0436\u0435\u043D",
    "UIClub_Text67": "\u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043A\u0430\u043A\u0438\u0435-\u043B\u0438\u0431\u043E \u0432\u043E\u043F\u0440\u043E\u0441\u044B, \u043E\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044C \u0432 \u0441\u043B\u0443\u0436\u0431\u0443 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0438 \u043A\u043B\u0438\u0435\u043D\u0442\u043E\u0432",
    "UIClub_Code3": "\u041D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u044B\u0439 \u043F\u0430\u0440\u043E\u043B\u044C",
    "UIClub_Can3": "\u0412\u044B \u0442\u0430\u043A\u0436\u0435 \u043C\u043E\u0436\u0435\u0442\u0435 \u043F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C",
    "UIClub_Text68": "\u0415\u0441\u043B\u0438 \u0432\u044B \u043F\u0440\u0435\u0432\u044B\u0441\u0438\u0442\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0440\u0430\u0437, \u0432\u044B \u0431\u0443\u0434\u0435\u0442\u0435 \u0437\u0430\u043C\u043E\u0440\u043E\u0436\u0435\u043D\u044B",
    "UIClub_CodeFail": "\u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u043F\u0430\u0440\u043E\u043B\u044F",
    "UIClub_Success4": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043B\u0438\u0447\u043D\u043E\u0441\u0442\u0438 \u0423\u0441\u043F\u0435\u0448\u043D\u043E",
    "UIClub_Code4": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u043D\u043E\u0432\u044B\u0439 \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u044B\u0439 \u043F\u0430\u0440\u043E\u043B\u044C",
    "UIClub_Code5": "\u0426\u0438\u0444\u0440\u043E\u0432\u043E\u0439 \u043F\u0430\u0440\u043E\u043B\u044C",
    "UIClub_Code6": "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043F\u0430\u0440\u043E\u043B\u044F",
    "UIClub_Again3": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0435\u0449\u0435 \u0440\u0430\u0437 \u0434\u043B\u044F \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F",
    "UIClub_Text69": "\u0414\u0432\u0430 \u0432\u0445\u043E\u0434\u0430 \u043D\u0435\u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B",
    "UIClub_Text70": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0435\u0449\u0435 \u0440\u0430\u0437 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438",
    "UIClub_CodeFail2": "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438\u041D\u0430\u0434\u0435\u0436\u043D\u044B\u0439 \u043F\u0430\u0440\u043E\u043B\u044C \u041E\u0448\u0438\u0431\u043A\u0430",
    "UIClub_CodeSuccess": "\u041F\u0430\u0440\u043E\u043B\u044C \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E\u0441\u0442\u0438 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438\u0423\u0441\u043F\u0435\u0448\u043D\u043E",
    "UIClub_Code7": "\u0421\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u043F\u0430\u0440\u043E\u043B\u044C",
