    "UIClub_Text73": "\u0421\u0442\u0440\u043E\u043A\u0430 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E",
    "UIClub_InDeve4": "\u0424\u0443\u043D\u043A\u0446\u0438\u044F \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u044F \u043B\u0438\u043D\u0438\u0439 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u0440\u0430\u0437\u0440\u0430\u0431\u043E\u0442\u043A\u0435",
    "UIClub_DoneExit": "\u0412\u044B\u0448\u0435\u043B \u0412\u043E\u0439\u0442\u0438",
    "UIClub_No11": "\u0422\u043E\u0432\u0430\u0440\u043E\u0432 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442",
    "UIClub_Copy": "\u0421\u043A\u043E\u043F\u0438\u0440\u0443\u0439\u0442\u0435 \u0430\u0434\u0440\u0435\u0441 \u041A\u043E\u0448\u0435\u043B\u0451\u043A \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0430",
    "UIClub_CopyCoin": "\u0421\u043A\u043E\u043F\u0438\u0440\u0443\u0439\u0442\u0435 \u0430\u0434\u0440\u0435\u0441 \u041A\u043E\u0448\u0435\u043B\u0451\u043A, \u0443\u043A\u0430\u0437\u0430\u043D\u043D\u044B\u0439 \u0432\u044B\u0448\u0435, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0443",
    "UIClub_OrCode": "\u0418\u043B\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u041A\u043E\u0448\u0435\u043B\u0451\u043A, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u0441\u043A\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u0442\u044C QR-\u043A\u043E\u0434 \u0434\u043B\u044F \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u043E\u043F\u043B\u0430\u0442\u044B",
    "UIClub_Text74": "\u041F\u043E\u043A\u0443\u043F\u043A\u0430 \u0410\u043B\u043C\u0430\u0437\u044B",
    "UIClub_Text75": "\u0410\u043A\u043A\u0430\u0443\u043D\u0442 \u0410\u043B\u043C\u0430\u0437\u044B",
    "UIClub_Text76": "\u0421\u043E\u0437\u0434\u0430\u043D\u0438\u0435 \u0437\u0430\u043A\u0430\u0437\u0430",
    "UIClub_Text77": "\u0417\u0430\u043F\u0440\u043E\u0441",
    "UIClub_Apply": "\u0420\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u043E\u043D\u043D\u044B\u0439 \u0432\u0437\u043D\u043E\u0441 \u0434\u043B\u044F \u043E\u043F\u0442\u043E\u0432\u0438\u043A\u0430 \xAB\u0410\u043B\u043C\u0430\u0437\u044B\xBB \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442",
    "UIClub_Text78": "\u0438 \u0431\u0443\u0434\u0435\u0442 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0435\u043D\u0430, \u0435\u0441\u043B\u0438 \u043E\u0442\u0437\u044B\u0432 \u0431\u0443\u0434\u0435\u0442 \u043E\u0442\u043A\u043B\u043E\u043D\u0435\u043D.",
    "UIClub_Apply2": "\u041F\u043E\u0441\u043B\u0435 \u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u044F \u0437\u0430\u044F\u0432\u043A\u0438",
    "UIClub_Text79": "\u041D\u0443\u0436\u043D\u043E \u0437\u0430",
    "UIClub_Text80": "\u0434\u043D\u0438",
    "UIClub_Text81": "\u0412 \u043F\u0440\u043E\u0442\u0438\u0432\u043D\u043E\u043C \u0441\u043B\u0443\u0447\u0430\u0435 \u043A\u0432\u0430\u043B\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u044F \u0431\u0443\u0434\u0435\u0442 \u043D\u0435\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439",
    "UIClub_Or": "\u0415\u0441\u043B\u0438 \u043A\u0432\u0430\u043B\u0438\u0444\u0438\u043A\u0430\u0446\u0438\u044F \u043E\u043F\u0442\u043E\u0432\u0438\u043A\u0430 \u043D\u0435\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u0430 \u0438\u043B\u0438 \u043E\u0434\u043E\u0431\u0440\u0435\u043D\u0438\u0435 \u043E\u0442\u043A\u043B\u043E\u043D\u0435\u043D\u043E, \u0432\u0430\u043C \u043F\u0440\u0438\u0434\u0435\u0442\u0441\u044F \u0437\u0430\u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0435\u0449\u0435 \u0440\u0430\u0437",
    "UIClub_Apply3": "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0410\u043B\u043C\u0430\u0437\u044B",
    "UIClub_Apply4": "\u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u0438\u043C\u0435\u043D\u0435\u043D\u0438\u044F",
    "UIClub_Text82": "\u041C\u044B \u0441\u0432\u044F\u0436\u0435\u043C\u0441\u044F \u0441 \u0432\u0430\u043C\u0438 \u0447\u0435\u0440\u0435\u0437 \u0441\u0438\u0441\u0442\u0435\u043C\u0443 \u0421\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F",
    "UIClub_Text83": "\u041E\u0431\u0440\u0430\u0442\u0438\u0442\u0435 \u0432\u043D\u0438\u043C\u0430\u043D\u0438\u0435 \u043D\u0430 \u0421\u043E\u043E\u0431\u0449\u0435\u043D\u0438\u044F",
    "UIClub_Text84": "\u041F\u043B\u0430\u0442\u0438\u0442\u044C",
