    "UILanding_Text6": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043D\u0430\u0439\u0434\u0438\u0442\u0435 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u043E\u0444\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u0430\u043D\u0430\u043B \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438",
    "UILanding_Text7": "\u041E\u0441\u0442\u0435\u0440\u0435\u0433\u0430\u0439\u0442\u0435\u0441\u044C \u0441\u0442\u043E\u0440\u043E\u043D\u043D\u0438\u0445 \u043F\u0438\u0440\u0430\u0442\u0441\u043A\u0438\u0445 \u0441\u0441\u044B\u043B\u043E\u043A",
    "UILanding_Table": "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u044F\u0440\u043B\u044B\u043A\u0438 \u043D\u0430 \u0440\u0430\u0431\u043E\u0447\u0438\u0439 \u0441\u0442\u043E\u043B",
    "UILanding_Text8": "\u0413\u043B\u043E\u0431\u0430\u043B\u044C\u043D\u0430\u044F \u043F\u043B\u0430\u0442\u0444\u043E\u0440\u043C\u0430 \u043F\u043E\u0434\u043B\u0438\u043D\u043D\u043E\u0433\u043E \u0445\u043E\u043B\u0434\u0435\u043C\u0430",
    "UILanding_Text9": "\u0411\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E \u0438 \u0447\u0435\u0441\u0442\u043D\u043E",
    "UILanding_Text10": "\u041D\u0430\u0441\u043B\u0430\u0436\u0434\u0430\u0439\u0442\u0435\u0441\u044C \u0438\u0433\u0440\u043E\u0439",
    "UILanding_Round2": "\u041E\u0445\u0440\u0430\u043D\u044F\u0439\u0442\u0435 \u0438\u0433\u0440\u0443 \u043A\u0430\u0436\u0434\u044B\u0439 \u0447\u0430\u0441",
    "UILanding_Text11": "\u0423\u043F\u043E\u0440\u043D\u043E \u0431\u043E\u0440\u0438\u0442\u0435\u0441\u044C \u0441 \u0431\u0430\u043D\u0434\u0430\u043C\u0438 \u0438 \u043C\u043E\u0448\u0435\u043D\u043D\u0438\u0447\u0435\u0441\u0442\u0432\u043E\u043C",
    "UILanding_Table2": "\u0421\u0442\u043E\u043B \u0434\u0440\u0443\u0437\u0435\u0439",
    "UILanding_Text12": "\u041A\u043E\u043C\u043D\u0430\u0442\u0430, \u043F\u043E\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u0430\u044F \u0441\u0432\u043E\u0438\u043C\u0438 \u0440\u0443\u043A\u0430\u043C\u0438",
    "UILanding_Text13": "\u0413\u0438\u0431\u043A\u0438\u0435 \u043F\u0440\u0430\u0432\u0438\u043B\u0430",
    "UILanding_AndRound": "\u0413\u0440\u0443\u043F\u043F\u043E\u0432\u044B\u0435 \u0438\u0433\u0440\u044B \u0441 \u0434\u0440\u0443\u0437\u044C\u044F\u043C\u0438 \u0432 \u043B\u044E\u0431\u043E\u0435 \u0432\u0440\u0435\u043C\u044F",
    "UILanding_Jackpot": "\u0421\u0432\u0435\u0440\u0445\u0432\u044B\u0441\u043E\u043A\u0438\u0439 \u043F\u0440\u0438\u0437\u043E\u0432\u043E\u0439 \u0444\u043E\u043D\u0434 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043E\u0432\u0430\u0442\u044C",
    "UILanding_Text14": "\u0427\u0435\u0441\u0442\u043D\u0430\u044F \u043A\u043E\u043D\u043A\u0443\u0440\u0435\u043D\u0446\u0438\u044F",
    "UILanding_Text15": "\u0423\u043B\u044C\u0442\u0440\u0430\u0441\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u0433\u0435\u0439\u043C\u043F\u043B\u0435\u0439",
    "UILanding_Text16": "\u041F\u043E\u043B\u043D\u044B\u0439 \u043A\u0430\u043B\u044C\u043C\u0430\u0440",
    "UILanding_Text17": "\u041F\u0435\u0440\u0432\u044B\u0439 \u0432\u044B\u043F\u0443\u0441\u043A \u043F\u043E\u043F\u0443\u043B\u044F\u0440\u043D\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u0432\u043E\u0433\u043E \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u0430, \u0442\u0430\u043A\u043E\u0433\u043E \u043A\u0430\u043A Thirteen Waters",
    "UILanding_Not": "\u0410\u0434\u0440\u0435\u0441 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438 \u0435\u0449\u0435 \u043D\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043D",
    "UILanding_DoneTable": "\u0423\u0436\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043E \u043D\u0430 \u0440\u0430\u0431\u043E\u0447\u0438\u0439 \u0441\u0442\u043E\u043B",
    "UILanding_Text18": "\u041F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0430 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043E\u0447\u043D\u044B\u0445 \u0444\u0430\u0439\u043B\u043E\u0432",
    "UILanding_Done": "\u0424\u0430\u0439\u043B \u0441 \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u0435\u043C \u0441\u043A\u0430\u0447\u0430\u043D.",
    "UILanding_Text19": "\u043F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043F\u0440\u0438\u0434\u0438",
    "UILanding_Text20": "\u0423\u043D\u0438\u0432\u0435\u0440\u0441\u0430\u043B\u044C\u043D\u044B\u0439",
    "UILanding_Text21": "\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u043C\u0438",
    "UILanding_Text22": "\u041F\u043E\u043B\u043D\u0430\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430",
    "UILanding_Fail": "\u0413\u0435\u043D\u0435\u0440\u0430\u0446\u0438\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043E\u0447\u043D\u043E\u0433\u043E \u0444\u0430\u0439\u043B\u0430 \u041E\u0448\u0438\u0431\u043A\u0430",
    "UILanding_Text23": "\u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u0437\u0436\u0435",
    "UILanding_Text24": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435",
    "UILanding_Again": "\u041E\u0442\u043A\u0440\u044B\u0432 \u044D\u0442\u0443 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443, \u043D\u0430\u0436\u043C\u0438\u0442\u0435",
    "UILanding_Text25": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043D\u0430 \u0432\u0435\u0440\u0445\u043D\u0438\u0439 \u043F\u0440\u0430\u0432\u044B\u0439 \u0443\u0433\u043E\u043B",
    "UILanding_Text26": "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435",
    "UILanding_Text27": "\u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u0434\u043E\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435",
    "UILanding_Text28": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043A\u043D\u043E\u043F\u043A\u0443 \xAB\u041F\u043E\u0434\u0435\u043B\u0438\u0442\u044C\u0441\u044F\xBB \u0432\u043D\u0438\u0437\u0443",
    "UILanding_Text29": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435",
    "UILanding_Text30": "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u043D\u0430 \u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u044D\u043A\u0440\u0430\u043D",
    "UILanding_Text31": "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0432 \u043C\u0435\u043D\u044E \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430",
