    "UIMTT_EnterTable": "\u041F\u0440\u0438\u0433\u043E\u0442\u043E\u0432\u044C\u0442\u0435\u0441\u044C \u0432\u043E\u0439\u0442\u0438 \u0432 \u0421\u0442\u043E\u043B",
