    "UITable_AllowCode": "\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u043C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0444\u0438\u0448\u0435\u043A",
    "UITable_BuyIn": "\u041B\u0438\u043C\u0438\u0442 \u043F\u043E\u043A\u0443\u043F\u043A\u0438 \u0444\u0438\u0448\u0435\u043A",
    "UITable_Text10": "\u0413\u0430\u043B\u0441\u0442\u0443\u043A",
    "UITable_Text11": "\u0417\u0430\u043C\u0435\u043D\u0438\u0442\u044C \u0447\u0438\u043F\u044B",
    "UITable_Code": "\u041C\u0438\u043D\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0435 \u0437\u0430\u0440\u0435\u0437\u0435\u0440\u0432\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0444\u0438\u0448\u043A\u0438",
    "UITable_Code2": "\u041C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0437\u0430\u0440\u0435\u0437\u0435\u0440\u0432\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0445 \u0444\u0438\u0448\u0435\u043A",
    "UITable_Text12": "\u041D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u0432\u0441\u0435",
    "UITable_Text13": "\u041F\u0440\u0438\u043D\u0443\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0432\u044B\u0431\u043E\u0440 \u0432\u0441\u0435\u0445",
    "UITable_Text14": "\u0440\u0435\u0436\u0438\u043C \u043A\u0430\u043B\u044C\u043C\u0430\u0440\u0430",
