    "UICreateTableSquidModeSingleToggle": "\u0E1B\u0E25\u0E32\u0E2B\u0E21\u0E36\u0E01\u0E15\u0E31\u0E27\u0E40\u0E14\u0E35\u0E22\u0E27",
