    "UINiuZaiXiaZhuQu_content01": "1.\u52DD\u8CA0\u5E73\u5340\u57DF:\u725B\u4ED4\u52DD\u3001\u5E73\u624B\u3001\u516C\u725B\u52DD;",
    "UINiuZaiXiaZhuQu_content02": "2.\u4EFB\u4E00\u4EBA\u624B\u724C\u5340\u57DF:\u540C\u82B1/\u9023\u724C/\u540C\u82B1\u9023\u724C\u3001\u5C0D\u5B50\u5C0DA;",
    "UINiuZaiXiaZhuQu_content03": "3.\u7372\u52DD\u724C\u578B\u5340\u57DF:\u9AD8\u724C/\u4E00\u5C0D\u3001\u5169\u5C0D\u3001\u4E09\u689D/\u9806\u5B50\u540C\u82B1\u3001\u846B\u8606\u3001\u91D1\u525B/\u540C\u82B1\u9806/\u7687\u540C",
    "UINiuZai_high_one": "\u9AD8\u724C/\u4E00\u5C0D",
    "UINiuZaiXiaZhuQu_content04": "\u7687\u540C",
    "UINiuZaiInsurance_titleTwo": "\u724C\u578B\u5927\u5C0F[\u4E0D\u5206\u82B1\u8272]",
    "UINiuZaiXiaZhuQu_content05": "1.\u724C\u578B:\u7687\u540C>\u540C\u82B1\u9806>\u56DB\u689D>\u846B\u8606>\u540C\u82B1>\u9806\u5B50>\u4E09\u689D>\u5169\u5C0D>\u5C0D\u5B50>",
    "UINiuZaiXiaZhuQu_content06": "\u9AD8\u724C;",
    "UINiuZaiXiaZhuQu_content07": "2.\u55AE\u724C:A>K>Q>J>10>9>8>7>6>5>4>3>2;",
    "UINiuZaiXiaZhuQu_content08": "3.\u76F8\u540C\u724C\u578B:\u512A\u5148\u6BD4\u8F03\u6700\u5927\u55AE\u724C,\u76F8\u540C\u5247\u4F9D\u6B21\u5411\u4E0B\u7E7C\u7E8C\u6BD4\u8F03,\u59825\u5F35",
    "UINiuZaiXiaZhuQu_content09": "\u724C\u76F8\u540C,\u5247\u70BA\u5E73\u5C40;",
    "UINiuZaiInsurance_titleThree": "\u7206\u838A\u898F\u5247",
    "UINiuZaiXiaZhuQu_content011": "\u838A\u5BB6\u5269\u9918\u7C4C\u78BC\u4E0D\u8DB3\u4EE5\u8CE0\u4ED8\u6240\u6709\u7372\u52DD\u73A9\u5BB6\u7684\u8CE0\u4ED8\u91CF\u6642,\u838A\u5BB6\u6240\u5269",
    "UINiuZaiXiaZhuQu_content012": "\u9918\u7684\u8A18\u5206\u5C07\u6309\u6BD4\u4F8B\u5168\u90E8\u5206\u914D\u7D66\u7372\u52DD\u73A9\u5BB6,\u4E26\u5728\u7D50\u7B97\u7D50\u675F\u5F8C\u95DC\u9589\u623F",
