    "UIDelayTips6": "\u724C\u5C40\u5EF6\u9072{0}H\u6210\u529F",
    "UIDelayTableApply": "\u5EF6\u6642\u7533\u8ACB",
    "UIFantasy_Introduce": "\u5E38\u898F\u73A9\u6CD5\u898F\u5247\uFF1A\\n1\u3001\u958B\u5C40\u6BCF\u4EBA\u767C7\u5F35\u624B\u724C\\n2\u30012/2/2\u5206\u7D44\uFF0C\u7136\u5F8C\u5C07\u591A\u9918\u76841\u5F35\u68C4\u6389\uFF0C\u4E14\u201C\u78BA\u5B9A\u201D\u5F8C\uFF0C\u4E0D\u80FD\u518D\u6B21\u66F4\u6539\u5206\u7D44\\n3\u3001\u540C\u6642\u767C\u653E\u7B2C1\u9053Flop\uFF0C\u7B2C2\u9053Flop\uFF0C\u7B2C3\u9053Flop 3*3 \u4E00\u51719\u5F35\u516C\u5171\u724C\uFF08\u660E\u724C\uFF09\u3002\\n4\u3001\u518D\u628A2/2/2\u5206\u7D44\u5F8C\u76843\u7D44\u624B\u724C\u6392\u6392\u5E8F\u53BB\u5C0D\u61C9 123\u9053\u516C\u5171\u724C\uFF0C3\u7D44\u90FD\u5339\u914D\u5C0D\u61C9\u78BA\u8A8D\u5F8C\u4E0D\u53EF\u66F4\u6539\u3002\\n5\u3001\u6309\u7167\u4E4B\u524D\u7684\u9806\u5E8F\uFF0C\u767C1\uFF0C2\uFF0C3\u9053turn\uFF08\u6697\u724C\uFF09\uFF0C\u518D\u767C1\uFF0C2\uFF0C3\u9053river\uFF08\u6697\u724C\uFF09\u3002\\n6.\u3001\u73A9\u5BB6\u4EAE \u7B2C\u4E00\u9053\u7684\u5E95\u724C, \u4EAEturn\u7684\u7B2C\u4E00\u9053\u516C\u5171\u724C, \u4EAEriver\u7684\u7B2C\u4E00\u9053\u516C\u5171\u724C, \u6BD4\u724C(\u5C55\u793A\u90E8\u5206\u7D50\u679C) \u3002\\n7\u3001\u73A9\u5BB6\u4EAE \u7B2C\u4E8C\u9053\u7684\u5E95\u724C, \u4EAEturn\u7684\u7B2C\u4E8C\u9053\u516C\u5171\u724C, \u4EAEriver\u7684\u7B2C\u4E8C\u9053\u516C\u5171\u724C, \u6BD4\u724C(\u5C55\u793A\u90E8\u5206\u7D50\u679C) \u3002\\n8\u3001 \u73A9\u5BB6\u4EAE \u7B2C\u4E09\u9053\u7684\u5E95\u724C, \u4EAEturn\u7684\u7B2C\u4E09\u9053\u516C\u5171\u724C, \u4EAEriver\u7684\u7B2C\u4E09\u9053\u516C\u5171\u724C, \u6BD4\u724C(\u5C55\u793A\u90E8\u5206\u7D50\u679C) \u3002\\n9\u3001\u532F\u7E3D\u6240\u6709\u6BD4\u724C\u7D50\u679C,\u51FA\u6700\u7D42\u7D50\u679C\u8A08\u7B97bonus\u7D50\u7B97\u734E\u52F5\uFF0C\u9032\u5165\u4E0B\u4E00\u8F2A\u3002\\n\\nToroFlops\u7279\u6B8A\u898F\u5247\uFF1A\\n1\u3001\u7576\u73A9\u5BB6\u57283\u7D44\u724C\u4E2D\uFF0C\u4EFB\u610F\u4E00\u7D44\u62FF\u5230full house\uFF08\u846B\u8606\uFF09\uFF0C\u4E14\u662F\u75313\u5F35J/Q/K/A\u7D44\u6210\u7684\uFF0C\u4E0B\u4E00\u8F2A\u9032\u5165Fantasy\u3002\\n2\u3001\u9032\u5165Fantasy\u7684\u73A9\u5BB6\u6709\u660E\u986F\u7684\u8996\u89BA\u6FC0\u52F5\u3002\\n3\u3001\u9032\u5165Fantasy\u7684\u73A9\u5BB6\uFF0C\u624B\u724C\u75317\u5F35\u8B8A\u70BA12\u5F35\uFF0C\u4E14\u4E0D\u9700\u8981\u5206\u7D44\uFF0C\u975EFantasy\u7684\u73A9\u5BB6\u548C\u666E\u901A\u898F\u5247\u4E00\u6A23\u9700\u8981\u6B63\u5E38 2/2/2 \u5206\u7D44\u3002\\n4\u3001\u9032\u5165Fantasy\u7684\u73A9\u5BB6\uFF0C\u57283\u9053Flop\u516C\u5171\u724C\u767C\u5B8C\u5F8C\uFF0C\u76F4\u63A5\u572812\u5F35\u624B\u724C\u88CF\u9078\u64C7\u5176\u4E2D6\u5F35 2/2/2 \u5C0D\u61C91\u30012\u30013\u9053Flop\u516C\u724C\u5339\u914D\uFF0C\u975EFantasy\u7684\u73A9\u5BB6\u548C\u666E\u901A\u898F\u5247\u4E00\u6A23\u6B63\u5E38\u5339\u5C0D\u3002\\n5\u3001\u5339\u5C0D\u5F8C\u6309\u7167\u666E\u901A\u898F\u5247\u9032\u884C\uFF0C\u767C1\uFF0C2\uFF0C3\u9053turn\uFF08\u6697\u724C\uFF09\uFF0C\u518D\u767C1\uFF0C2\uFF0C3\u9053river\uFF08\u6697\u724C\uFF09\uFF0C\u7136\u5F8C\u4F9D\u6B21\u4EAE\u724C\uFF0C\u6BD4\u724C\u3002\\n6\u3001\u532F\u7E3D\u6240\u6709\u6BD4\u724C\u7D50\u679C\u7D50\u7B97\u734E\u52F5\u3002\u9032\u5165\u4E0B\u4E00\u8F2A\u3002",
    "UIFantasy_scoring": "\u8A08\u5206\u7D71\u8A08",
    "UIFantasy_Introduce2": "\u8A18\u5206\u898F\u5247\\n1\u30012\u4EBA\u6642\u76F4\u63A5\u9032\u884C\u6BD4\u8F03\uFF1B3\u4EBA\u6642\u9032\u884C\u5169\u5169\u6BD4\u8F03\uFF0C\u6700\u5F8C\u53D6\u548C\uFF0C\u8A08\u7B97\u5206\u503C\u3002\\n2\u3001\u8A08\u5206\u7E3D\u503C=\u724C\u578B\u5206\u5DEE+\u52DD\u8CA0\u9EDE\u6578+\u5168\u5C40\u984D\u5916\u9EDE\u6578\\n3\u3001\u724C\u578B\u5206\u503C\u5982\u4E0B\uFF0C\u62FF\u5230\u6307\u5B9A\u724C\u578B\u7372\u5F97\u76F8\u61C9\u7684\u724C\u578B\u5206",
