    "Mahjong_RuleTitle1": "\u57FA\u790E\u73A9\u6CD5",
    "Mahjong_RuleContent1_1": "\u56DB\u5DDD\u9EBB\u5C07\u4F7F\u7528\u4E0D\u5305\u542B\u5B57\u724C\uFF08\u5373\u6C92\u6709\u6771\u3001\u5357\u3001\u897F\u3001\u5317\u3001\u4E2D\u3001\u767C\u3001\u767D\uFF09\u7684108\u5F35\u724C\uFF0C\u53EA\u5305\u62EC1-9\u842C\u30011-9\u7B52\u30011-9\u689D\u4E09\u8272\u5E8F\u6578\u724C\u540436\u5F35",
    "Mahjong_RuleContent1_2": "\u64F2\u9AB0\u5B50\u78BA\u5B9A\u838A\u5BB6\uFF0C\u5F8C\u7E8C\u7531\u80E1\u724C\u8005\u5750\u838A\uFF0C\u4E00\u70AE\u591A\u97FF\u5247\u653E\u70AE\u8005\u70BA\u838A\uFF0C\u5982\u679C\u6D41\u5C40\u5247\u838A\u5BB6\u9023\u838A",
    "Mahjong_RuleContent1_3": "\u6BCF\u540D\u73A9\u5BB6\u8D77\u624B\u629313\u5F35\u724C\uFF0C\u838A\u5BB6\u591A\u4E00\u5F35\u70BA14\u5F35",
    "Mahjong_RuleContent1_4": "\u53EF\u78B0\u3001\u53EF\u69D3\uFF0C\u4E0D\u53EF\u5403",
    "Mahjong_RuleTitle2": "\u80E1\u724C\u898F\u5247",
    "Mahjong_RuleContent2_1": "\u53EF\u9EDE\u70AE\u80E1\uFF0C\u6436\u69D3\u80E1\uFF0C\u652F\u6301\u4E00\u70AE\u591A\u97FF\u3002 \u5FC5\u9808\u7F3A\u9580\uFF0C\u5728\u8840\u6230\u5230\u5E95\u4E2D\uFF0C\u73A9\u5BB6\u5FC5\u9808\u201C\u7F3A\u4E00\u9580\u201D\uFF0C\u5373\u4E0D\u80FD\u6709\u67D0\u4E00\u9580\u82B1\u8272\u7684\u724C\uFF0C\u78BA\u4FDD\u80E1\u724C\u6642\u624B\u4E0A\u53EA\u5269\u4E0B\u5169\u9580\u82B1\u8272",
    "Mahjong_RuleContent2_2": "\u5728\u8840\u6230\u5230\u5E95\u6A21\u5F0F\u4E0B\uFF0C\u4E00\u5BB6\u80E1\u724C\u5F8C\uFF0C\u5269\u9918\u73A9\u5BB6\u7E7C\u7E8C\u904A\u6232\uFF0C\u76F4\u5230\u4E09\u5BB6\u80E1\u724C\u6216\u8005\u6D41\u5C40\u70BA\u6B62\u3002 \u80E1\u724C\u8005\u6536\u53D6\u9EDE\u70AE\u8005\u7684\u5206\u6578\uFF0C\u81EA\u6478\u5247\u5176\u4ED6\u4E09\u5BB6\u5747\u652F\u4ED8\uFF0C\u5DF2\u7D93\u80E1\u724C\u7684\u73A9\u5BB6\u4E0D\u5728\u53C3\u8207\u724C\u5C40\uFF0C\u53EF\u4EE5\u81EA\u7531\u96E2\u958B\u3002",
    "Mahjong_RuleTitle3": "\u63DB\u4E09\u5F35",
    "Mahjong_RuleContent3_1": "\u767C\u5B8C\u624B\u724C\u5F8C\uFF0C\u6BCF\u4F4D\u73A9\u5BB6\u9078\u64C73\u5F35\u540C\u82B1\u8272\u7684\u724C\uFF0C\u96A8\u6A5F\u8207\u5176\u5B831\u6BD4\u7279\u73A9\u5BB6\u4EA4\u63DB\uFF1B",
    "Mahjong_RuleContent3_2": "\u63DB\u4E09\u5F35\u662F\u5176\u4E2D\u7684\u4E00\u500B\u73A9\u6CD5\uFF0C\u53EF\u9078\u64C7\u548C\u4E0D\u9078\u64C7\u9019\u500B\u6A21\u5F0F",
    "Mahjong_RuleContent3_3": "\u63DB\u4E09\u5F35\u89F8\u767C\u597D\u724C\u76F4\u63A5\u8DF3\u904E\u63DB\u4E09\u5F35\uFF0C\u89F8\u767C\u689D\u4EF6\u70BA\u5176\u4E2D2\u500B\u82B1\u8272\u724C\u578B\u5C11\u65BC3\u5F35\uFF1B",
    "Mahjong_RuleTitle4": "\u7F3A\u4E00\u9580",
    "Mahjong_RuleContent4_1": "\u767C\u5B8C\u624B\u724C\u5F8C\uFF0C\u73A9\u5BB6\u9700\u8981\u901A\u904E\u8D77\u624B\u724C\u6C7A\u5B9A\u4E26\u6253\u51FA\u4E00\u7A2E\u82B1\u8272\uFF08\u7B52\u3001\u689D\u3001\u842C\uFF09\u7684\u724C\u4F5C\u70BA\u201C\u7F3A\u201D\uFF0C\u610F\u5473\u8457\u5728\u6574\u500B\u904A\u6232\u904E\u7A0B\u4E2D\uFF0C\u73A9\u5BB6\u5FC5\u9808\u6368\u68C4\u8A72\u9580\u82B1\u8272\u7684\u6240\u6709\u724C\uFF0C\u53EA\u7528\u5269\u4E0B\u7684\u5169\u9580\u82B1\u8272\u4F86\u7D44\u5408\u80E1\u724C\uFF1B",
    "Mahjong_RuleContent4_2": "\u9019\u500B\u5728\u80E1\u724C\u4EE5\u53CA\u6478\u5B8C\u6240\u6709\u624B\u724C\u524D\u662F\u53EF\u4EE5\u96A8\u610F\u8ABF\u6574\u7684\uFF0C\u548C\u201C\u5B9A\u7F3A\u201D\u4E0D\u4E00\u6A23",
    "Mahjong_RuleTitle5": "\u5B9A\u7F3A",
    "Mahjong_RuleContent5_1": "\u767C\u5B8C\u624B\u724C\u5F8C\u9078\u64C7\u4E00\u9580\u4E0D\u8981\u7684\u82B1\u8272\u5373\u70BA\u5B9A\u7F3A\uFF0C\u6478\u5230\u5B9A\u7F3A\u7684\u9019\u9580\u82B1\u8272\u7684\u724C\u4E00\u5B9A\u8981\u6253\u51FA\uFF0C\u5C0D\u5C40\u4E2D\u4E0D\u53EF\u66F4\u6539\u5B9A\u7F3A\u3002",
