    "UINiuZaiXiaZhuQu_content04": "\u7687\u540C",
    "UINiuZaiInsurance_titleTwo": "\u724C\u578B\u5927\u5C0F[\u4E0D\u5206\u82B1\u8272]",
    "UINiuZaiXiaZhuQu_content05": "1.\u724C\u578B:\u7687\u540C>\u540C\u82B1\u987A>\u56DB\u6761>\u846B\u82A6>\u540C\u82B1>\u987A\u5B50>\u4E09\u6761>\u4E24\u5BF9>\u5BF9\u5B50>",
    "UINiuZaiXiaZhuQu_content06": "\u9AD8\u724C;",
    "UINiuZaiXiaZhuQu_content07": "2.\u5355\u724C:A>K>Q>J>10>9>8>7>6>5>4>3>2;",
    "UINiuZaiXiaZhuQu_content08": "3.\u76F8\u540C\u724C\u578B:\u4F18\u5148\u6BD4\u8F83\u6700\u5927\u5355\u724C,\u76F8\u540C\u5219\u4F9D\u6B21\u5411\u4E0B\u7EE7\u7EED\u6BD4\u8F83,\u59825\u5F20",
    "UINiuZaiXiaZhuQu_content09": "\u724C\u76F8\u540C,\u5219\u4E3A\u5E73\u5C40;",
    "UINiuZaiInsurance_titleThree": "\u7206\u5E84\u89C4\u5219",
    "UINiuZaiXiaZhuQu_content011": "\u5E84\u5BB6\u5269\u4F59\u7B79\u7801\u4E0D\u8DB3\u4EE5\u8D54\u4ED8\u6240\u6709\u83B7\u80DC\u73A9\u5BB6\u7684\u8D54\u4ED8\u91CF\u65F6,\u5E84\u5BB6\u6240\u5269",
    "UINiuZaiXiaZhuQu_content012": "\u4F59\u7684\u8BB0\u5206\u5C06\u6309\u6BD4\u4F8B\u5168\u90E8\u5206\u914D\u7ED9\u83B7\u80DC\u73A9\u5BB6,\u5E76\u5728\u7ED3\u7B97\u7ED3\u675F\u540E\u5173\u95ED\u623F",
