    "Mahjong_RuleTitle1": "\u57FA\u7840\u73A9\u6CD5",
    "Mahjong_RuleContent1_1": "\u56DB\u5DDD\u9EBB\u5C06\u4F7F\u7528\u4E0D\u5305\u542B\u5B57\u724C\uFF08\u5373\u6CA1\u6709\u4E1C\u3001\u5357\u3001\u897F\u3001\u5317\u3001\u4E2D\u3001\u53D1\u3001\u767D\uFF09\u7684108\u5F20\u724C\uFF0C\u53EA\u5305\u62EC1-9\u4E07\u30011-9\u7B52\u30011-9\u6761\u4E09\u8272\u5E8F\u6570\u724C\u540436\u5F20",
    "Mahjong_RuleContent1_2": "\u63B7\u9AB0\u5B50\u786E\u5B9A\u5E84\u5BB6\uFF0C\u540E\u7EED\u7531\u80E1\u724C\u8005\u5750\u5E84\uFF0C\u4E00\u70AE\u591A\u54CD\u5219\u653E\u70AE\u8005\u4E3A\u5E84\uFF0C\u5982\u679C\u6D41\u5C40\u5219\u5E84\u5BB6\u8FDE\u5E84",
    "Mahjong_RuleContent1_3": "\u6BCF\u540D\u73A9\u5BB6\u8D77\u624B\u629313\u5F20\u724C\uFF0C\u5E84\u5BB6\u591A\u4E00\u5F20\u4E3A14\u5F20",
    "Mahjong_RuleContent1_4": "\u53EF\u78B0\u3001\u53EF\u6760\uFF0C\u4E0D\u53EF\u5403",
    "Mahjong_RuleTitle2": "\u80E1\u724C\u89C4\u5219",
    "Mahjong_RuleContent2_1": "\u53EF\u70B9\u70AE\u80E1\uFF0C\u62A2\u6760\u80E1\uFF0C\u652F\u6301\u4E00\u70AE\u591A\u54CD\u3002\u5FC5\u987B\u7F3A\u95E8\uFF0C\u5728\u8840\u6218\u5230\u5E95\u4E2D\uFF0C\u73A9\u5BB6\u5FC5\u987B\u201C\u7F3A\u4E00\u95E8\u201D\uFF0C\u5373\u4E0D\u80FD\u6709\u67D0\u4E00\u95E8\u82B1\u8272\u7684\u724C\uFF0C\u786E\u4FDD\u80E1\u724C\u65F6\u624B\u4E0A\u53EA\u5269\u4E0B\u4E24\u95E8\u82B1\u8272",
    "Mahjong_RuleContent2_2": "\u5728\u8840\u6218\u5230\u5E95\u6A21\u5F0F\u4E0B\uFF0C\u4E00\u5BB6\u80E1\u724C\u540E\uFF0C\u5269\u4F59\u73A9\u5BB6\u7EE7\u7EED\u6E38\u620F\uFF0C\u76F4\u5230\u4E09\u5BB6\u80E1\u724C\u6216\u8005\u6D41\u5C40\u4E3A\u6B62\u3002\u80E1\u724C\u8005\u6536\u53D6\u70B9\u70AE\u8005\u7684\u5206\u6570\uFF0C\u81EA\u6478\u5219\u5176\u4ED6\u4E09\u5BB6\u5747\u652F\u4ED8\uFF0C\u5DF2\u7ECF\u80E1\u724C\u7684\u73A9\u5BB6\u4E0D\u5728\u53C2\u4E0E\u724C\u5C40\uFF0C\u53EF\u4EE5\u81EA\u7531\u79BB\u5F00\u3002",
    "Mahjong_RuleTitle3": "\u6362\u4E09\u5F20",
    "Mahjong_RuleContent3_1": "\u53D1\u5B8C\u624B\u724C\u540E\uFF0C\u6BCF\u4F4D\u73A9\u5BB6\u9009\u62E93\u5F20\u540C\u82B1\u8272\u7684\u724C\uFF0C\u968F\u673A\u4E0E\u5176\u5B831\u4F4D\u73A9\u5BB6\u4EA4\u6362\uFF1B",
    "Mahjong_RuleContent3_2": "\u6362\u4E09\u5F20\u662F\u5176\u4E2D\u7684\u4E00\u4E2A\u73A9\u6CD5\uFF0C\u53EF\u9009\u62E9\u548C\u4E0D\u9009\u62E9\u8FD9\u4E2A\u6A21\u5F0F",
    "Mahjong_RuleContent3_3": "\u6362\u4E09\u5F20\u89E6\u53D1\u597D\u724C\u76F4\u63A5\u8DF3\u8FC7\u6362\u4E09\u5F20\uFF0C\u89E6\u53D1\u6761\u4EF6\u4E3A\u5176\u4E2D2\u4E2A\u82B1\u8272\u724C\u578B\u5C11\u4E8E3\u5F20\uFF1B",
    "Mahjong_RuleTitle4": "\u7F3A\u4E00\u95E8",
    "Mahjong_RuleContent4_1": "\u53D1\u5B8C\u624B\u724C\u540E\uFF0C\u73A9\u5BB6\u9700\u8981\u901A\u8FC7\u8D77\u624B\u724C\u51B3\u5B9A\u5E76\u6253\u51FA\u4E00\u79CD\u82B1\u8272\uFF08\u7B52\u3001\u6761\u3001\u4E07\uFF09\u7684\u724C\u4F5C\u4E3A\u201C\u7F3A\u201D\uFF0C\u610F\u5473\u7740\u5728\u6574\u4E2A\u6E38\u620F\u8FC7\u7A0B\u4E2D\uFF0C\u73A9\u5BB6\u5FC5\u987B\u820D\u5F03\u8BE5\u95E8\u82B1\u8272\u7684\u6240\u6709\u724C\uFF0C\u53EA\u7528\u5269\u4E0B\u7684\u4E24\u95E8\u82B1\u8272\u6765\u7EC4\u5408\u80E1\u724C\uFF1B",
    "Mahjong_RuleContent4_2": "\u8FD9\u4E2A\u5728\u80E1\u724C\u4EE5\u53CA\u6478\u5B8C\u6240\u6709\u624B\u724C\u524D\u662F\u53EF\u4EE5\u968F\u610F\u8C03\u6574\u7684\uFF0C\u548C\u201C\u5B9A\u7F3A\u201D\u4E0D\u4E00\u6837",
    "Mahjong_RuleTitle5": "\u5B9A\u7F3A",
